/* 自动生成，请勿手工修改。来源：DSH physics/phy-experiment；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"phy-experiment-1","title":"基本测量与读数规范：刻度尺、停表、温度计、天平、量筒、弹簧测力计","subtitle":"实验操作考试 · 必做实验 · all","grade":"all","tags":["实验操作考试 · 必做实验"],"blocks":[{"type":"note","title":"教材位置","text":"实验操作考试 · 必做实验 · all"},{"type":"note","title":"问题切入","text":"两位同学用同一把刻度尺量同一根铅笔，一个写 6.8 cm、一个写 6.80 cm，谁的写法规范？温度计刚从水里拿出来，示数为什么变小了？托盘天平如果游码没有归零就开始称量，测出的质量会偏大还是偏小？"},{"type":"note","title":"一句话抓住关键","text":"任何一次测量都走同一套顺序：先看量程与分度值，再调零或调平，然后按规范操作，最后按分度值决定读到哪一位并写上单位。位数与顺序错了，读数就是错的，这也是评委最容易扣分的地方。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"量身高、称体重、看时间，每一样都有「怎么量才准」的规矩。实验题丢分，多半不是不会算，而是没按规矩读。","walk":["先看量程和分度值，确定能量多大、该读到哪一位。","再调零或调平：天平放平、游码归零、指针指中央，温度计看清零刻度。","最后按规则读数并写单位；刻度尺要估读到分度值的下一位。"],"try":"用刻度尺量课本的厚度，估读到 0.1 mm，换三个位置各量一次并比较。","use":["天平：左物右码，用镊子夹砝码。","量筒：视线与凹液面最低处相平。"]},{"type":"h","text":"先看现象：同一把尺子，两次读出的位数不一样"},{"type":"p","text":"把物体的一端对准刻度尺的零刻度线，另一端落在 1.4 cm 这条刻度线上。这时不能只写 1.4 cm：刻度尺上 1 cm 与 2 cm 之间有 10 个小格，每一个小格代表 1 mm，这就是这把尺的分度值。分度值是 1 mm 时，准确值读到 0.1 cm，还要用眼睛把这一小格再分成十份，估读出 0.01 cm 这一位，所以规范写法是 1.40 cm。测量结果由准确值、估读值和单位三部分组成，末位的 0 不是多余的，它表示估读到了 0.1 mm 这一位。"},{"type":"figure","figure":{"id":"fig-exp-basic-ruler-1","title":"刻度尺的读数：准确值加估读值","caption":"分度值 1 mm，物体长 1.4 cm，规范读数要写到 1.40 cm","view":"wide","alt":"一把分度值为 1 毫米的刻度尺，物体左端与零刻度线对齐，右端正好落在 1.4 厘米的刻度线上","prims":[{"t":"text","x":50,"y":8,"text":"读数时视线要正对刻度线","size":3.8,"tone":"muted"},{"t":"rect","x":10,"y":18,"w":56,"h":10,"fill":true,"tone":"main","label":"物体"},{"t":"rect","x":10,"y":30,"w":80,"h":10,"tone":"main"},{"t":"line","x1":10,"y1":30,"x2":10,"y2":38},{"t":"line","x1":50,"y1":30,"x2":50,"y2":38},{"t":"line","x1":90,"y1":30,"x2":90,"y2":38},{"t":"line","x1":14,"y1":30,"x2":14,"y2":34},{"t":"line","x1":18,"y1":30,"x2":18,"y2":34},{"t":"line","x1":22,"y1":30,"x2":22,"y2":34},{"t":"line","x1":26,"y1":30,"x2":26,"y2":34},{"t":"line","x1":30,"y1":30,"x2":30,"y2":34},{"t":"line","x1":34,"y1":30,"x2":34,"y2":34},{"t":"line","x1":38,"y1":30,"x2":38,"y2":34},{"t":"line","x1":42,"y1":30,"x2":42,"y2":34},{"t":"line","x1":46,"y1":30,"x2":46,"y2":34},{"t":"line","x1":54,"y1":30,"x2":54,"y2":34},{"t":"line","x1":58,"y1":30,"x2":58,"y2":34},{"t":"line","x1":62,"y1":30,"x2":62,"y2":34},{"t":"line","x1":66,"y1":30,"x2":66,"y2":34},{"t":"line","x1":70,"y1":30,"x2":70,"y2":34},{"t":"line","x1":74,"y1":30,"x2":74,"y2":34},{"t":"line","x1":78,"y1":30,"x2":78,"y2":34},{"t":"line","x1":82,"y1":30,"x2":82,"y2":34},{"t":"line","x1":86,"y1":30,"x2":86,"y2":34},{"t":"line","x1":66,"y1":18,"x2":66,"y2":30,"dashed":true,"tone":"accent"},{"t":"line","x1":10,"y1":18,"x2":10,"y2":30,"dashed":true,"tone":"accent"},{"t":"text","x":10,"y":44,"text":"0","size":3.6},{"t":"text","x":50,"y":44,"text":"1","size":3.6},{"t":"text","x":90,"y":44,"text":"2","size":3.6},{"t":"text","x":50,"y":51,"text":"单位：cm；分度值 1 mm；读数 1.40 cm","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"读数前先确认两件事：零刻度线在哪里、分度值是多少。若零刻度线已经磨损，可以从另一条完整的刻度线量起，最后用末端读数减去起点读数。"},{"type":"h","text":"抓住哪个量：分度值决定读到哪一位"},{"type":"p","text":"分度值是相邻两条刻度线之间代表的量，它决定了读数的末位在哪一位上。初中阶段的读数要求分成两类：刻度尺必须估读到分度值的下一位；温度计（分度值 1 ℃）、量筒（50 mL 量筒分度值 1 mL）、托盘天平（感量 0.2 g）、弹簧测力计（分度值 0.2 N）读到分度值所在的那一位即可。所以看到示数先在心里写出分度值，再决定写几位小数：量筒读到 42 mL 就写 42 mL，写成 42.0 mL 是把仪器说精了，写成 42.00 mL 更是没有依据。"},{"type":"figure","figure":{"id":"fig-exp-basic-value-1","title":"两种读数要求：估读与不估读","caption":"刻度尺要往下估读一位，量筒与温度计读到分度值所在位","view":"wide","alt":"左边是 50 毫升量筒中水面在 42 毫升处，右边是分度值 1 摄氏度的温度计液柱示意","prims":[{"t":"beaker","x":14,"y":12,"w":22,"h":42,"fill":0.84},{"t":"line","x1":36,"y1":12,"x2":42,"y2":12},{"t":"line","x1":36,"y1":20.4,"x2":42,"y2":20.4},{"t":"line","x1":36,"y1":28.8,"x2":42,"y2":28.8},{"t":"line","x1":36,"y1":37.2,"x2":42,"y2":37.2},{"t":"line","x1":36,"y1":45.6,"x2":42,"y2":45.6},{"t":"line","x1":36,"y1":54,"x2":42,"y2":54},{"t":"text","x":44,"y":12,"text":"50","anchor":"start","size":3.4},{"t":"text","x":44,"y":20.4,"text":"40","anchor":"start","size":3.4},{"t":"text","x":44,"y":28.8,"text":"30","anchor":"start","size":3.4},{"t":"text","x":44,"y":37.2,"text":"20","anchor":"start","size":3.4},{"t":"text","x":44,"y":45.6,"text":"10","anchor":"start","size":3.4},{"t":"text","x":44,"y":54,"text":"0","anchor":"start","size":3.4},{"t":"text","x":25,"y":59,"text":"量筒：读到分度值 1 mL","size":3.6,"tone":"accent"},{"t":"thermometer","x":74,"y":12,"h":36,"value":0.7,"label":"温度计"},{"t":"text","x":74,"y":57,"text":"温度计：读到分度值 1 ℃","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"常见失分：把刻度尺的估读位省掉（1.40 cm 写成 1.4 cm），或者给不需要估读的仪器多写一位（42 mL 写成 42.0 mL）。"},{"type":"h","text":"温度计：玻璃泡全部浸入，读数时留在液体中"},{"type":"p","text":"测液体温度时，玻璃泡要全部浸入被测液体，既不能碰到容器底，也不能碰到容器壁，否则测到的是容器或热源附近的温度，而不是液体的温度。要等到示数稳定后再读数，读数时玻璃泡必须继续留在液体中，视线与温度计中液柱的上表面相平。把温度计取出来再读，玻璃泡上的液体蒸发吸热，玻璃泡温度下降，示数会偏小。"},{"type":"figure","figure":{"id":"fig-exp-basic-thermo-1","title":"测水温时的正确做法","caption":"玻璃泡全部浸入、不碰壁不碰底；读数时温度计留在液体中","view":"wide","alt":"烧杯里盛有水，温度计的玻璃泡浸没在水中且不接触杯底杯壁，视线水平地与液柱上表面相平","prims":[{"t":"beaker","x":30,"y":28,"w":32,"h":28,"fill":0.65,"label":"水"},{"t":"thermometer","x":46,"y":12,"h":38,"value":0.72},{"t":"arrow","x1":86,"y1":26,"x2":60,"y2":26,"tone":"accent","label":"视线"},{"t":"text","x":20,"y":14,"text":"玻璃泡不碰壁、不碰底","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":46,"y":62,"text":"读数时温度计留在液体中，示数稳定后再读","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"体温计可以离开人体读数，是因为它的玻璃管里有一段极细的缩口，液柱不会自动流回玻璃泡。这一点与普通温度计不同，不要混用。"},{"type":"h","text":"托盘天平：放平、游码归零、先调平再称量"},{"type":"p","text":"使用天平有一条固定顺序：把天平放在水平台上；把游码移到标尺左端的零刻度线处；调节横梁两端的平衡螺母，使指针指在分度盘中央，指针偏左就把螺母向右调、偏右就往左调；左盘放物体，右盘放砝码，用镊子夹取，先加质量大的再加小的，最后移动游码使横梁重新平衡；读数等于右盘砝码总质量加上游码所对的刻度值；称量完毕把砝码放回盒中、游码归零。如果开始称量前游码没有归零，调出的零点是带着一个额外质量的零点，测出的质量会偏大。"},{"type":"figure","figure":{"id":"fig-exp-basic-balance-1","title":"托盘天平的使用顺序","caption":"放平、游码归零、调平衡螺母、左物右码、用镊子夹取砝码","view":"wide","alt":"托盘天平的横梁水平平衡，左盘放物体、右盘放砝码，游码标尺的游码停在零刻度线附近","prims":[{"t":"lever","x1":20,"y1":14,"x2":80,"y2":14,"pivot":0.5,"label":"支点"},{"t":"arc","cx":30,"cy":15,"r":9,"from":200,"to":340},{"t":"arc","cx":70,"cy":15,"r":9,"from":200,"to":340},{"t":"rect","x":22,"y":22,"w":16,"h":7,"fill":true,"tone":"main","label":"物体"},{"t":"rect","x":62,"y":22,"w":16,"h":7,"fill":true,"tone":"accent","label":"砝码"},{"t":"line","x1":50,"y1":17,"x2":50,"y2":30},{"t":"text","x":50,"y":34,"text":"指针指中央","size":3.4,"tone":"muted"},{"t":"rect","x":30,"y":38,"w":40,"h":4,"tone":"main","label":"游码标尺"},{"t":"text","x":50,"y":48,"text":"读数 = 砝码总质量 + 游码示数","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"称量过程中只能加减砝码、移动游码，不能再动平衡螺母","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"天平调平分两个阶段：称量前用平衡螺母调，称量过程中只能加减砝码与移动游码。用手拿砝码会污染、腐蚀砝码，必须用镊子。"},{"type":"h","text":"量筒：视线与凹液面的最低处相平"},{"type":"p","text":"水和大多数液体在量筒里由于表面张力会形成中间低、边缘高的凹液面，读数的位置应当是凹液面的最低处，量筒的刻度就是按它标定的。读数时把量筒放在水平桌面上，视线与凹液面最低处保持水平：俯视时视线斜向下，看到的刻度偏上，读数偏大；仰视时视线斜向上，看到的刻度偏下，读数偏小。用量筒测固体体积时用两次读数相减，固体必须完全浸没、不吸水、不溶于水。"},{"type":"figure","figure":{"id":"fig-exp-basic-cylinder-1","title":"量筒读数的视线","caption":"视线与凹液面最低处相平；俯视读大、仰视读小","view":"wide","alt":"量筒中液面呈凹形，水平的视线对准凹液面最低处，另外两条虚线表示俯视与仰视时的错误视线","prims":[{"t":"beaker","x":36,"y":12,"w":22,"h":42,"fill":0.6,"label":"量筒"},{"t":"arrow","x1":88,"y1":28.8,"x2":60,"y2":28.8,"tone":"accent","label":"视线"},{"t":"arrow","x1":84,"y1":8,"x2":58,"y2":28.8,"dashed":true,"tone":"danger","label":"俯视读大"},{"t":"arrow","x1":84,"y1":50,"x2":58,"y2":28.8,"dashed":true,"tone":"danger","label":"仰视读小"},{"t":"text","x":47,"y":22,"text":"凹液面最低处","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"50 mL 量筒分度值 1 mL，读到 1 mL","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"量筒是量器不是反应容器：不能加热，也不能在量筒里溶解固体或稀释液体。"},{"type":"h","text":"弹簧测力计与停表：校零、沿轴线方向、读对末位"},{"type":"p","text":"弹簧测力计使用前要校零：看指针是否指在零刻度线上，不在就要调到零位；同时看清量程与分度值，所测的力不能超过量程。测量时让弹簧的轴线方向与所测力的方向在同一条直线上，使弹簧能自由伸缩，不要让它与外壳摩擦或让指针被卡住。读数时视线正对刻度线，结果带单位（N）。用弹簧测力计沿水平方向匀速拉动木块测滑动摩擦力时，示数才等于摩擦力。停表读数时先看小盘（分钟），再看大盘（秒），分度值 0.1 s，读到 0.1 s 即可。"},{"type":"figure","figure":{"id":"fig-exp-basic-spring-1","title":"弹簧测力计的使用","caption":"先校零，再沿轴线方向拉，读数时视线正对刻度线","view":"wide","alt":"弹簧测力计的外壳内弹簧被向下拉伸，指针指在 2.4 牛顿的刻度线上，拉力沿弹簧的轴线方向","prims":[{"t":"rect","x":42,"y":8,"w":14,"h":42,"tone":"main"},{"t":"spring","x1":49,"y1":12,"x2":49,"y2":32,"coils":7},{"t":"line","x1":49,"y1":32,"x2":49,"y2":44},{"t":"arrow","x1":49,"y1":44,"x2":49,"y2":54,"tone":"accent","label":"F"},{"t":"line","x1":56,"y1":26,"x2":62,"y2":26,"tone":"accent"},{"t":"text","x":64,"y":26,"text":"2.4 N","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":22,"y":14,"text":"使用前指针先校零","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"拉力沿弹簧轴线方向，视线正对刻度线","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"把测力计倒过来使用，会把外壳或挂钩本身的重力也算进示数里，读数偏大，属于不规范操作。"},{"type":"h","text":"停表：先看小盘判「哪一圈」，再看大盘读秒"},{"type":"p","text":"机械停表有两个盘：小盘记分钟（一圈 15 min，每半格 0.5 min），大盘记秒（一圈只有 30 s，分度值 0.1 s）。读数顺序是先看小盘：指针过了几条半格线，就说明大盘已经转过几圈；再看大盘读出秒数，把两部分相加。以本图为例，小盘指针停在 1 与 2 之间的半格线上（即 1.5 min = 90 s），大盘指针指在 10.4 s 处，所以读数是 90 s + 10.4 s = 100.4 s，也就是 1 min 40.4 s。如果只读大盘的 10.4 s 就错了——小盘已经过了半格，说明大盘已经多转了一整圈。"},{"type":"figure","figure":{"id":"fig-exp-basic-stopwatch-1","title":"停表的双盘读数","caption":"小盘示数 1.5 min、大盘示数 10.4 s，读数 = 90 s + 10.4 s = 100.4 s","view":"square","alt":"一块机械停表：小盘指针停在 1 与 2 之间的半格线上，大盘指针指在 10.4 秒的位置，大盘一圈为 30 秒","prims":[{"t":"stopwatch","x":50,"y":50,"r":30,"minute":1.5,"second":10.4},{"t":"text","x":50,"y":94,"text":"大盘一圈 30 s，分度值 0.1 s；小盘一圈 15 min","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"大盘上的 10.4 s 与 40.4 s 是同一个位置，只有小盘能告诉你该读哪一个：小盘没过半格读 0—30 s，过了半格读 30—60 s。使用前要检查指针是否在零位，按表要按到底再松手，否则指针回零不彻底，每次计时都带一个固定误差。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["测量结果的组成","l = l_(准确) + l_(估读)","长度单位 m、cm、mm；估读位由分度值决定 · 只适用于需要估读的刻度尺。写法必须与分度值匹配：分度值 1 mm 的刻度尺，准确值读到 0.1 cm，估读位在 0.01 cm 上，所以 1.40 cm 才规范。温度计、量筒、天平、弹簧测力计初中不要求估读，写到分度值所在位即可，多写一位是把仪器说精了。"],["累积法（以多测少）","d = (L)/(n)","L 为总长度（cm、mm），n 为份数，d 为一份的长度 · 适用于被测长度小于分度值、或直接测量误差过大的情形（纸的厚度、细丝直径、硬币厚度）。条件是被测物体必须相同、叠放整齐并压紧，总长度要读到刻度尺的估读位；松散或数量数错，结果都会跟着错。"],["差值法测体积","V = V₂ - V₁","V₁ 为放入物体前液体体积，V₂ 为放入后液体与物体的总体积，单位 mL（1 mL = 1 cm³） · 适用于形状不规则、不吸水、不溶于水的固体（排水法）。两次读数都要把量筒放平、视线与凹液面最低处相平；物体要完全浸没，且不能接触容器壁和底。物体吸水或漂浮（如木块）时这个式子不成立，要用针压法或沉坠法另作处理。"],["天平读数","m = m_(砝码) + m_(游码)","各量单位统一为 g · 适用于左物右码的规范操作，且称量前游码已归零、横梁已调平。若游码没有归零就开始称量，零点本身带着一个额外质量，测出的质量偏大；若放成左码右物，物体质量等于砝码总质量减去游码示数，不能照搬这个式子。"]]},{"type":"h","text":"应用 · 生活应用：体检与厨房里的读数"},{"type":"note","title":"情境","text":"体检时用分度值 1 mm 的身高尺量出身高，体温计读数是 36.8 ℃；厨房里用量杯量 200 mL 水准备煮饭。"},{"type":"note","title":"模型与思路","text":"读数规范只与仪器的分度值有关，与仪器贵不贵、大不大无关：刻度尺要往下估读一位，量杯与体温计读到分度值所在位。"},{"type":"list","title":"解答步骤","items":["身高落在 162.3 cm 与 162.4 cm 两条刻度线之间，准确值取 162.3 cm，再用眼睛估读这一小格，记作 162.32 cm（分度值 1 mm = 0.1 cm，估读位在 0.01 cm）。","体温计的分度值是 0.1 ℃，示数 36.8 ℃ 已经是分度值所在位，不必再估读。","量杯量水时把它放在水平桌面上，视线与凹液面最低处相平，读到 200 mL。"]},{"type":"figure","figure":{"id":"fig-exp-1-read-daily","title":"读数三件事：先看量程与分度值，再读数值","caption":"体温计分度值 0.1 ℃、读数 36.8 ℃；量杯的分度值决定读到哪一位（200 mL 是液面与 200 刻度线相平）","view":"wide","alt":"左边是一支体温计，液柱停在 36.8 摄氏度附近并标注读数；右边是一个量杯，液面与 200 毫升刻度线相平，标出读数与分度值","prims":[{"t":"thermometer","x":20,"y":12,"h":56,"value":0.62,"label":"体温计"},{"t":"text","x":20,"y":76,"text":"读数 36.8 ℃，分度值 0.1 ℃","size":3.4,"tone":"accent","anchor":"middle"},{"t":"rect","x":58,"y":16,"w":26,"h":52,"tone":"muted"},{"t":"rect","x":61,"y":36,"w":20,"h":29,"tone":"accent","fill":true},{"t":"line","x1":58,"y1":36,"x2":84,"y2":36,"tone":"accent","width":0.6},{"t":"line","x1":84,"y1":20,"x2":89,"y2":20,"tone":"muted","width":0.3},{"t":"line","x1":84,"y1":30,"x2":89,"y2":30,"tone":"muted","width":0.3},{"t":"line","x1":84,"y1":40,"x2":89,"y2":40,"tone":"muted","width":0.3},{"t":"line","x1":84,"y1":50,"x2":89,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":84,"y1":60,"x2":89,"y2":60,"tone":"muted","width":0.3},{"t":"text","x":92,"y":38,"text":"200 mL","size":3.4,"tone":"accent","anchor":"end"},{"t":"text","x":71,"y":76,"text":"读数 200 mL，分度值 20 mL","size":3.4,"tone":"accent","anchor":"middle"},{"t":"text","x":50,"y":88,"text":"读数 = 数值 + 单位；分度值决定估读到哪一位","size":3.6,"tone":"main","anchor":"middle"}]}},{"type":"note","title":"结论","text":"同一句「读数」，位数由分度值决定：1 mm 的尺读到 0.01 cm，0.1 ℃ 的体温计读到 0.1 ℃，1 mL 的量杯读到 1 mL。位数写错，即使数值接近也算读数不规范。"},{"type":"h","text":"应用 · 实验应用：用累积法测一张纸的厚度"},{"type":"note","title":"情境","text":"一张纸的厚度比刻度尺的分度值（1 mm）小得多，直接测量连估读位都读不出来。"},{"type":"note","title":"模型与思路","text":"把几张相同的纸叠紧压平，量出总厚度 L，再用 d = L/n 求一张的厚度。这是以多测少的累积法，误差被平均到每一张上。"},{"type":"list","title":"解答步骤","items":["取 500 张同样的纸叠整齐、压紧，用分度值 1 mm 的刻度尺量得总厚度为 5.00 cm。","按 d = L/n 计算：5.00 cm ÷ 500 = 0.01 cm。","换算单位：0.01 cm = 0.1 mm，与刻度尺的估读位一致。","答：一张纸的厚度约 0.1 mm。"]},{"type":"note","title":"结论","text":"累积法的关键是「相同、叠紧、压平」：纸叠松散时总厚度偏大，算出的单张厚度就跟着偏大。"},{"type":"h","text":"应用 · 实验应用：天平称量与读数"},{"type":"note","title":"情境","text":"称量一个金属块，右盘中放入 50 g、20 g、5 g 三个砝码，游码移到 2.4 g 处时横梁平衡。"},{"type":"note","title":"模型与思路","text":"天平读数等于右盘砝码总质量加上游码所对的刻度值；标尺感量 0.2 g，游码示数只能取 0.2 g 的整数倍。"},{"type":"list","title":"解答步骤","items":["先读砝码：50 g + 20 g + 5 g = 75 g。","再读游码：游码左侧所对的刻度为 2.4 g（2.4 g 是 0.2 g 的整数倍，可以读到）。","相加：m = 75 g + 2.4 g = 77.4 g。"]},{"type":"figure","figure":{"id":"fig-exp-1-balance-app","title":"天平的读数：砝码总质量 + 游码示数","caption":"左盘放物体、右盘加砝码，横梁平衡后读数 = 右盘砝码总质量 + 游码所对的刻度值；标尺感量 0.2 g，游码示数只能取 0.2 g 的整数倍","view":"wide","alt":"托盘天平示意图：左盘放着被测物体，右盘放着两个砝码，横梁下方是带游码的标尺，游码停在标尺的某个刻度处","prims":[{"t":"rect","x":26,"y":52,"w":48,"h":5,"tone":"muted","fill":true},{"t":"rect","x":48,"y":30,"w":4,"h":22,"tone":"muted","fill":true},{"t":"line","x1":22,"y1":30,"x2":78,"y2":30,"tone":"main","width":1},{"t":"line","x1":50,"y1":30,"x2":50,"y2":40,"tone":"muted","dashed":true},{"t":"line","x1":22,"y1":30,"x2":22,"y2":38,"tone":"muted","width":0.5},{"t":"line","x1":14,"y1":38,"x2":30,"y2":38,"tone":"muted","width":0.8},{"t":"line","x1":78,"y1":30,"x2":78,"y2":38,"tone":"muted","width":0.5},{"t":"line","x1":70,"y1":38,"x2":86,"y2":38,"tone":"muted","width":0.8},{"t":"rect","x":17,"y":32,"w":10,"h":6,"tone":"accent","fill":true},{"t":"text","x":22,"y":28,"text":"被测物体","size":3.2,"tone":"accent","anchor":"middle"},{"t":"rect","x":71,"y":32,"w":6,"h":6,"tone":"main","fill":true},{"t":"rect","x":79,"y":32,"w":6,"h":6,"tone":"main","fill":true},{"t":"text","x":78,"y":28,"text":"砝码","size":3.2,"tone":"main","anchor":"middle"},{"t":"rect","x":30,"y":46,"w":34,"h":4,"tone":"muted"},{"t":"line","x1":32,"y1":46,"x2":32,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":36,"y1":46,"x2":36,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":40,"y1":46,"x2":40,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":44,"y1":46,"x2":44,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":48,"y1":46,"x2":48,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":52,"y1":46,"x2":52,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":56,"y1":46,"x2":56,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":60,"y1":46,"x2":60,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":64,"y1":46,"x2":64,"y2":50,"tone":"muted","width":0.3},{"t":"rect","x":58,"y":44.6,"w":3,"h":6.8,"tone":"danger","fill":true},{"t":"text","x":64,"y":50,"text":"标尺与游码","size":3.2,"tone":"muted","anchor":"start"},{"t":"text","x":50,"y":62,"text":"m = 砝码总质量 + 游码示数","size":3.6,"tone":"accent","anchor":"middle"}]}},{"type":"note","title":"结论","text":"金属块的质量是 77.4 g。若物体和砝码放反了（左码右物），物体质量等于砝码总质量减去游码示数。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["读数时 1.4 cm 与 1.40 cm 是同一个结果，随便写一个就行","分度值 1 mm 的刻度尺必须写成 1.40 cm，末位的 0 是估读位，不能省","末位的 0 表示估读到了 0.1 mm 这一位。省掉它，等于把测量仪器的精度说低了一档，也说明操作者没有做估读这一步。"],["用量筒读液体体积时，视线要与凹液面的最高处（边缘）相平","视线要与凹液面的最低处相平","凹液面最低处才是液体真正占据的体积所对应的位置，量筒的刻度正是按它标定的。看边缘的最高处会把读数读大。"],["温度计放进水里后取出来读数，看得更清楚，结果也一样","读数时玻璃泡必须继续留在液体中","取出后玻璃泡上的液体蒸发吸热，玻璃泡温度下降，液柱缩短，示数比液体真实温度偏低。"],["天平放到桌上就可以直接称量，游码在哪个位置都无所谓","先把天平放在水平台上，把游码移到标尺左端零刻度线，调平衡螺母使指针指中央，然后才能称量","游码没有归零时，调出的平衡是带着一个额外质量的零点，这个额外质量会被算进读数里，测出的质量偏大。"],["弹簧测力计使用前不用看指针在哪里，只要记住零误差就行","使用前要检查并调节指针到零刻度线，同时看清量程与分度值","指针不在零位时每次读数的示数都带着同一个零点误差；若把零点误差当成「记住的差值」去修正，稍一疏忽就会算错，而且超过量程还会损坏弹簧。"]]},{"type":"table","title":"估读与不估读（初中阶段各测量仪器的读数要求（先看分度值））","head":["比较项","要估读到分度值的下一位","读到分度值所在位即可"],"rows":[["仪器","刻度尺（分度值 1 mm）","温度计、量筒、托盘天平、弹簧测力计、停表"],["分度值示例","1 mm","1 ℃、1 mL、0.2 g、0.2 N、0.1 s"],["规范读数","1.40 cm（末位 0 是估读位，不能省）","38 ℃、42 mL、77.4 g、2.4 N"],["常见失分","少写估读位（写成 1.4 cm）或多写一位（1.400 cm）","多写一位（把 42 mL 写成 42.0 mL）"]]},{"type":"table","title":"俯视与仰视（视线不正对刻度时读数怎么偏）","head":["比较项","俯视（视线斜向下）","仰视（视线斜向上）"],"rows":[["看到的刻度","看到的刻度偏上，读数偏大","看到的刻度偏下，读数偏小"],["量取液体时","读到 40 mL 就停，实际量到的水少于 40 mL","读到 40 mL 就停，实际量到的水多于 40 mL"],["规范做法","视线与凹液面最低处相平","视线与凹液面最低处相平"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["仪器读数（配图）","给出刻度尺、量筒、温度计、天平、弹簧测力计的图示，要求写出读数。评分通常看三点：位数是否与分度值匹配、刻度尺有没有估读、数值后面有没有单位。做题的固定动作是先在心里写出分度值，再写结果。"],["操作规范判断","列出几种操作让学生判断对错并说明理由，如玻璃泡碰壁、用手拿砝码、游码未归零、测力计未校零、量筒读数时俯视。答题要说清「错在哪里」加上「会带来什么后果（偏大还是偏小）」，只说错不说理由通常拿不到全分。"],["操作顺序与器材选择","以测量任务为背景考查步骤排序与器材选择，要求写出先做什么后做什么，并说明这样排序的理由（避免沾水、避免零点误差、避免损坏仪器）。这是实验操作考试里最容易被整项扣分的部分。"]]},{"type":"quote","text":"【材料一】某小组用量具测量一个金属圆柱体：先用分度值 1 mm 的刻度尺量它的高，再用调节好的托盘天平称它的质量，最后用量筒和水测它的体积。天平的砝码盒里有 100 g、50 g、20 g、20 g、10 g、5 g 的砝码，标尺上的感量为 0.2 g。\n【材料二】使用量筒时，视线要与凹液面的最低处相平。视线斜向下（俯视）时看到的刻度偏上，读数偏大；视线斜向上（仰视）时看到的刻度偏下，读数偏小。若用俯视的方式量取一定体积的液体，读到的体积达到了要求，实际量到的液体却比要求的少。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】金属圆柱体的高落在 3.2 cm 与 3.3 cm 两条刻度线之间，更靠近 3.2 cm。请写出规范读数并说明理由。（3 分）","【设问】称量时右盘放入 50 g 与 20 g 的砝码各一个，游码移到 3.4 g 处时横梁平衡。写出金属圆柱体的质量，并说明天平读数为什么不用再往下估读。（4 分）","【设问】若量取 40 mL 水时视线俯视，读到的体积与实际体积相比偏大还是偏小？实际量到的水比 40 mL 多还是少？请说明理由。（3 分）"]}],"questions":[{"id":"phy-experiment-1-q1","type":"choice","stem":"如图，用分度值为 1 mm 的刻度尺测量一个物体的长度，物体的左端与零刻度线对齐。下列读数中规范的是","answer":"B","explain":"B 规范：分度值 1 mm = 0.1 cm，准确值读 1.4 cm，还要往下估读一位，所以写成 1.40 cm，末位的 0 表示估读到 0.1 mm。A 错：刻度尺必须估读，不能只读到分度值所在位。C 错：估读只需一位，多写的位数没有仪器精度作依据。D 错：测量结果必须带单位，只写数字无法表达测的是什么。","options":["1.4 cm，因为分度值就是 1 mm，读到毫米这一位已经够了","1.40 cm，准确值是 1.4 cm，末位的 0 是估读出来的那一位","1.400 cm，估读的位数越多越准确","1.4，只要数字对，单位可以省"],"difficulty":1,"tags":["刻度尺","估读"],"figure":{"id":"fig-exp-basic-ruler-q1","title":"用分度值 1 mm 的刻度尺测物体长度","caption":"物体右端正好落在 1.4 cm 的刻度线上","view":"wide","alt":"刻度尺的零刻度线对准物体左端，物体右端正好与 1.4 厘米处的刻度线对齐","prims":[{"t":"rect","x":10,"y":18,"w":56,"h":10,"fill":true,"tone":"main","label":"物体"},{"t":"rect","x":10,"y":30,"w":80,"h":10,"tone":"main"},{"t":"line","x1":10,"y1":30,"x2":10,"y2":38},{"t":"line","x1":50,"y1":30,"x2":50,"y2":38},{"t":"line","x1":90,"y1":30,"x2":90,"y2":38},{"t":"line","x1":14,"y1":30,"x2":14,"y2":34},{"t":"line","x1":18,"y1":30,"x2":18,"y2":34},{"t":"line","x1":22,"y1":30,"x2":22,"y2":34},{"t":"line","x1":26,"y1":30,"x2":26,"y2":34},{"t":"line","x1":30,"y1":30,"x2":30,"y2":34},{"t":"line","x1":34,"y1":30,"x2":34,"y2":34},{"t":"line","x1":38,"y1":30,"x2":38,"y2":34},{"t":"line","x1":42,"y1":30,"x2":42,"y2":34},{"t":"line","x1":46,"y1":30,"x2":46,"y2":34},{"t":"line","x1":54,"y1":30,"x2":54,"y2":34},{"t":"line","x1":58,"y1":30,"x2":58,"y2":34},{"t":"line","x1":62,"y1":30,"x2":62,"y2":34},{"t":"line","x1":66,"y1":30,"x2":66,"y2":34},{"t":"line","x1":70,"y1":30,"x2":70,"y2":34},{"t":"line","x1":74,"y1":30,"x2":74,"y2":34},{"t":"line","x1":78,"y1":30,"x2":78,"y2":34},{"t":"line","x1":82,"y1":30,"x2":82,"y2":34},{"t":"line","x1":86,"y1":30,"x2":86,"y2":34},{"t":"line","x1":66,"y1":18,"x2":66,"y2":30,"dashed":true,"tone":"accent"},{"t":"line","x1":10,"y1":18,"x2":10,"y2":30,"dashed":true,"tone":"accent"},{"t":"text","x":10,"y":44,"text":"0","size":3.6},{"t":"text","x":50,"y":44,"text":"1","size":3.6},{"t":"text","x":90,"y":44,"text":"2","size":3.6},{"t":"text","x":50,"y":52,"text":"单位：cm","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-1-q2","type":"choice","stem":"用温度计测量一杯水的温度，下列操作正确的是","answer":"D","explain":"D 正确：示数稳定后，玻璃泡继续留在液体中读数，视线与液柱上表面相平，读到的才是液体的温度。A 错：碰到容器底测到的是容器底附近的温度，不是液体温度。B 错：取出后玻璃泡上的液体蒸发吸热，示数会偏低。C 错：碰到容器壁同样测不到液体的真实温度。","options":["玻璃泡可以接触容器底，只要它全部浸入液体中就行","把温度计从水中取出后再读数，这样看得更清楚","让玻璃泡接触容器壁，读数会更稳定","读数时玻璃泡留在液体中，视线与温度计中液柱的上表面相平"],"difficulty":1,"tags":["温度计"]},{"id":"phy-experiment-1-q3","type":"choice","stem":"用托盘天平称量物体的质量，下列操作正确的是","answer":"A","explain":"A 正确，这是称量前的调平顺序：放平、游码归零、再调平衡螺母。B 错：称量过程中只能加减砝码、移动游码，再动平衡螺母会把已经调好的零点破坏掉。C 错：手上的汗渍与油脂会污染、腐蚀砝码，改变砝码的质量，必须用镊子夹取。D 错：左码右物时物体质量等于砝码总质量减去游码示数，读数规则不成立。","options":["先把天平放在水平台上，把游码移到标尺左端的零刻度线，再调节平衡螺母使指针指在分度盘中央","称量过程中发现指针偏左，可以调节平衡螺母使它回到中央","为了省时间，可以用手直接拿取砝码","物体放在右盘、砝码放在左盘，读数仍然等于砝码总质量加游码示数"],"difficulty":2,"tags":["托盘天平","操作规范"]},{"id":"phy-experiment-1-q4","type":"choice","stem":"关于量筒与弹簧测力计的使用，下列说法正确的是","answer":"C","explain":"C 正确：量筒读到分度值所在位，50 mL 量筒分度值 1 mL，结果写 42 mL；多写一位是把仪器说精了。A 错：应与凹液面最低处相平，看最高处会把读数读大。B 错：使用前应把指针调到零刻度线，靠心算修正零点误差容易出错。D 错：测量时要让弹簧的轴线方向与所测力的方向在同一条直线上，否则弹簧与外壳摩擦，读数不准。","options":["量筒读数时视线要与凹液面的最高处相平","弹簧测力计的指针不在零刻度线时，只要记住这个差值就不必校零","50 mL 的量筒分度值为 1 mL，读到 42 mL 即可，不必写成 42.0 mL","弹簧测力计可以沿任意方向拉动，读数都一样"],"difficulty":1,"tags":["量筒","弹簧测力计"]},{"id":"phy-experiment-1-q5","type":"fill","stem":"如图，某同学用量筒测量水的体积，量筒的分度值为 1 mL。此时量筒中水的体积是 ______ mL。","answer":"42|42 mL|42mL","explain":"为什么这样读：读数前先看分度值（1 mL），再看凹液面最低处落在哪条刻度线上。图中水面正好在 40 mL 上方第二小格处，所以是 42 mL。量筒不需要估读，写到分度值所在位即可，所以不写 42.0 mL。若视线俯视，读数会偏大；仰视则偏小。","difficulty":1,"tags":["量筒","读数"],"figure":{"id":"fig-exp-basic-cyl-read-1","title":"量筒中水的体积","caption":"视线与凹液面最低处相平，水面在 40 mL 上方第二小格","view":"wide","alt":"量筒的刻度从下到上为 0 到 50 毫升，水面位于 40 毫升刻度上方两小格处，一条水平视线正对凹液面最低处","prims":[{"t":"beaker","x":34,"y":12,"w":24,"h":42,"fill":0.84},{"t":"line","x1":58,"y1":12,"x2":64,"y2":12},{"t":"line","x1":58,"y1":20.4,"x2":64,"y2":20.4},{"t":"line","x1":58,"y1":28.8,"x2":64,"y2":28.8},{"t":"line","x1":58,"y1":37.2,"x2":64,"y2":37.2},{"t":"line","x1":58,"y1":45.6,"x2":64,"y2":45.6},{"t":"line","x1":58,"y1":54,"x2":64,"y2":54},{"t":"text","x":66,"y":12,"text":"50","anchor":"start","size":3.4},{"t":"text","x":66,"y":20.4,"text":"40","anchor":"start","size":3.4},{"t":"text","x":66,"y":28.8,"text":"30","anchor":"start","size":3.4},{"t":"text","x":66,"y":37.2,"text":"20","anchor":"start","size":3.4},{"t":"text","x":66,"y":45.6,"text":"10","anchor":"start","size":3.4},{"t":"text","x":66,"y":54,"text":"0","anchor":"start","size":3.4},{"t":"arrow","x1":92,"y1":18.72,"x2":60,"y2":18.72,"tone":"accent","label":"视线"},{"t":"text","x":46,"y":60,"text":"量筒 50 mL，分度值 1 mL","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-1-q6","type":"fill","stem":"用调节好的托盘天平称量一个小石块，右盘中放入 20 g 和 5 g 的砝码各一个，游码移到标尺上 1.4 g 处时横梁平衡。小石块的质量是 ______ g。","answer":"26.4|26.4 g|26.4g","explain":"为什么这样算：天平读数 = 右盘砝码总质量 + 游码所对刻度值 = 20 g + 5 g + 1.4 g = 26.4 g。游码读数是游码左侧所对的刻度，本题中是 1.4 g，且 1.4 g 是感量 0.2 g 的整数倍，可以读到。若称量前游码没有归零，测出的质量会偏大；若砝码与物体放反，则应改成相减。","difficulty":1,"tags":["托盘天平","计算"],"figure":{"id":"fig-exp-1-balance-q6","title":"天平读数：20 g 与 5 g 砝码 + 游码 1.4 g","caption":"横梁平衡时读数为右盘砝码总质量与游码示数之和：20 g + 5 g + 1.4 g = 26.4 g","view":"wide","alt":"托盘天平示意图：右盘放着一个 20 克的砝码与一个 5 克的砝码，标尺上的游码停在 1.4 克刻度处","prims":[{"t":"rect","x":26,"y":52,"w":48,"h":5,"tone":"muted","fill":true},{"t":"rect","x":48,"y":30,"w":4,"h":22,"tone":"muted","fill":true},{"t":"line","x1":22,"y1":30,"x2":78,"y2":30,"tone":"main","width":1},{"t":"line","x1":50,"y1":30,"x2":50,"y2":40,"tone":"muted","dashed":true},{"t":"line","x1":22,"y1":30,"x2":22,"y2":38,"tone":"muted","width":0.5},{"t":"line","x1":14,"y1":38,"x2":30,"y2":38,"tone":"muted","width":0.8},{"t":"line","x1":78,"y1":30,"x2":78,"y2":38,"tone":"muted","width":0.5},{"t":"line","x1":70,"y1":38,"x2":86,"y2":38,"tone":"muted","width":0.8},{"t":"rect","x":17,"y":32,"w":10,"h":6,"tone":"accent","fill":true},{"t":"text","x":22,"y":28,"text":"小石块","size":3.2,"tone":"accent","anchor":"middle"},{"t":"rect","x":71,"y":32,"w":6,"h":6,"tone":"main","fill":true},{"t":"rect","x":79,"y":32,"w":6,"h":6,"tone":"main","fill":true},{"t":"text","x":78,"y":28,"text":"20 g + 5 g","size":3.2,"tone":"main","anchor":"middle"},{"t":"rect","x":30,"y":46,"w":34,"h":4,"tone":"muted"},{"t":"line","x1":32,"y1":46,"x2":32,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":36,"y1":46,"x2":36,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":40,"y1":46,"x2":40,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":44,"y1":46,"x2":44,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":48,"y1":46,"x2":48,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":52,"y1":46,"x2":52,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":56,"y1":46,"x2":56,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":60,"y1":46,"x2":60,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":64,"y1":46,"x2":64,"y2":50,"tone":"muted","width":0.3},{"t":"rect","x":58,"y":44.6,"w":3,"h":6.8,"tone":"danger","fill":true},{"t":"text","x":64,"y":50,"text":"标尺与游码","size":3.2,"tone":"muted","anchor":"start"},{"t":"text","x":50,"y":62,"text":"m = 20 g + 5 g + 1.4 g = 26.4 g","size":3.6,"tone":"accent","anchor":"middle"}]}},{"id":"phy-experiment-1-q7","type":"short","stem":"一包打印纸共 500 张，用分度值 1 mm 的刻度尺量得整包纸（不含包装）的总厚度为 5.00 cm。求一张纸的厚度，并说明为什么采用这种测量方法。","answer":"一张纸的厚度 d = L/n = 5.00 cm ÷ 500 = 0.01 cm = 0.1 mm。因为一张纸的厚度远小于刻度尺的分度值 1 mm，直接测量连估读位都读不出来，把 500 张纸叠紧量出总厚度再除以张数，误差被平均，结果更可靠。","explain":"为什么这么做：单张纸的厚度比刻度尺的分度值小，测量时读数的绝对误差会占很大的比例。累积法用「总量除以份数」把误差摊薄到 1/500，所以能测出比 1 mm 小得多的厚度。两个易错点：一是纸没有叠紧或没有压平，总厚度偏大，算出的单张厚度偏大；二是张数数错，除以错的数量。","difficulty":2,"tags":["累积法","计算"],"rubric":["写出累积法关系式 d = L/n（1 分）","总厚度与张数配对正确（1 分）","计算结果 0.01 cm，单位正确（1 分）","换算成 0.1 mm 并作答、说明累积法的理由（1 分）"],"steps":["看清分度值：1 mm = 0.1 cm，总厚度记为 5.00 cm（读到 0.01 cm）。","用累积法的关系式 d = L/n。","代入：d = 5.00 cm ÷ 500 = 0.01 cm。","换算单位：0.01 cm = 0.1 mm。","答：一张纸的厚度约为 0.1 mm。"]},{"id":"phy-experiment-1-q8","type":"short","stem":"实验室里有一把零刻度线已经磨损的刻度尺和两块直角三角板。请设计一个方案测出一枚硬币的直径，写出器材、步骤与直径的表达式，并说明零刻度线磨损时该怎么处理。","answer":"器材：刻度尺、两块直角三角板。步骤：① 把硬币平放在水平桌面上；② 用两块三角板的一条直角边从两侧夹紧硬币，使两条直角边互相平行且都与刻度尺垂直；③ 读出这两条直角边在刻度尺上对应的刻度值 l₁ 与 l₂（都从某条完整的刻度线量起，不使用已磨损的零刻度线）；④ 硬币的直径 d = l₂ − l₁。零刻度线磨损后它的位置不再可靠，直接以它为起点，读数会带上一个固定的偏差；改用「末端读数减起点读数」的差值法，两次读数用同一把尺、同一个分度值，这个偏差就被减掉了。","explain":"为什么用两块三角板：硬币是圆的，只用刻度尺直接量，很难保证量到的是直径（圆中最长的弦），量歪了结果就偏小。两块三角板夹紧后两条直角边平行，量到的就是直径。为什么要用差值法：零刻度线磨损后，它的实际位置与标称的零位不再重合，从它量起会带来固定的零点误差；而末端读数减起点读数可以把这同一个误差消掉。另外，读数时视线要正对刻度线，结果要写到 0.01 cm 这一位。","difficulty":3,"tags":["实验设计","刻度尺"],"rubric":["写出器材：刻度尺、两块直角三角板（1 分）","说明夹紧硬币、并使三角板与刻度尺垂直（1 分）","写出差值法的做法与表达式 d = l₂ − l₁（1 分）","说明零刻度线磨损后不能用它的原因（读数会带上固定偏差）（1 分）"]},{"id":"phy-experiment-1-q9","type":"short","stem":"请画出用温度计测量一杯水温度时的正确做法示意图，在图上标出玻璃泡的位置和读数时视线的方向。","answer":"见参考答案图：温度计的玻璃泡全部浸入水中，既不接触容器底也不接触容器壁；读数时玻璃泡留在水中，视线与温度计中液柱的上表面相平。","explain":"作图要点有三条：一是玻璃泡要全部浸在液面以下，并且与杯底、杯壁都留出空隙（碰到杯底或杯壁测到的不是水的温度）；二是温度计要竖直立在水中，不要倾斜碰壁；三是用一条水平箭头表示视线，箭头指向液柱上表面，表示视线与液柱上表面相平。把这三条画出来，就是这道题的得分点。","difficulty":2,"tags":["作图","温度计"],"rubric":["玻璃泡全部浸入水中，且与杯底、杯壁都留有间隙（不碰壁不碰底）","温度计竖直立在水中，没有倾斜碰壁","用水平箭头表示视线，且箭头指向液柱上表面（视线与液柱上表面相平）","图中标出「玻璃泡」与「视线」两处"],"answerFigure":{"id":"fig-exp-basic-thermo-ans1","title":"参考答案：测水温的正确做法","caption":"玻璃泡全部浸入且不碰壁不碰底，视线与液柱上表面相平","view":"wide","alt":"烧杯中盛有水，温度计的玻璃泡全部浸没在水中且与杯底杯壁都有空隙，一条水平箭头表示视线与液柱上表面相平","prims":[{"t":"beaker","x":28,"y":26,"w":34,"h":30,"fill":0.68,"label":"水"},{"t":"thermometer","x":45,"y":10,"h":40,"value":0.7},{"t":"arrow","x1":88,"y1":24,"x2":58,"y2":24,"tone":"accent","label":"视线"},{"t":"text","x":20,"y":12,"text":"玻璃泡全部浸入","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":62,"text":"不碰杯底、不碰杯壁，读数时温度计留在水中","size":3.4,"tone":"accent"}]}},{"id":"phy-experiment-1-q10","type":"choice","stem":"如图是一块机械停表，小盘的指针停在 1 与 2 之间的半格线上，大盘的指针指在 10.4 s 处。此时停表的读数是","answer":"C","explain":"C 正确：小盘指针过了 1 与 2 之间的半格线，说明它已走了 1.5 min = 90 s（大盘转过三整圈），大盘再读 10.4 s，所以读数是 90 s + 10.4 s = 100.4 s，即 1 min 40.4 s。A 错：只读了大盘的示数，漏掉小盘的 90 s——大盘一圈只有 30 s，盘面上 10.4 s 与 40.4 s 位置相同，必须靠小盘判断是哪一圈。B、D 错：把大盘的一圈当成 60 s，机械停表的大盘一圈是 30 s，所以不会出现 30.4 s、40.4 s 这两个读数。","options":["10.4 s","30.4 s","100.4 s","40.4 s"],"difficulty":2,"tags":["停表","读数"],"figure":{"id":"fig-exp-basic-stopwatch-q10","title":"停表的示数是多少","caption":"先看小盘判断大盘是哪一圈，再读大盘的秒数","view":"square","alt":"一块机械停表：小盘指针停在 1 与 2 之间的半格线上（1.5 分钟），大盘指针指在 10.4 秒处","prims":[{"t":"stopwatch","x":50,"y":50,"r":30,"minute":1.5,"second":10.4},{"t":"text","x":50,"y":94,"text":"大盘一圈 30 s","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-1-q11","type":"fill","stem":"再一次用停表计时：小盘的指针指在 0 与 1 之间的半格线上（即 0.5 min），大盘的指针指在 22.6 s 处。这次停表的读数是 ______ s。","answer":"52.6|52.6 s|52.6s|52.6秒","explain":"为什么是 52.6 s 而不是 22.6 s：小盘指针已经过了 0.5 min 的半格线，说明大盘转过了一圈（30 s），再加上大盘读出的 22.6 s，得 30 s + 22.6 s = 52.6 s。判断大盘在哪一圈全靠小盘：没过半格线读 0—30 s，过了半格线读 30—60 s，这正是停表读数最容易错的地方。","difficulty":2,"tags":["停表","读数"],"figure":{"id":"fig-exp-basic-stopwatch-q11","title":"这块停表读作多少秒","caption":"小盘指针过了半格线，大盘读数要加上一整圈 30 s","view":"square","alt":"一块机械停表：小盘指针指在 0 与 1 之间的半格线上（0.5 分钟），大盘指针指在 22.6 秒处","prims":[{"t":"stopwatch","x":50,"y":50,"r":30,"minute":0.5,"second":22.6},{"t":"text","x":50,"y":94,"text":"大盘一圈 30 s","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-1-m1-q1","type":"short","stem":"金属圆柱体的高落在 3.2 cm 与 3.3 cm 两条刻度线之间，更靠近 3.2 cm。请写出规范读数并说明理由。（3 分）","answer":"3.21 cm（估读值在 3.21 cm 附近的合理写法都可以）。刻度尺分度值是 1 mm = 0.1 cm，准确值读 3.2 cm，还要估读一位，估读位在 0.01 cm 上，所以末位必须写出。","explain":"","tags":["读数规范","刻度尺"],"rubric":["写出准确值 3.2 cm（1 分）","补上估读位，结果写到 0.01 cm 这一位（1 分）","结果带上单位 cm（1 分）"]},{"id":"phy-experiment-1-m1-q2","type":"short","stem":"称量时右盘放入 50 g 与 20 g 的砝码各一个，游码移到 3.4 g 处时横梁平衡。写出金属圆柱体的质量，并说明天平读数为什么不用再往下估读。（4 分）","answer":"m = 50 g + 20 g + 3.4 g = 73.4 g。天平标尺的感量是 0.2 g，游码示数只能取 0.2 g 的整数倍（如 3.2 g、3.4 g），读到 0.1 g 位就可以了，初中不要求再把 0.1 g 往下估读。","explain":"","tags":["托盘天平","读数规范"],"rubric":["读出砝码总质量 70 g（1 分）","加上游码示数，得 73.4 g 并带单位（1 分）","写出天平读数规则：读数 = 砝码总质量 + 游码示数（1 分）","说明感量 0.2 g、游码读到 0.1 g 位即可（1 分）"],"figure":{"id":"fig-exp-1-balance-m1","title":"天平读数：50 g 与 20 g 砝码 + 游码 3.4 g","caption":"读数只取「砝码总质量 + 游码示数」，不用再加或再乘任何数：50 g + 20 g + 3.4 g = 73.4 g","view":"wide","alt":"托盘天平示意图：右盘放着一个 50 克的砝码与一个 20 克的砝码，标尺上的游码停在 3.4 克刻度处","prims":[{"t":"rect","x":26,"y":52,"w":48,"h":5,"tone":"muted","fill":true},{"t":"rect","x":48,"y":30,"w":4,"h":22,"tone":"muted","fill":true},{"t":"line","x1":22,"y1":30,"x2":78,"y2":30,"tone":"main","width":1},{"t":"line","x1":50,"y1":30,"x2":50,"y2":40,"tone":"muted","dashed":true},{"t":"line","x1":22,"y1":30,"x2":22,"y2":38,"tone":"muted","width":0.5},{"t":"line","x1":14,"y1":38,"x2":30,"y2":38,"tone":"muted","width":0.8},{"t":"line","x1":78,"y1":30,"x2":78,"y2":38,"tone":"muted","width":0.5},{"t":"line","x1":70,"y1":38,"x2":86,"y2":38,"tone":"muted","width":0.8},{"t":"rect","x":17,"y":32,"w":10,"h":6,"tone":"accent","fill":true},{"t":"text","x":22,"y":28,"text":"金属圆柱体","size":3.2,"tone":"accent","anchor":"middle"},{"t":"rect","x":71,"y":32,"w":6,"h":6,"tone":"main","fill":true},{"t":"rect","x":79,"y":32,"w":6,"h":6,"tone":"main","fill":true},{"t":"text","x":78,"y":28,"text":"50 g + 20 g","size":3.2,"tone":"main","anchor":"middle"},{"t":"rect","x":30,"y":46,"w":34,"h":4,"tone":"muted"},{"t":"line","x1":32,"y1":46,"x2":32,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":36,"y1":46,"x2":36,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":40,"y1":46,"x2":40,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":44,"y1":46,"x2":44,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":48,"y1":46,"x2":48,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":52,"y1":46,"x2":52,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":56,"y1":46,"x2":56,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":60,"y1":46,"x2":60,"y2":50,"tone":"muted","width":0.3},{"t":"line","x1":64,"y1":46,"x2":64,"y2":50,"tone":"muted","width":0.3},{"t":"rect","x":98,"y":44.6,"w":3,"h":6.8,"tone":"danger","fill":true},{"t":"text","x":64,"y":50,"text":"标尺与游码","size":3.2,"tone":"muted","anchor":"start"},{"t":"text","x":50,"y":62,"text":"m = 50 g + 20 g + 3.4 g = 73.4 g","size":3.6,"tone":"accent","anchor":"middle"}]}},{"id":"phy-experiment-1-m1-q3","type":"short","stem":"若量取 40 mL 水时视线俯视，读到的体积与实际体积相比偏大还是偏小？实际量到的水比 40 mL 多还是少？请说明理由。（3 分）","answer":"俯视时视线斜向下，看到的刻度线在液面实际位置的上方，读到的体积偏大。因此当读数显示 40 mL 时就停止加水，实际的水还没有到 40 mL，实际量到的水比 40 mL 少。","explain":"","tags":["量筒","视线"],"rubric":["答出俯视读数偏大（1 分）","说明视线斜向下、看到的刻度偏上（1 分）","推出实际量到的水少于 40 mL（1 分）"]}]},{"id":"phy-experiment-2","title":"测量固体和液体的密度：ρ = m/V 的完整实验流程","subtitle":"实验操作考试 · 必做实验 · all","grade":"all","tags":["实验操作考试 · 必做实验"],"blocks":[{"type":"note","title":"教材位置","text":"实验操作考试 · 必做实验 · all"},{"type":"note","title":"问题切入","text":"27 g 的一小块金属，怎么判断它是铝还是铁？先用量筒测体积、再用天平称质量行不行？为什么教材要求先称质量、后测体积？测液体密度时把量筒里的液体全部倒进烧杯，测出的密度会偏大还是偏小？"},{"type":"note","title":"一句话抓住关键","text":"密度是质量与体积的比值，所以要把「两个量分别怎么测、按什么顺序测」想清楚：顺序错了，质量会被水污染、体积会被残留液体影响，比值跟着错。凡是能重复测量的都要多次测量取平均值。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"测密度就是「称多重、量多大」，但先称还是先量，顺序错了结果就偏。","walk":["固体：先测质量（保持干燥），再排水测体积，避免沾水后质量偏大。","液体：先测总质量，倒出一部分测体积，再测剩余质量，用差值算质量。","ρ = m/V，注意换算 1 g/cm³ = 10³ kg/m³。"],"try":"测一块橡皮的密度：天平称质量，量筒排水测体积，再算比值。","use":["吸水物体：先让它吸饱水，或用「补水量」求体积。","误差分析：先测体积再测质量，会让密度偏大。"]},{"type":"h","text":"先看现象：体积不同，质量与体积的比值却一样"},{"type":"p","text":"两块都是铝的金属块，甲的体积是乙的两倍，它的质量也正好是乙的两倍：甲 m = 54 g、V = 20 cm³，乙 m = 27 g、V = 10 cm³。把质量除以体积，两者都得到 2.7 g/cm³。这说明同种物质的质量与体积的比值是一个定值，这个定值就是密度，用它可以把铝、铁、铜区分开——这也是「鉴别物质」的物理依据。"},{"type":"figure","figure":{"id":"fig-exp-density-1","title":"同种物质的质量与体积成正比","caption":"甲块体积是乙块的两倍，质量也是两倍，比值都是 2.7 g/cm³","view":"wide","alt":"两块大小不同的铝块，甲块体积 20 立方厘米质量 54 克，乙块体积 10 立方厘米质量 27 克，两者的密度都是 2.7 克每立方厘米","prims":[{"t":"text","x":50,"y":8,"text":"同种物质，质量与体积的比值相同","size":3.8,"tone":"muted"},{"t":"rect","x":12,"y":16,"w":28,"h":24,"fill":true,"tone":"main","label":"甲"},{"t":"rect","x":58,"y":26,"w":14,"h":14,"fill":true,"tone":"accent","label":"乙"},{"t":"text","x":26,"y":48,"text":"m = 54 g，V = 20 cm³","size":3.4},{"t":"text","x":26,"y":55,"text":"ρ = 2.7 g/cm³","size":3.4,"tone":"accent"},{"t":"text","x":70,"y":48,"text":"m = 27 g，V = 10 cm³","size":3.4},{"t":"text","x":70,"y":55,"text":"ρ = 2.7 g/cm³","size":3.4,"tone":"accent"}]}},{"type":"note","title":"","text":"密度是物质的一种特性：同种物质在相同状态下密度一般相同，与物体的质量、体积大小无关。不能说「质量越大密度越大」。"},{"type":"h","text":"抓住哪个量：要测的是 m 和 V，不是 ρ"},{"type":"p","text":"密度不能直接测量，要分别测出质量 m 和体积 V，再用 ρ = m/V 算出来。测质量用托盘天平；规则的固体可以用刻度尺量出长、宽、高再算体积；不规则的固体和液体要用50 mL量筒（分度值 1 mL）测体积。把这三个环节画成一条流程，后面所有操作顺序问题都落在这条流程上：先想清楚每一步测什么、用什么测、会不会互相影响。"},{"type":"figure","figure":{"id":"fig-exp-density-2","title":"测密度的三件事","caption":"先测质量，再测体积，最后用 ρ = m/V 计算","view":"wide","alt":"流程图：用天平测质量 m，用量筒或刻度尺测体积 V，再用密度公式计算密度","prims":[{"t":"rect","x":6,"y":22,"w":26,"h":14,"fill":true,"tone":"main","label":"测质量 m"},{"t":"arrow","x1":33,"y1":29,"x2":39,"y2":29,"tone":"accent"},{"t":"rect","x":40,"y":22,"w":26,"h":14,"fill":true,"tone":"main","label":"测体积 V"},{"t":"arrow","x1":67,"y1":29,"x2":73,"y2":29,"tone":"accent"},{"t":"rect","x":74,"y":22,"w":22,"h":14,"fill":true,"tone":"accent","label":"算 ρ"},{"t":"text","x":19,"y":42,"text":"托盘天平","size":3.4,"tone":"muted"},{"t":"text","x":53,"y":42,"text":"量筒或刻度尺","size":3.4,"tone":"muted"},{"t":"text","x":85,"y":42,"text":"ρ = m/V","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":55,"text":"顺序会互相影响：这就是要先想清楚的地方","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"体积单位要配套：1 mL = 1 cm³ = 10⁻⁶ m³，1 g/cm³ = 1×10³ kg/m³。"},{"type":"h","text":"顺序问题：一定先测质量，后测体积"},{"type":"p","text":"先用量筒测体积，石块从水里拿出来时表面会沾水，再放到天平上称，测出的质量就偏大；体积本身没变，于是 ρ = m/V 的结果偏大。所以规范的顺序是先称质量、后测体积：先称质量时石块是干燥的，质量准确；测完体积实验就结束了，即使沾水也不影响结果。这条理由也是实验操作考试里最常问的「为什么」。"},{"type":"figure","figure":{"id":"fig-exp-density-3","title":"顺序错了会怎样","caption":"先测体积：石块沾水，测出的质量偏大，算出的密度偏大","view":"wide","alt":"石块浸在量筒的水中沾上水，箭头指向一个标着质量偏大的方框，表示先测体积再称质量会使密度偏大","prims":[{"t":"beaker","x":14,"y":14,"w":24,"h":30,"fill":0.6},{"t":"circle","cx":26,"cy":38,"r":3.6,"fill":true,"tone":"main"},{"t":"text","x":26,"y":10,"text":"量筒中的石块","size":3.4,"tone":"muted"},{"t":"arrow","x1":42,"y1":28,"x2":56,"y2":28,"tone":"danger","label":"沾水"},{"t":"rect","x":60,"y":21,"w":28,"h":14,"fill":true,"tone":"danger","label":"质量偏大"},{"t":"text","x":74,"y":44,"text":"ρ = m/V 偏大","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":56,"text":"先测体积后称质量：石块沾水，测出的质量偏大","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"若石块会吸水（如砖块、木块），还要先让它吸足水或改用其他方法，否则测出的体积偏小、密度偏大。"},{"type":"h","text":"排水法测不规则固体的体积"},{"type":"p","text":"测小石块这类不规则固体的体积用排水法：先在量筒里倒入适量的水，读出体积 V₁；用细线把石块系好，缓慢放入量筒使它完全浸没，读出总体积 V₂；石块的体积 V = V₂ − V₁。三个细节：水要「适量」——既能浸没石块，放入后又不超过量程；石块要完全浸没且不接触筒壁与筒底；两次读数视线都要与凹液面最低处相平。"},{"type":"figure","figure":{"id":"fig-exp-density-4","title":"排水法测体积","caption":"先读 V₁，再读放入石块后的 V₂，V = V₂ − V₁","view":"wide","alt":"左边量筒中只有 20 毫升水，右边量筒中放入石块后水面升到 30 毫升，两次读数相减得石块体积 10 立方厘米","prims":[{"t":"text","x":50,"y":8,"text":"V = V₂ − V₁ = 30 mL − 20 mL = 10 cm³","size":3.8,"tone":"accent"},{"t":"beaker","x":10,"y":16,"w":22,"h":34,"fill":0.4,"label":"V₁"},{"t":"beaker","x":58,"y":16,"w":22,"h":34,"fill":0.6,"label":"V₂"},{"t":"circle","cx":69,"cy":42,"r":4,"fill":true,"tone":"main","label":"石块"},{"t":"arrow","x1":36,"y1":30,"x2":54,"y2":30,"tone":"accent","label":"放入石块"},{"t":"text","x":21,"y":56,"text":"V₁ = 20 mL","size":3.4},{"t":"text","x":69,"y":56,"text":"V₂ = 30 mL","size":3.4}]}},{"type":"note","title":"","text":"细线的体积很小可以忽略；若石块较大，要用「先放石块再加水到浸没」的方式，避免水溢出影响读数。"},{"type":"h","text":"液体密度：两种方案与误差比较"},{"type":"p","text":"液体不能直接放上天平称，要借助容器。方案一：先称烧杯和液体的总质量 m₁，把一部分液体倒入量筒读出体积 V，再称烧杯和剩余液体的质量 m₂，则液体的密度 ρ = (m₁ − m₂)/V，量筒里那部分液体的质量正好是 m₁ − m₂，没有残留带来的误差。方案二：先称空烧杯的质量 m₀，用量筒量出体积 V 后把液体全部倒入烧杯称总质量 m₂，则 ρ = (m₂ − m₀)/V；但量筒壁上总会残留少量液体，倒进烧杯的液体偏少，质量偏小，算出的密度偏小。所以方案一更好。"},{"type":"figure","figure":{"id":"fig-exp-density-5","title":"测液体密度的两种方案","caption":"方案一用两次质量之差与量筒体积对应，避免残留误差","view":"wide","alt":"上排是方案一的流程：先测总质量，倒出部分液体到量筒，再测剩余质量；下排是方案二的流程：先测空杯质量，量筒测体积后全部倒入再称质量","prims":[{"t":"rect","x":6,"y":12,"w":24,"h":12,"fill":true,"tone":"main","label":"m₁"},{"t":"arrow","x1":31,"y1":18,"x2":37,"y2":18,"tone":"accent"},{"t":"rect","x":38,"y":12,"w":24,"h":12,"fill":true,"tone":"main","label":"倒出部分"},{"t":"arrow","x1":63,"y1":18,"x2":69,"y2":18,"tone":"accent"},{"t":"rect","x":70,"y":12,"w":24,"h":12,"fill":true,"tone":"main","label":"m₂"},{"t":"text","x":50,"y":31,"text":"方案一：ρ = (m₁ − m₂)/V，量筒中的液体就是倒出的那部分","size":3.3,"tone":"accent"},{"t":"rect","x":6,"y":38,"w":24,"h":12,"fill":true,"tone":"muted","label":"m₀（空杯）"},{"t":"arrow","x1":31,"y1":44,"x2":37,"y2":44,"tone":"muted"},{"t":"rect","x":38,"y":38,"w":24,"h":12,"fill":true,"tone":"muted","label":"量筒测 V"},{"t":"arrow","x1":63,"y1":44,"x2":69,"y2":44,"tone":"muted"},{"t":"rect","x":70,"y":38,"w":24,"h":12,"fill":true,"tone":"muted","label":"全部倒入"},{"t":"text","x":50,"y":58,"text":"方案二：量筒壁残留液体，测出的质量偏小、密度偏小","size":3.3,"tone":"danger"}]}},{"type":"note","title":"","text":"判断方案好坏只看一条：算式里的质量与体积是不是严格对应「同一部分液体」。对应得上就没有残留误差。"},{"type":"h","text":"数据记录、平均值与 m-V 图像"},{"type":"p","text":"数据要记成表格：表头写清物理量与单位，如「质量 m/g」「体积 V/cm³」「密度 ρ/(g·cm⁻³)」，同一物体测三次取平均值以减小偶然误差。还可以用图像法处理数据：以体积 V 为横轴、质量 m 为纵轴描点连线，同种物质（状态不变）的点落在一条过原点的直线上，直线的斜率就是密度。图像法的好处是一眼能看出规律，也能发现某次数据明显偏离直线的错误。"},{"type":"figure","figure":{"id":"fig-exp-density-6","title":"质量—体积图像","caption":"同种物质的 m-V 图像是一条过原点的直线，斜率等于密度","view":"square","alt":"以体积为横轴、质量为纵轴的坐标图，一条过原点的倾斜直线经过体积 10、20、30 立方厘米对应质量 27、54、81 克的数据点","prims":[{"t":"axis","x":20,"y":84,"w":72,"h":64,"xLabel":"V/cm³","yLabel":"m/g","origin":true,"grid":true,"xTicks":[{"at":0.14,"label":"10"},{"at":0.28,"label":"20"},{"at":0.42,"label":"30"}],"yTicks":[{"at":0.25,"label":"27"},{"at":0.5,"label":"54"},{"at":0.75,"label":"81"}]},{"t":"curve","points":[[20,84],[30,68],[40,52],[50,36],[60,20]],"tone":"accent","arrow":true},{"t":"circle","cx":30,"cy":68,"r":1.6,"fill":true,"tone":"danger"},{"t":"circle","cx":40,"cy":52,"r":1.6,"fill":true,"tone":"danger"},{"t":"circle","cx":50,"cy":36,"r":1.6,"fill":true,"tone":"danger"},{"t":"text","x":66,"y":30,"text":"斜率 = ρ","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"图像的斜率由坐标轴的刻度决定，读斜率时要先把刻度换算成实际数值，不能直接用图上量到的长度相除。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["密度公式","ρ = (m)/(V)","ρ：kg/m³ 或 g/cm³；m：kg 或 g；V：m³ 或 cm³（1 mL = 1 cm³，1 g/cm³ = 1×10³ kg/m³） · 对同种物质在同一状态下 ρ 是定值，公式用来「由 m 和 V 求 ρ」；变形 m = ρV 用来求质量，V = m/ρ 用来求体积。使用条件有三条：m 与 V 必须是同一物体（同一部分物质）的数值；单位必须配套（g 配 cm³，kg 配 m³）；不能由式子反推「ρ 与 m 成正比、与 V 成反比」。"],["排水法测体积","V = V₂ - V₁","V₁、V₂ 单位 mL 或 cm³ · 适用于不吸水、不溶于水且能完全浸没的固体。物体漂浮时要加针压或沉坠；物体吸水时要先让它吸足水再测；物体体积太大时要改用「溢水法」并保证溢出的水全部收集到量筒里。"],["液体密度的计算（方案一）","ρ = (m₁ - m₂)/(V)","m₁、m₂ 单位 g，V 单位 cm³，ρ 单位 g/cm³ · m₁ 是烧杯与液体的总质量，m₂ 是倒出部分液体后烧杯与剩余液体的总质量，V 是量筒中那部分液体的体积。这个式子的关键是「质量差」与「量筒中的体积」严格对应同一部分液体，所以没有残留误差。"],["多次测量取平均值","ρ = (ρ₁ + ρ₂ + ρ₃)/(3)","各次结果单位相同，一般为 g/cm³ · 只适用于「同一物体、同一条件」的重复测量（同一个小石块测三次）。若三次测的是不同物体（不同石块、不同液体），它们的密度本来就不同，不能平均；有效位数要与测量仪器的分度值一致。"]]},{"type":"h","text":"应用 · 生活应用：用密度鉴别物质"},{"type":"note","title":"情境","text":"奶奶有一枚「金戒指」，测得质量是 13.5 g，体积是 0.9 cm³。已知金的密度是 19.3×10³ kg/m³，铜的密度是 8.9×10³ kg/m³。"},{"type":"note","title":"模型与思路","text":"密度是物质的特性，用它可以把金、铜等区分开。先把测得的两个量代入 ρ = m/V，再与纯金的密度比较。"},{"type":"list","title":"解答步骤","items":["统一单位：m = 13.5 g，V = 0.9 cm³。","求密度：ρ = m/V = 13.5 g ÷ 0.9 cm³ = 15 g/cm³ = 15×10³ kg/m³。","与纯金比较：15×10³ kg/m³ 小于 19.3×10³ kg/m³，说明它不是纯金（可能是掺了其他金属的合金）。"]},{"type":"note","title":"结论","text":"这枚戒指的密度是 15×10³ kg/m³，明显小于纯金的密度，所以它不是纯金制品。这就是用密度鉴别物质的典型用法。"},{"type":"h","text":"应用 · 实验应用：测小石块的密度"},{"type":"note","title":"情境","text":"用托盘天平称得小石块的质量为 27 g；量筒中先注入 20 mL 水，把石块完全浸没后水面升到 30 mL。"},{"type":"note","title":"模型与思路","text":"不规则固体的体积用排水法测，密度用 ρ = m/V 计算，两个量的单位要配套（g 与 cm³）。"},{"type":"list","title":"解答步骤","items":["测体积：V = V₂ − V₁ = 30 mL − 20 mL = 10 mL = 10 cm³。","代入公式：ρ = m/V = 27 g ÷ 10 cm³ = 2.7 g/cm³。","换算单位：2.7 g/cm³ = 2.7×10³ kg/m³。","对照密度表：与铝的密度一致，说明小石块可能是铝质的。"]},{"type":"note","title":"结论","text":"小石块的密度是 2.7×10³ kg/m³。注意操作顺序：先称质量、后测体积，否则石块沾水会使质量偏大。"},{"type":"h","text":"应用 · 实验应用：用同一个瓶子测液体密度"},{"type":"note","title":"情境","text":"一个瓶子装满水时比空瓶重 50 g，装满某种液体时比空瓶重 55 g。已知水的密度为 1.0×10³ kg/m³。"},{"type":"note","title":"模型与思路","text":"同一个瓶子装满两种液体，两次的液体体积都等于瓶子的容积，所以两种液体的体积相同；用体积相同作桥梁，由水的质量求出容积，再求液体的密度。"},{"type":"list","title":"解答步骤","items":["水的质量 m水 = 50 g，水的密度 ρ水 = 1.0 g/cm³，瓶的容积 V = m水/ρ水 = 50 cm³。","液体的质量 m液 = 55 g，体积 V = 50 cm³。","液体的密度 ρ液 = m液/V = 55 g ÷ 50 cm³ = 1.1 g/cm³ = 1.1×10³ kg/m³。"]},{"type":"note","title":"结论","text":"这种液体的密度是 1.1×10³ kg/m³，比水大，可能是盐水一类的液体。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["测固体密度时先测体积、后测质量也一样，反正两个量都要测","必须先测质量、后测体积，否则石块沾水使测出的质量偏大、密度偏大","从水中取出的石块表面沾着水，水会一起被天平称进去。体积不变而质量偏大，由 ρ = m/V 可知结果偏大。"],["测液体密度时，把量筒中的液体全部倒入烧杯再称质量，测出的密度更准确","量筒壁上会残留少量液体，倒入烧杯的液体偏少、质量偏小，测出的密度偏小","量筒壁上的残留液体没有被称到，而体积是按量筒读数算的，于是质量偏小而体积不变，密度偏小。所以要用「先测总质量、倒出部分、再测剩余质量」的方案。"],["1 g/cm³ = 1×10³ kg/m³，所以 2.7 g/cm³ 就是 2.7 kg/m³","2.7 g/cm³ = 2.7×10³ kg/m³","1 g/cm³ = 10⁻³ kg ÷ 10⁻⁶ m³ = 10³ kg/m³，换算时要乘 10³，不是把数字照抄。铝的密度 2.7 g/cm³ 也就是 2700 kg/m³。"],["由 ρ = m/V 可知，物体的质量越大密度越大、体积越大密度越小","密度是物质的特性，同种物质在相同状态下密度相同，与质量、体积无关","质量与体积是同比例变化的：把一块铝切成两半，质量变成一半、体积也变成一半，比值不变，所以密度不变。"]]},{"type":"table","title":"先测质量与先测体积（测不规则固体密度时的两种操作顺序）","head":["比较项","先测质量，后测体积","先测体积，后测质量"],"rows":[["称量时石块的状态","干燥的","表面沾水"],["测出的质量","准确","偏大（水被一起称进去）"],["测出的体积","准确","准确"],["算出的密度","准确","偏大"]]},{"type":"table","title":"液体密度的两种方案（比较两个方案的误差来源）","head":["比较项","方案一：测总质量 → 倒出部分到量筒 → 测剩余质量","方案二：测空杯质量 → 量筒测体积 → 全部倒入烧杯再称"],"rows":[["计算式","ρ = (m₁ − m₂)/V","ρ = (m₂ − m₀)/V"],["误差来源","量筒中液体的质量与体积严格对应，无明显残留误差","量筒壁上残留液体，倒入烧杯的液体偏少"],["结果偏差","接近真实值","质量偏小，密度偏小"],["结论","更合理，优先选用","不推荐，除非把残留液体也算进去"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["实验步骤排序与误差分析","给出若干个操作步骤，要求排出正确顺序并说明理由；或者问「按某顺序做会使结果偏大还是偏小」。答题固定套路是：先写清哪个量偏了、往哪个方向偏，再由 ρ = m/V 判断密度的偏差方向。"],["数据表格与图像处理","给出质量与体积的数据，要求补全表格、计算密度、画 m-V 图像并由图像求密度。评分通常看：表头有没有写单位、数据有没有按规则取平均值、图像是否过原点且描点连线规范、由斜率求密度的过程是否完整。"],["密度计算与鉴别物质","以金属块、液体、空心球为情境，考查密度计算、单位换算与鉴别判断。空心球问题要分「按质量算体积」「按体积算质量」两条路走：算出的体积比实际大，说明球是空心的。"]]},{"type":"quote","text":"【材料一】某小组测量一块小石块的密度。他们先把小石块放在调节好的托盘天平上称量，右盘放 20 g 与 5 g 的砝码，游码移到 2.0 g 处时横梁平衡；然后在 50 mL 量筒中注入 20 mL 水，用细线系好小石块缓慢放入量筒使其完全浸没，水面升到 30 mL。\n【材料二】另一小组测量盐水的密度。他们先把盐水倒入烧杯，称得烧杯和盐水的总质量为 96.0 g；把一部分盐水倒入量筒，读出体积为 40 mL；再称烧杯和剩余盐水的质量为 52.0 g。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据材料一，求出小石块的质量、体积和密度（密度分别用 g/cm³ 与 kg/m³ 表示）。（4 分）","【设问】材料一中，如果先用量筒测体积、再用天平称质量，测出的密度会偏大还是偏小？为什么？（3 分）","【设问】根据材料二，求出盐水的密度，并说明这个方案比「把量筒中的盐水全部倒入烧杯再称量」好在哪里。（4 分）"]}],"questions":[{"id":"phy-experiment-2-q1","type":"choice","stem":"如图，用量筒和水测小石块的体积：量筒中原有 20 mL 水，把小石块用细线系好完全浸入水中后，水面升到 30 mL。下列说法正确的是","answer":"B","explain":"B 正确：排水法用两次读数相减，V = 30 mL − 20 mL = 10 mL = 10 cm³。A 错：30 mL 是水和石块的总体积，不是石块自己的体积。C 错：石块取出后会带出一部分水，再读数反而使结果偏小，规范做法是读完 V₂ 就结束。D 错：量筒不需要估读，50 mL 量筒分度值 1 mL，读到 10 mL 即可。","options":["小石块的体积等于第二次的读数，即 30 cm³","小石块的体积等于两次读数之差，即 10 cm³","必须把小石块从水中取出后再读一次水的体积，才能算出石块的体积","两次读数都要估读到 0.1 mL，结果写成 10.00 cm³"],"difficulty":1,"tags":["排水法","量筒"],"figure":{"id":"fig-exp-density-q1","title":"排水法测石块体积","caption":"放入石块前 20 mL，放入后 30 mL","view":"wide","alt":"左边量筒中水面在 20 毫升处，右边量筒中放入小石块后水面升到 30 毫升处","prims":[{"t":"beaker","x":12,"y":16,"w":22,"h":34,"fill":0.4,"label":"V₁"},{"t":"beaker","x":58,"y":16,"w":22,"h":34,"fill":0.6,"label":"V₂"},{"t":"circle","cx":69,"cy":42,"r":4,"fill":true,"tone":"main","label":"石块"},{"t":"arrow","x1":38,"y1":30,"x2":54,"y2":30,"tone":"accent"},{"t":"text","x":23,"y":56,"text":"20 mL","size":3.4},{"t":"text","x":69,"y":56,"text":"30 mL","size":3.4},{"t":"text","x":50,"y":8,"text":"量筒分度值 1 mL","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-2-q2","type":"choice","stem":"用天平和量筒测量小石块的密度，下列操作顺序中最合理的是","answer":"A","explain":"A 正确：先称质量时石块干燥、质量准确，而测完体积实验就结束了，沾水不影响结果。B 错：石块沾水后质量偏大而不是偏小，而且沾水发生在测体积之后，若接着称质量就会把这个偏大带进密度计算。C 错：顺序不同，测出的质量不同，结果就不同。D 错：泡水后再称质量同样使质量偏大，且多了一步无意义的操作。","options":["先用天平称质量，再用排水法测体积，这样石块在称量时是干燥的","先用排水法测体积，再用天平称质量，因为石块沾水后质量会变小","两种顺序对结果的影响完全一样，随便选一个","先把石块浸在水中泡一会儿再称质量，可以避免表面附着气泡"],"difficulty":2,"tags":["操作顺序","误差分析"]},{"id":"phy-experiment-2-q3","type":"choice","stem":"测量盐水的密度时，小明用量筒量出 40 mL 盐水，把盐水全部倒入空烧杯后称得总质量，算出密度。与规范的方案相比，他的结果","answer":"D","explain":"D 正确：量筒壁上总会残留少量盐水，它没有被称进去，而体积仍按量筒的 40 mL 计算，所以质量偏小、体积不变、密度偏小。A、B 都把偏差方向说反了：残留使质量偏小而不是偏大，量筒读数也不受残留影响。C 错：「一点也没有损失」与事实不符，倒出液体时量筒壁一定会有残留。规范做法是先称烧杯与盐水的总质量，倒出部分到量筒，再称剩余质量，用质量差与量筒中的体积对应。","options":["偏大，因为烧杯里还残留着水","偏大，因为量筒的读数偏小","完全相同，因为盐水一点也没有损失","偏小，因为量筒壁上残留了少量盐水，倒入烧杯的盐水质量偏小"],"difficulty":3,"tags":["液体密度","误差分析"],"figure":{"id":"fig-exp-2-cylinder","title":"用量筒量取盐水再倒入烧杯","caption":"量筒读数时视线要与凹液面的最低处相平；把盐水全部倒入烧杯后，量筒内壁上会残留少量盐水，使算出的密度偏小","view":"square","alt":"左边是一个量筒，里面盛着盐水，液面凹面处标有 40 毫升的读数位置；一条箭头指向右边空烧杯，表示把盐水倒入烧杯","prims":[{"t":"rect","x":14,"y":20,"w":22,"h":56,"tone":"muted"},{"t":"rect","x":17,"y":40,"w":16,"h":33,"tone":"accent","fill":true},{"t":"line","x1":14,"y1":40,"x2":36,"y2":40,"tone":"accent","width":0.6},{"t":"line","x1":36,"y1":26,"x2":41,"y2":26,"tone":"muted","width":0.3},{"t":"line","x1":36,"y1":36,"x2":41,"y2":36,"tone":"muted","width":0.3},{"t":"line","x1":36,"y1":46,"x2":41,"y2":46,"tone":"muted","width":0.3},{"t":"line","x1":36,"y1":56,"x2":41,"y2":56,"tone":"muted","width":0.3},{"t":"line","x1":36,"y1":66,"x2":41,"y2":66,"tone":"muted","width":0.3},{"t":"text","x":44,"y":42,"text":"40 mL","size":3.4,"tone":"accent","anchor":"start"},{"t":"text","x":25,"y":88,"text":"量筒：视线与凹液面最低处相平","size":3.6,"tone":"main","anchor":"middle"},{"t":"arrow","x1":44,"y1":50,"x2":58,"y2":50,"tone":"danger","label":"全部倒入"},{"t":"beaker","x":62,"y":40,"w":30,"h":34,"fill":0.45,"label":"烧杯"},{"t":"text","x":77,"y":88,"text":"量筒壁残留盐水","size":3.6,"tone":"danger","anchor":"middle"}]}},{"id":"phy-experiment-2-q4","type":"choice","stem":"关于密度，下列说法正确的是","answer":"C","explain":"C 正确：密度由物质的种类与状态决定，切去一半后质量、体积都减半，比值不变。A 错：只改变物体大小不改变密度。B 错：换算时要乘 10³，2.7 g/cm³ = 2.7×10³ kg/m³，直接照抄数字是单位换算的典型错误。D 错：体积变大时质量也同比例变大（同种物质），密度不变。","options":["铁块的密度是 7.9×10³ kg/m³，切去一半后它的密度变为原来的一半","1 g/cm³ 等于 1×10³ kg/m³，所以 2.7 g/cm³ 等于 2.7 kg/m³","密度是物质的一种特性，同种物质在相同状态下密度一般相同，与质量、体积的大小无关","由 ρ = m/V 可知，体积越大密度越小"],"difficulty":2,"tags":["密度概念","单位换算"]},{"id":"phy-experiment-2-q5","type":"fill","stem":"如图，量筒的分度值为 1 mL。放入小石块前量筒中水的体积是 20 mL，放入小石块后水面升到 30 mL，小石块的体积是 ______ cm³。","answer":"10|10 cm³|10cm³|10 mL","explain":"为什么这样算：排水法用两次读数之差求体积，V = V₂ − V₁ = 30 mL − 20 mL = 10 mL，而 1 mL = 1 cm³，所以是 10 cm³。两次读数都要让视线与凹液面最低处相平，石块要完全浸没且不接触筒壁、筒底。若石块吸水或带有气泡，测出的体积会偏小或偏大。","difficulty":1,"tags":["排水法","读数"],"figure":{"id":"fig-exp-density-q5","title":"放入石块前后的水面位置","caption":"两次读数之差就是小石块的体积","view":"wide","alt":"左边量筒中水面在 20 毫升处，右边量筒中放入小石块后水面升到 30 毫升处，两次读数相减得 10 立方厘米","prims":[{"t":"beaker","x":12,"y":16,"w":22,"h":34,"fill":0.4,"label":"V₁ = 20 mL"},{"t":"beaker","x":58,"y":16,"w":22,"h":34,"fill":0.6,"label":"V₂ = 30 mL"},{"t":"circle","cx":69,"cy":42,"r":4,"fill":true,"tone":"main"},{"t":"arrow","x1":38,"y1":30,"x2":54,"y2":30,"tone":"accent","label":"放入石块"},{"t":"text","x":50,"y":8,"text":"量筒分度值 1 mL","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-2-q6","type":"fill","stem":"一块金属的质量是 54 g，体积是 20 cm³，它的密度是 ______ kg/m³。","answer":"2700|2700 kg/m³|2.7×10³|2.7×10³","explain":"为什么这样算：先按配套单位求密度，ρ = m/V = 54 g ÷ 20 cm³ = 2.7 g/cm³；再换算单位，1 g/cm³ = 1×10³ kg/m³，所以 2.7 g/cm³ = 2.7×10³ kg/m³ = 2700 kg/m³。常见错误是把 2.7 直接当成 kg/m³ 的数值，或者把 54 g 当成 54 kg 代入。","difficulty":2,"tags":["密度计算","单位换算"]},{"id":"phy-experiment-2-q7","type":"short","stem":"一个空烧杯的质量是 42.4 g。把它装满水后总质量是 92.4 g，装满某种液体后总质量是 97.4 g。已知水的密度为 1.0×10³ kg/m³，求这种液体的密度（分别用 g/cm³ 与 kg/m³ 表示）。","answer":"水的质量 m水 = 92.4 g − 42.4 g = 50 g，瓶的容积 V = m水/ρ水 = 50 g ÷ 1.0 g/cm³ = 50 cm³。液体的质量 m液 = 97.4 g − 42.4 g = 55 g，液体的密度 ρ液 = m液/V = 55 g ÷ 50 cm³ = 1.1 g/cm³ = 1.1×10³ kg/m³。","explain":"为什么这么做：两种液体都装满同一个烧杯，它们的体积都等于烧杯的容积，这就是「体积相同」这个桥梁。先用水的质量与水的密度求出容积，再把这个体积用到液体上。代入时要注意两点：一是质量都要减去空杯的质量；二是水的密度要换成与水质量单位配套的 1.0 g/cm³（若用 1.0×10³ kg/m³，则质量必须先换成 0.05 kg）。","difficulty":3,"tags":["密度计算","等体积"],"rubric":["算出水的质量 50 g（1 分）","求出瓶的容积 50 cm³（1 分）","算出液体的质量 55 g（1 分）","写出 ρ = m/V 并算出 1.1 g/cm³、正确换算成 1.1×10³ kg/m³（1 分）"],"steps":["水的质量：m水 = 92.4 g − 42.4 g = 50 g。","瓶的容积（也就是水的体积）：V = m水/ρ水 = 50 g ÷ 1.0 g/cm³ = 50 cm³。","液体的质量：m液 = 97.4 g − 42.4 g = 55 g。","液体的密度：ρ液 = m液/V = 55 g ÷ 50 cm³ = 1.1 g/cm³。","换算单位：1.1 g/cm³ = 1.1×10³ kg/m³，作答并带单位。"]},{"id":"phy-experiment-2-q8","type":"short","stem":"在测量小石块密度的实验中：(1) 为什么要求先测质量、后测体积？(2) 如果测得小石块的密度比真实值偏大，除了石块沾水，还可能有哪些原因？请写出两条。","answer":"(1) 先测质量时小石块是干燥的，测出的质量准确；先测体积时石块表面会沾水，再称质量会使质量偏大，由 ρ = m/V 可知算出的密度偏大。实验结束时不需要再称质量，所以把测体积放在最后最合理。(2) 可能的原因：① 把石块从量筒中取出或读数时带走了水，使水面读数偏小，算出的体积偏小；② 石块没有完全浸没（或表面附着气泡），读出的 V₂ 偏小，体积偏小；③ 游码没有归零就开始称量，测出的质量偏大；④ 石块吸水，测出的体积偏小。","explain":"判断偏差方向的通用思路是：先看哪个量偏了、朝哪个方向偏，再由 ρ = m/V 推结果。质量偏大或体积偏小都会使密度偏大；质量偏小或体积偏大都会使密度偏小。(2) 问里的「水面读数偏小」「石块没完全浸没」「石块吸水」都让 V 偏小，而「游码未归零」让 m 偏大，四种原因都会使密度偏大。","difficulty":3,"tags":["实验说理","误差分析"],"rubric":["答出先测质量时石块干燥、质量准确（1 分）","说明先测体积会使石块沾水、质量偏大并推出密度偏大（1 分）","写出第一条导致密度偏大的其他原因并说明偏差方向（1 分）","写出第二条原因并说明偏差方向（1 分）"]},{"id":"phy-experiment-2-q9","type":"short","stem":"请画出用排水法测小石块体积时两次水面位置的示意图，在图上标出 V₁、V₂，并写出体积的表达式。","answer":"见参考答案图：第一次量筒中只有水，水面在 V₁ 处；第二次用细线把小石块完全浸没在水中，水面升到 V₂ 处；小石块的体积 V = V₂ − V₁。","explain":"作图要点：① 两张量筒图要画成同样的形状与刻度，只让水面高低不同，这样才看得出是「同一次实验的先后两次」；② 石块要画在水面以下、不接触筒壁与筒底，并画一条细线表示用细线系住；③ 两个水面位置分别标注 V₁、V₂，再在下方写出 V = V₂ − V₁。若把石块画成露出水面，就等于没完全浸没，体积的测量会偏小。","difficulty":2,"tags":["作图","排水法"],"rubric":["两张量筒图画成相同形状与刻度，只有水面高低不同","石块画在水面以下、不接触筒壁与筒底，并用细线系住","两处水面分别标注 V₁、V₂","写出体积表达式 V = V₂ − V₁"],"answerFigure":{"id":"fig-exp-density-ans1","title":"参考答案：两次水面位置","caption":"V₁ 是原有水的体积，V₂ 是放入石块后的总体积","view":"wide","alt":"左边量筒中水面在 V₁ 处，右边量筒中石块被细线吊着完全浸没、水面升到 V₂ 处，下方写出体积表达式 V 等于 V₂ 减 V₁","prims":[{"t":"beaker","x":12,"y":14,"w":22,"h":34,"fill":0.4,"label":"V₁"},{"t":"beaker","x":58,"y":14,"w":22,"h":34,"fill":0.62,"label":"V₂"},{"t":"line","x1":69,"y1":4,"x2":69,"y2":26,"dashed":true,"tone":"muted"},{"t":"circle","cx":69,"cy":32,"r":4,"fill":true,"tone":"main","label":"石块"},{"t":"arrow","x1":38,"y1":28,"x2":54,"y2":28,"tone":"accent"},{"t":"text","x":23,"y":54,"text":"只有水","size":3.4,"tone":"muted"},{"t":"text","x":69,"y":54,"text":"石块完全浸没","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":61,"text":"V = V₂ − V₁","size":4,"tone":"accent"}]}},{"id":"phy-experiment-2-m1-q1","type":"short","stem":"根据材料一，求出小石块的质量、体积和密度（密度分别用 g/cm³ 与 kg/m³ 表示）。（4 分）","answer":"m = 20 g + 5 g + 2.0 g = 27 g；V = 30 mL − 20 mL = 10 mL = 10 cm³；ρ = m/V = 27 g ÷ 10 cm³ = 2.7 g/cm³ = 2.7×10³ kg/m³。","explain":"","tags":["密度计算","排水法"],"rubric":["读出质量 m = 27 g 并写出读数过程（1 分）","用排水法算出 V = 10 cm³（1 分）","写出 ρ = m/V 并算出 2.7 g/cm³（1 分）","正确换算成 2.7×10³ kg/m³（1 分）"]},{"id":"phy-experiment-2-m1-q2","type":"short","stem":"材料一中，如果先用量筒测体积、再用天平称质量，测出的密度会偏大还是偏小？为什么？（3 分）","answer":"会偏大。先测体积时小石块表面沾了水，再放到天平上称量，水会被一起称进去，测出的质量偏大；体积不变，由 ρ = m/V 可知算出的密度偏大。所以规范的顺序是先测质量、后测体积。","explain":"","tags":["误差分析","操作顺序"],"rubric":["答出「偏大」（1 分）","说明石块沾水使测出的质量偏大（1 分）","用 ρ = m/V 说明体积不变、质量偏大导致密度偏大（1 分）"]},{"id":"phy-experiment-2-m1-q3","type":"short","stem":"根据材料二，求出盐水的密度，并说明这个方案比「把量筒中的盐水全部倒入烧杯再称量」好在哪里。（4 分）","answer":"倒出的盐水质量 m = 96.0 g − 52.0 g = 44.0 g，体积 V = 40 mL = 40 cm³，密度 ρ = m/V = 44.0 g ÷ 40 cm³ = 1.1 g/cm³ = 1.1×10³ kg/m³。这个方案中，量筒里那 40 mL 盐水的质量正好等于两次称量的质量之差，质量与体积严格对应同一部分盐水；而「全部倒入烧杯」的方案里有少量盐水残留在量筒壁上，倒入烧杯的质量偏小，体积却按量筒读数算，因此测出的密度偏小。","explain":"","tags":["液体密度","方案评价"],"rubric":["算出倒出盐水的质量 44.0 g（1 分）","写出 ρ = m/V 并算出 1.1 g/cm³（1 分）","正确换算成 1.1×10³ kg/m³（1 分）","说明质量与体积对应同一部分液体、避免残留误差（1 分）"]}]},{"id":"phy-experiment-3","title":"探究影响滑动摩擦力大小的因素：转换法与控制变量","subtitle":"实验操作考试 · 必做实验 · all","grade":"all","tags":["实验操作考试 · 必做实验"],"blocks":[{"type":"note","title":"教材位置","text":"实验操作考试 · 必做实验 · all"},{"type":"note","title":"问题切入","text":"为什么在瓷砖上推箱子很轻松、在粗糙的水泥地上却很费劲？弹簧测力计上读出的是拉力，凭什么说它等于摩擦力？为什么必须匀速拉动木块？如果把木块侧放使接触面积变小，摩擦力会变小吗？"},{"type":"note","title":"一句话抓住关键","text":"木块做匀速直线运动时，水平方向上的拉力与滑动摩擦力是一对平衡力，大小相等，所以测力计的示数就等于滑动摩擦力，这就是转换法；再分别只改变压力、只改变接触面的粗糙程度，用控制变量法找出规律。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"摩擦力看不见，怎么测？让木块匀速滑动，此时拉力与摩擦力平衡，测力计的示数就是摩擦力——这叫转换法。","walk":["转换法：把不易直接测的量，转化成容易测的量。","控制变量：研究压力影响时，只改压力，接触面保持不变。","结论：压力越大、接触面越粗糙，滑动摩擦力越大。"],"try":"用弹簧秤拉木块在桌面上匀速滑动，再垫上毛巾重做，比较两次示数。","use":["必须「匀速直线」拉动，否则拉力不等于摩擦力。","设计表格：只让一个变量改变，其余保持不变。"]},{"type":"h","text":"先看现象：地面越粗糙、箱子越重，推起来越费劲"},{"type":"p","text":"同样的箱子，在光滑的瓷砖上轻轻一推就能滑动，在粗糙的水泥地上却很吃力；同一个地面，箱子里的东西越重，推起来也越费力。这两个现象指向两个因素：接触面的粗糙程度和压力的大小。要研究它们各自的作用，就必须一次只改变一个因素，让另一个保持相同——这就是控制变量。"},{"type":"figure","figure":{"id":"fig-exp-friction-1","title":"两个影响因素","caption":"接触面越粗糙，拉动同一个箱子越费力","view":"wide","alt":"左边箱子的下方是斜线较稀的瓷砖地面，右边箱子的下方是斜线较密的水泥地面，右边需要更大的拉力","prims":[{"t":"hatch","x":8,"y":24,"w":38,"h":5,"gap":3},{"t":"rect","x":14,"y":14,"w":16,"h":10,"fill":true,"tone":"main","label":"箱子"},{"t":"arrow","x1":31,"y1":19,"x2":42,"y2":19,"tone":"accent","label":"F"},{"t":"text","x":27,"y":36,"text":"瓷砖：省力","size":3.6,"tone":"muted"},{"t":"hatch","x":54,"y":24,"w":38,"h":5,"gap":1.3},{"t":"rect","x":60,"y":14,"w":16,"h":10,"fill":true,"tone":"main","label":"箱子"},{"t":"arrow","x1":77,"y1":19,"x2":90,"y2":19,"tone":"danger","label":"F 更大"},{"t":"text","x":73,"y":36,"text":"水泥地：费力","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":50,"text":"接触面越粗糙、压力越大，滑动摩擦力越大","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"滑动摩擦力产生在「相对滑动」的两物体之间，它的大小只由压力大小与接触面的粗糙程度决定。"},{"type":"h","text":"转换法：匀速拉动时，示数就等于摩擦力"},{"type":"p","text":"摩擦力看不见也摸不着，不能直接读数，但可以转换：用弹簧测力计沿水平方向拉着木块在水平面上做匀速直线运动，木块在水平方向上只受到拉力和滑动摩擦力，两者是一对平衡力，大小相等，于是弹簧测力计的示数就等于滑动摩擦力。这里的三个条件缺一不可：水平拉动、匀速直线运动、测力计已校零。若拉着木块加速前进，拉力大于摩擦力，示数就不再等于摩擦力了。"},{"type":"figure","figure":{"id":"fig-exp-friction-2","title":"转换法：拉力的示数等于摩擦力","caption":"木块匀速直线运动，水平方向拉力与摩擦力二力平衡","view":"wide","alt":"水平面上一个木块，右侧用弹簧测力计沿水平方向向右匀速拉动，木块受到向右的拉力与向左的摩擦力，两者大小相等","prims":[{"t":"line","x1":8,"y1":40,"x2":92,"y2":40,"width":0.8},{"t":"hatch","x":8,"y":40,"w":84,"h":5,"gap":2.2},{"t":"rect","x":30,"y":26,"w":20,"h":14,"fill":true,"tone":"main","label":"木块"},{"t":"spring","x1":50,"y1":33,"x2":64,"y2":33,"coils":6},{"t":"text","x":57,"y":24,"text":"弹簧测力计","size":3.4,"tone":"muted"},{"t":"arrow","x1":66,"y1":33,"x2":88,"y2":33,"tone":"accent","label":"F 拉"},{"t":"arrow","x1":30,"y1":33,"x2":12,"y2":33,"tone":"danger","label":"f"},{"t":"text","x":50,"y":52,"text":"匀速直线运动","size":3.8,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"二力平衡：示数 F = 滑动摩擦力 f","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"读数要在木块匀速运动的过程中读，不能等它停下来再读；测力计使用前必须校零，拉力的方向要沿水平方向。"},{"type":"h","text":"控制变量一：只改变压力"},{"type":"p","text":"把木块放在木板上，用弹簧测力计匀速拉动，读出摩擦力；然后在木块上放一个砝码，压力变大，再用同样的方法匀速拉动，读出新的摩擦力。两次实验接触面都是同一块木板，粗糙程度没有变，只有压力变了，因此两次读数的差别只能由压力引起。实验结果是压力越大，滑动摩擦力越大。"},{"type":"figure","figure":{"id":"fig-exp-friction-3","title":"改变压力（接触面不变）","caption":"同一个木板，压力从 4.0 N 增到 6.0 N，摩擦力从 1.6 N 增到 2.4 N","view":"wide","alt":"上排木块单独放在木板上，压力 4.0 牛顿时摩擦力 1.6 牛顿；下排木块上加了砝码，压力 6.0 牛顿时摩擦力 2.4 牛顿","prims":[{"t":"hatch","x":8,"y":26,"w":36,"h":5,"gap":2.6},{"t":"rect","x":14,"y":16,"w":16,"h":10,"fill":true,"tone":"main","label":"木块"},{"t":"spring","x1":30,"y1":21,"x2":42,"y2":21,"coils":4},{"t":"text","x":26,"y":36,"text":"压力 4.0 N，f = 1.6 N","size":3.4,"tone":"muted"},{"t":"hatch","x":56,"y":26,"w":36,"h":5,"gap":2.6},{"t":"rect","x":62,"y":16,"w":16,"h":10,"fill":true,"tone":"main","label":"木块"},{"t":"rect","x":64,"y":10,"w":12,"h":6,"fill":true,"tone":"accent","label":"砝码"},{"t":"spring","x1":78,"y1":21,"x2":88,"y2":21,"coils":4},{"t":"text","x":74,"y":36,"text":"压力 6.0 N，f = 2.4 N","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":50,"text":"接触面粗糙程度相同，压力越大，滑动摩擦力越大","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"结论必须写全「在……一定时」。只写「压力越大摩擦力越大」缺了条件，属于表述不完整。"},{"type":"h","text":"控制变量二：只改变接触面的粗糙程度"},{"type":"p","text":"保持木块与砝码都不变（压力相同），先让木块在木板上匀速滑动，读出摩擦力；再把毛巾铺在木板上，用同样的方法匀速拉动木块，读出摩擦力。这一次压力没有变，只有接触面的粗糙程度变了，结果是毛巾面比木板面的摩擦力大。两次实验合起来说明：滑动摩擦力的大小由压力大小和接触面的粗糙程度共同决定。"},{"type":"figure","figure":{"id":"fig-exp-friction-4","title":"改变接触面的粗糙程度（压力不变）","caption":"同样放砝码，木板面上 f = 2.4 N，毛巾面上 f = 3.2 N","view":"wide","alt":"上排木块加砝码在木板上滑动，摩擦力 2.4 牛顿；下排同样加砝码的木块在毛巾上滑动，摩擦力 3.2 牛顿","prims":[{"t":"hatch","x":8,"y":26,"w":36,"h":5,"gap":2.6},{"t":"rect","x":14,"y":16,"w":16,"h":10,"fill":true,"tone":"main","label":"木块"},{"t":"rect","x":16,"y":10,"w":12,"h":6,"fill":true,"tone":"accent","label":"砝码"},{"t":"spring","x1":30,"y1":21,"x2":42,"y2":21,"coils":4},{"t":"text","x":26,"y":36,"text":"木板面：f = 2.4 N","size":3.4,"tone":"muted"},{"t":"hatch","x":56,"y":26,"w":36,"h":5,"gap":1.2},{"t":"rect","x":62,"y":16,"w":16,"h":10,"fill":true,"tone":"main","label":"木块"},{"t":"rect","x":64,"y":10,"w":12,"h":6,"fill":true,"tone":"accent","label":"砝码"},{"t":"spring","x1":78,"y1":21,"x2":88,"y2":21,"coils":4},{"t":"text","x":74,"y":36,"text":"毛巾面：f = 3.2 N","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":50,"text":"压力相同时，接触面越粗糙，滑动摩擦力越大","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"铺毛巾时要铺平、固定住，否则毛巾被拉动，测力计的读数就不只是摩擦力了。"},{"type":"h","text":"数据记录与结论表述"},{"type":"p","text":"数据要填进表格：表头写「压力 F/N」「摩擦力 f/N」，同一条件测三次取平均值。写结论时固定用这个句式：在（某个因素）一定时，（另一个因素）越大，滑动摩擦力越大。这样的表述把控制变量的条件交代清楚了，才算是完整的实验结论；只写「压力越大摩擦力越大」缺了前提，会被扣分。"},{"type":"figure","figure":{"id":"fig-exp-friction-6","title":"实验数据记录表","caption":"同一条件重复测量取平均值，改变条件的数据不能放在一起平均","view":"wide","alt":"三行数据表：第一次压力 4.0 牛顿时摩擦力 1.6 牛顿，第二次压力 6.0 牛顿时摩擦力 2.4 牛顿，第三次在毛巾面上压力 6.0 牛顿时摩擦力 3.2 牛顿","prims":[{"t":"rect","x":8,"y":12,"w":84,"h":36,"tone":"main"},{"t":"line","x1":8,"y1":21,"x2":92,"y2":21},{"t":"line","x1":8,"y1":30,"x2":92,"y2":30},{"t":"line","x1":8,"y1":39,"x2":92,"y2":39},{"t":"line","x1":26,"y1":12,"x2":26,"y2":48},{"t":"line","x1":58,"y1":12,"x2":58,"y2":48},{"t":"text","x":17,"y":16.5,"text":"次数","size":3.4},{"t":"text","x":42,"y":16.5,"text":"压力 F/N","size":3.4},{"t":"text","x":75,"y":16.5,"text":"摩擦力 f/N","size":3.4},{"t":"text","x":17,"y":25.5,"text":"1","size":3.4},{"t":"text","x":42,"y":25.5,"text":"4.0","size":3.4},{"t":"text","x":75,"y":25.5,"text":"1.6","size":3.4},{"t":"text","x":17,"y":34.5,"text":"2","size":3.4},{"t":"text","x":42,"y":34.5,"text":"6.0","size":3.4},{"t":"text","x":75,"y":34.5,"text":"2.4","size":3.4},{"t":"text","x":17,"y":43.5,"text":"3","size":3.4},{"t":"text","x":42,"y":43.5,"text":"6.0（毛巾）","size":3.4},{"t":"text","x":75,"y":43.5,"text":"3.2","size":3.4},{"t":"text","x":50,"y":56,"text":"同一条件测三次取平均值；不同条件的数据不能平均","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"第 1 次与第 2 次对比可以看出压力的影响，第 2 次与第 3 次对比可以看出粗糙程度的影响，分析时必须说清是拿哪两次比较。"},{"type":"h","text":"改进方案：拉动木板，读数更稳定"},{"type":"p","text":"教材的基础方案要求木块做匀速直线运动，但用手拉很难保持匀速，读数一直在晃动。改进的办法是：把弹簧测力计的一端固定（接在支架或墙上），另一端拉住木块，然后用手拉动下面的木板。木块虽然随木板一起被「蹭」，但它相对地面是静止的，处于平衡状态，测力计的示数就等于木块受到的滑动摩擦力——而且木板不必匀速拉动，读数稳定得多，操作也容易。"},{"type":"figure","figure":{"id":"fig-exp-friction-5","title":"改进方案：拉木板、木块不动","caption":"木块静止，测力计示数仍等于滑动摩擦力，木板不必匀速拉动","view":"wide","alt":"木块放在长木板上，左侧通过弹簧测力计固定在支架上，长木板被向右拉动，木块受到向右的滑动摩擦力与测力计的拉力平衡","prims":[{"t":"rect","x":6,"y":14,"w":6,"h":16,"fill":true,"tone":"muted","label":"支架"},{"t":"spring","x1":34,"y1":22,"x2":12,"y2":22,"coils":7},{"t":"rect","x":34,"y":16,"w":20,"h":12,"fill":true,"tone":"main","label":"木块"},{"t":"arrow","x1":54,"y1":22,"x2":68,"y2":22,"tone":"danger","label":"f"},{"t":"rect","x":20,"y":28,"w":60,"h":10,"fill":true,"tone":"accent","label":"长木板（被拉动）"},{"t":"hatch","x":20,"y":38,"w":60,"h":5,"gap":2.2},{"t":"arrow","x1":62,"y1":43,"x2":84,"y2":43,"tone":"accent","label":"拉动木板"},{"t":"text","x":50,"y":55,"text":"木块静止：示数仍然等于滑动摩擦力，读数稳定","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"改进方案的关键是「木块相对地面静止」：静止属于平衡状态，不要求木板匀速；若改成拉木块，就仍然必须匀速。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["二力平衡与转换法","f = F_(示)","f 与 F示 的单位都是 N（牛顿） · 只适用于用弹簧测力计沿水平方向拉动木块做匀速直线运动的情形：此时水平方向上只有拉力和滑动摩擦力，两者平衡。若木块加速运动，示数大于摩擦力；减速时示数小于摩擦力；测力计没有校零、没有沿水平方向拉、或者木块没有做匀速直线运动，这个等号都不成立。"],["摩擦力与压力的定量关系（本组器材的结论）","f = 0.4F","f、F 单位都是 N · 这是在木板表面上测得的一组数据（压力 4.0 N 对应摩擦力 1.6 N，压力 6.0 N 对应 2.4 N）得出的比例关系，只用于在这组器材上做数据推算。初中阶段写结论要用定性表述「接触面粗糙程度一定时，压力越大，滑动摩擦力越大」，不能把这个 0.4 当成普遍适用的常数。"],["同一条件取平均值","f = (f₁ + f₂ + f₃)/(3)","各次读数单位都是 N · 只适用于「同一压力、同一接触面」下的重复测量，用来减小偶然误差。改变了压力或更换了接触面之后的读数属于不同条件，它们的差别正是实验要找的规律，绝不能放在一起取平均。"]]},{"type":"h","text":"应用 · 生活应用：鞋底花纹与刹车"},{"type":"note","title":"情境","text":"运动鞋底有凹凸的花纹，雨天走在瓷砖地面上仍然不容易滑倒；骑自行车下坡时用力捏闸，车会很快减速。"},{"type":"note","title":"模型与思路","text":"花纹是为了增大接触面的粗糙程度，捏闸是增大闸皮对轮圈的压力，两者都在增大滑动（或滚动）摩擦力，用「压力与粗糙程度决定摩擦力大小」来解释。"},{"type":"list","title":"解答步骤","items":["鞋底花纹使鞋底与地面之间形成许多细小的凸起，接触面更粗糙，在压力相同时摩擦力更大。","捏闸时闸皮对轮圈的压力增大，接触面不变，摩擦力随之增大，车轮更快减速。","若地面有水（相当于加了一层润滑），粗糙程度下降，即使压力相同摩擦力也变小，所以要小心行走。"]},{"type":"note","title":"结论","text":"增大有益摩擦的办法有两个：增大压力、增大接触面的粗糙程度；反过来，加润滑油、加滚轮则是减小摩擦的办法。"},{"type":"h","text":"应用 · 实验应用：由数据推算摩擦力"},{"type":"note","title":"情境","text":"在同一块木板上做实验：木块对木板的压力为 4.0 N 时，匀速拉动读出摩擦力 1.6 N；在木块上放一个重 2.0 N 的砝码后，仍匀速拉动。"},{"type":"note","title":"模型与思路","text":"接触面没有变，只有压力变了。由第一组数据求出「摩擦力与压力的比值」，再用这个比值推算新的压力下摩擦力的大小。"},{"type":"list","title":"解答步骤","items":["第一组数据：f₁/F₁ = 1.6 N ÷ 4.0 N = 0.4。","放入砝码后的压力：F₂ = 4.0 N + 2.0 N = 6.0 N。","推算摩擦力：f₂ = 0.4 × 6.0 N = 2.4 N。"]},{"type":"note","title":"结论","text":"摩擦力变为 2.4 N。这个比值只说明本组实验里「摩擦力与压力成正比」的定量关系，写结论时仍要用「接触面粗糙程度一定时，压力越大，滑动摩擦力越大」这样的表述。"},{"type":"h","text":"应用 · 实验应用：为什么改进后读数更稳"},{"type":"note","title":"情境","text":"两种操作：甲同学用手拉木块做匀速直线运动，乙同学把测力计固定在支架上、拉动下面的木板。"},{"type":"note","title":"模型与思路","text":"读数是否稳定，取决于被测物体是否处于平衡状态、以及操作者能不能保持匀速。乙方案中木块静止，始终处于平衡状态，与木板是否匀速无关。"},{"type":"list","title":"解答步骤","items":["甲方案：木块必须匀速直线运动，手很难拉得均匀，示数会随速度变化而晃动。","乙方案：木块被固定住不动，受力始终平衡，示数等于摩擦力且稳定。","比较结论：乙方案操作更容易、读数更稳定，是更合理的改进方案。"]},{"type":"note","title":"结论","text":"改进的实质是把「控制木块匀速」换成「木块保持静止」，用静止这个更容易实现的平衡状态来代替匀速。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["弹簧测力计的示数在任何情况下都等于木块受到的滑动摩擦力","只有木块在水平方向上做匀速直线运动时，示数才等于滑动摩擦力","匀速直线运动时拉力与摩擦力是一对平衡力，大小相等；加速运动时拉力大于摩擦力，减速时拉力小于摩擦力，示数都不等于摩擦力。"],["把木块侧放使接触面积变小，滑动摩擦力也会明显变小","压力与接触面粗糙程度不变时，滑动摩擦力的大小与接触面积无关，示数基本不变","这个实验研究的因素是压力大小和接触面的粗糙程度。侧放只改变了接触面积，压力与粗糙程度都没变，弹簧测力计的示数几乎不变，所以不能说摩擦力与接触面积有关。"],["摩擦力的方向总是与物体的运动方向相反","滑动摩擦力的方向与物体相对接触面的运动方向相反","改进方案里木板向右被拉动，木块相对木板向左滑，木块受到的摩擦力方向向右，与它「随木板移动」的方向一致。判断方向要盯住「相对谁运动」，而不是看物体相对地面怎么动。"],["多次实验是为了取平均值，让摩擦力测得更准","这里多次实验是改变条件、避免偶然性，得出普遍规律；只有同一条件下的重复测量才取平均值","探究性实验的「多次」是通过改变压力或粗糙程度来比较，目的是找出规律，把不同条件下的数据平均反而把规律抹掉了。"]]},{"type":"table","title":"两种测量方案（教材基础方案与改进方案的比较）","head":["比较项","用弹簧测力计拉动木块","把测力计固定，拉动木板、木块不动"],"rows":[["木块的状态","必须做匀速直线运动","相对地面静止"],["是否要求匀速","要求，手很难拉均匀","不要求，木板怎么拉都行"],["读数是否稳定","容易晃动，读数不稳","稳定，容易读准"],["原理","二力平衡：F示 = f","静止状态下二力平衡：F示 = f"]]},{"type":"table","title":"两个影响因素（控制变量法：一次只改变一个因素）","head":["比较项","压力大小","接触面粗糙程度"],"rows":[["怎样改变","在木块上加砝码","在木板上铺毛巾或棉布"],["必须控制不变","同一块木板（粗糙程度相同）","木块与砝码不变（压力相同）"],["数据对比","1.6 N 与 2.4 N 对比","2.4 N 与 3.2 N 对比"],["结论表述","粗糙程度一定时，压力越大，滑动摩擦力越大","压力一定时，接触面越粗糙，滑动摩擦力越大"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["转换法与二力平衡的分析","问「弹簧测力计的示数为什么能表示摩擦力」，答题要用二力平衡说清：匀速直线运动时木块水平方向只受拉力和滑动摩擦力，两者平衡所以相等。若题目改成加速拉动，要说清示数与摩擦力不再相等。"],["控制变量与结论表述","给出几组实验数据，要求判断某两次实验能研究哪个因素、能不能得出某个结论，并写出完整结论。评分关键是结论里必须有「在……一定时」这个条件，以及有没有指明是拿哪两组数据比较。"],["实验装置的改进与评价","给出改进装置（拉动木板、木块静止，或用电机匀速拉传送带），要求说明改进的好处、测力计示数的读数条件、以及改进后为什么不再需要匀速拉动。属于探究与实验类非选择题的常见考法。"]]},{"type":"quote","text":"【材料一】某小组探究滑动摩擦力的大小与哪些因素有关。他们用弹簧测力计沿水平方向匀速拉动放在长木板上的木块，记录读数；然后在木块上放一个砝码重复实验；最后把毛巾铺在木板上、保持木块与砝码不变再重复实验。实验数据如下：木块单独在木板上，压力 4.0 N，摩擦力 1.6 N；木块加砝码在木板上，压力 6.0 N，摩擦力 2.4 N；木块加砝码在毛巾面上，压力 6.0 N，摩擦力 3.2 N。\n【材料二】为了克服「手拉木块难以保持匀速」的困难，老师把弹簧测力计的一端固定在支架上，另一端拉住木块，实验时用手抽动下面的长木板。这样木块保持静止，测力计的示数稳定，读数也准确多了。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】分析材料一的前两组数据，可以得出什么结论？写结论时要注意什么？（3 分）","【设问】根据材料一的三组数据，说明第 2、3 两组数据的比较能研究什么问题，并写出结论。（3 分）","【设问】材料二的改进装置中，为什么不需要让木板做匀速直线运动？测力计的示数为什么仍然等于木块受到的滑动摩擦力？（4 分）"]}],"questions":[{"id":"phy-experiment-3-q1","type":"choice","stem":"如图，用弹簧测力计沿水平方向拉动放在水平木板上的木块。下列说法正确的是","answer":"A","explain":"A 正确：匀速直线运动时木块水平方向只受拉力和滑动摩擦力，两者是一对平衡力，所以示数等于摩擦力。B 错：加速、减速时拉力与摩擦力不再平衡，示数不等于摩擦力。C 错：加速运动时拉力大于摩擦力，示数比摩擦力大。D 错：示数不变只说明拉力稳定，木块可能仍在加速（例如在光滑程度逐渐变化的表面上），判断是否匀速要看木块的运动状态而不是看示数。","options":["木块做匀速直线运动时，弹簧测力计的示数等于木块受到的滑动摩擦力","弹簧测力计的示数在任何情况下都等于木块受到的滑动摩擦力","木块做加速运动时，弹簧测力计的示数等于木块受到的滑动摩擦力","只要弹簧测力计的示数不变，木块就一定在做匀速直线运动"],"difficulty":2,"tags":["转换法","二力平衡"],"figure":{"id":"fig-exp-friction-q1","title":"用弹簧测力计拉动木块","caption":"沿水平方向拉动木块，测力计的示数等于拉力","view":"wide","alt":"水平木板上的木块被弹簧测力计沿水平方向向右拉动，木块受到向右的拉力与向左的摩擦力","prims":[{"t":"line","x1":8,"y1":40,"x2":92,"y2":40,"width":0.8},{"t":"hatch","x":8,"y":40,"w":84,"h":5,"gap":2.2},{"t":"rect","x":30,"y":26,"w":20,"h":14,"fill":true,"tone":"main","label":"木块"},{"t":"spring","x1":50,"y1":33,"x2":64,"y2":33,"coils":6},{"t":"arrow","x1":66,"y1":33,"x2":86,"y2":33,"tone":"accent","label":"F"},{"t":"arrow","x1":30,"y1":33,"x2":12,"y2":33,"tone":"danger","label":"f"},{"t":"text","x":50,"y":54,"text":"木块沿水平方向运动","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-3-q2","type":"choice","stem":"在探究滑动摩擦力的大小与接触面粗糙程度的关系时，下列结论的表述正确的是","answer":"B","explain":"B 正确：结论必须同时交代被控制的变量与变化的变量，这是控制变量法在表述上的要求。A、C 都丢掉了「在……一定时」这个前提，只改变一个因素得出的结论不能推广到另一个因素也在变的情形。D 错：实验数据表明压力同样是决定因素之一（压力从 4.0 N 增到 6.0 N 时摩擦力从 1.6 N 增到 2.4 N），说「只与粗糙程度有关」与数据矛盾。","options":["接触面越粗糙，滑动摩擦力一定越大，不必控制压力相同","在压力一定时，接触面越粗糙，滑动摩擦力越大","压力越大，滑动摩擦力越大，不必控制接触面相同","滑动摩擦力的大小只与接触面的粗糙程度有关"],"difficulty":2,"tags":["结论表述","控制变量"]},{"id":"phy-experiment-3-q3","type":"choice","stem":"在做完「压力大小和接触面粗糙程度都不变，把木块侧放使接触面积变小」的对比实验后，下列说法正确的是","answer":"C","explain":"C 正确：侧放只改变接触面积，压力与粗糙程度都没变，弹簧测力计的示数基本不变，说明滑动摩擦力的大小与接触面积无关。A 错：与实验现象不符，若摩擦力随面积减小而明显变小，示数会有明显差别。B 错：滑动摩擦力的方向与物体相对接触面的运动方向相反，与「运动方向相同」或「相反」不能一概而论。D 错：静止的物体也可能受静摩擦力，例如站在加速的公交车上、被推而未推动的箱子。","options":["压力与粗糙程度不变时，把木块侧放使接触面积变小，滑动摩擦力明显变小","滑动摩擦力的方向总是与物体的运动方向相同","压力与粗糙程度不变时，把木块侧放使接触面积变小，滑动摩擦力基本不变","静止的物体一定不受摩擦力"],"difficulty":3,"tags":["摩擦力","接触面积"]},{"id":"phy-experiment-3-q4","type":"choice","stem":"把弹簧测力计的一端固定在支架上，另一端拉住木块，实验时用手抽动下面的长木板（木块保持静止）。关于这个改进装置，下列说法正确的是","answer":"D","explain":"D 正确：木块相对地面静止，属于平衡状态，水平方向上拉力与滑动摩擦力平衡，示数等于摩擦力，而且木板拉得快慢都不影响读数。A 错：正因为木块静止，才不必要求木板匀速，这正是改进的意义。B 错：重力的方向竖直向下，与水平方向的摩擦力无关。C 错：改进只是改变了拉动方式，木块对木板的压力仍等于木块（连同砝码）的重力，没有变大。","options":["改进后必须让木板做匀速直线运动，否则测力计读数不准","改进后木块受到的滑动摩擦力等于木块和砝码的总重力","改进后木块对木板的压力变大了","拉动木板时木块保持静止，弹簧测力计的示数仍然等于木块受到的滑动摩擦力"],"difficulty":2,"tags":["实验改进"]},{"id":"phy-experiment-3-q5","type":"fill","stem":"用弹簧测力计沿水平方向匀速拉动放在木板上的木块，测力计的分度值为 0.2 N，指针如图位置。此时木块受到的滑动摩擦力是 ______ N。","answer":"2.4|2.4 N|2.4N","explain":"为什么这样读：木块做匀速直线运动，测力计的示数等于滑动摩擦力；测力计分度值 0.2 N，指针在 2 N 之后第二小格处，读作 2.4 N。读数时视线要正对刻度线，示数要带单位。若木块不是匀速运动，示数就不能表示摩擦力，这也是操作中最容易失分的地方。","difficulty":1,"tags":["弹簧测力计","读数"],"figure":{"id":"fig-exp-friction-q5","title":"弹簧测力计的示数","caption":"分度值 0.2 N，指针指在 2.4 N 处","view":"wide","alt":"弹簧测力计的刻度从 0 到 5 牛顿，指针指在 2.4 牛顿的刻度线处","prims":[{"t":"rect","x":38,"y":8,"w":16,"h":44,"tone":"main"},{"t":"spring","x1":46,"y1":12,"x2":46,"y2":30,"coils":6},{"t":"line","x1":46,"y1":30,"x2":46,"y2":44},{"t":"arrow","x1":46,"y1":44,"x2":46,"y2":54,"tone":"accent"},{"t":"line","x1":54,"y1":36,"x2":62,"y2":36,"tone":"accent"},{"t":"text","x":64,"y":36,"text":"2.4 N","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":30,"y":12,"text":"分度值 0.2 N","anchor":"end","size":3.4,"tone":"muted"},{"t":"text","x":46,"y":60,"text":"读数时视线正对刻度线","size":3.4,"tone":"muted"}]}},{"id":"phy-experiment-3-q6","type":"fill","stem":"在同一块木板上，木块对木板的压力为 4.0 N 时匀速拉动，读出摩擦力为 1.6 N；在木块上放一个重 2.0 N 的砝码后仍在该木板上匀速拉动，摩擦力是 ______ N。","answer":"2.4|2.4 N|2.4N","explain":"为什么这样算：接触面是同一块木板，粗糙程度不变，摩擦力与压力的比值不变，1.6 N ÷ 4.0 N = 0.4；放上砝码后压力变为 4.0 N + 2.0 N = 6.0 N，摩擦力就是 0.4 × 6.0 N = 2.4 N。注意压力不是砝码的重力，而是木块与砝码的重力之和；这个比值只是本组实验数据的定量关系，写结论时要用「压力越大，滑动摩擦力越大」这样的定性表述并带上控制变量的条件。","difficulty":2,"tags":["摩擦力计算","控制变量"]},{"id":"phy-experiment-3-q7","type":"short","stem":"某小组在同一块木板上做实验，数据如下：压力 2.0 N 时摩擦力 0.8 N；压力 4.0 N 时摩擦力 1.6 N；压力 6.0 N 时摩擦力 2.4 N。(1) 分析数据能得出什么结论？(2) 若压力为 5.0 N，摩擦约为多少？请写出依据。","answer":"(1) 三次实验中接触面都是同一块木板（粗糙程度相同），摩擦力与压力的比值都是 0.4（0.8÷2.0、1.6÷4.0、2.4÷6.0 都等于 0.4），说明在接触面粗糙程度一定时，压力越大，滑动摩擦力越大，且摩擦力与压力成正比。(2) 由比值 0.4 可得 f = 0.4 × 5.0 N = 2.0 N。","explain":"为什么这么分析：控制变量法要求先确认三次实验中哪些量没变（同一块木板、都是匀速拉动），再比较变化的量。三组数据的比值相同，说明摩擦力与压力成正比，因此可以用比值推算未测过的数据。推算时要注意单位统一（都用 N），并说明这是在粗糙程度不变的前提下的推算。","difficulty":2,"tags":["数据分析","计算"],"rubric":["指出三次实验接触面相同、属于控制变量（1 分）","算出比值 0.4（1 分）","结论完整并带上「接触面粗糙程度一定时」的条件（1 分）","推算得 2.0 N 并带单位（1 分）"],"steps":["说明三次实验的接触面相同（同一块木板），是控制变量后的比较。","分别求比值：0.8 N ÷ 2.0 N = 0.4，1.6 N ÷ 4.0 N = 0.4，2.4 N ÷ 6.0 N = 0.4。","得出结论：接触面粗糙程度一定时，压力越大，滑动摩擦力越大，摩擦力与压力成正比。","推算：f = 0.4 × 5.0 N = 2.0 N。","答：压力为 5.0 N 时摩擦力约为 2.0 N。"]},{"id":"phy-experiment-3-q8","type":"short","stem":"请设计实验探究「滑动摩擦力的大小与接触面的粗糙程度是否有关」。写出器材、操作步骤、需要控制不变的量，以及判断结论的依据。","answer":"器材：弹簧测力计、木块、长木板、毛巾（或棉布）、砝码。步骤：① 把木块放在长木板上，用弹簧测力计沿水平方向匀速拉动木块，读出测力计示数 f₁；② 保持木块与砝码不变，把毛巾铺平并固定在木板上，用同样的方法匀速拉动木块，读出 f₂；③ 比较 f₁ 与 f₂。需要控制不变的量：木块对接触面的压力（木块与砝码都不变）、拉动的方向与方式（都沿水平方向匀速拉动）。判断依据：若 f₂ 大于 f₁，说明压力相同时接触面越粗糙，滑动摩擦力越大；若两次读数基本相同，说明滑动摩擦力与接触面的粗糙程度无关。","explain":"设计的关键在两点：一是用转换法把摩擦力转换成测力计的示数，所以必须沿水平方向匀速拉动、且测力计先校零；二是用控制变量法，只让接触面的粗糙程度变化，压力、拉动方式都要保持不变。铺毛巾时要铺平、固定，避免毛巾被木块拖动而影响读数；两组实验各测三次取平均值可以减小偶然误差。","difficulty":3,"tags":["实验设计","控制变量"],"rubric":["器材完整：弹簧测力计、木块、长木板、毛巾、砝码（1 分）","操作中写明沿水平方向匀速拉动，并用示数表示摩擦力（1 分）","写明控制压力不变的作法（木块与砝码都不变）（1 分）","写出判断依据与结论的完整表述（1 分）"]},{"id":"phy-experiment-3-q9","type":"short","stem":"请画出木块沿水平木板被匀速拉动时的受力示意图，用带箭头的线段表示它受到的各个力，并标出力的符号。","answer":"见参考答案图：竖直方向受到向下的重力 G 与向上的支持力 F支，两者大小相等；水平方向受到向右的拉力 F 与向左的滑动摩擦力 f，两者大小相等。","explain":"作图要点：① 四个力都画在木块上，起点可以取木块中心；② 竖直方向的两个力方向相反、长度相等（因为竖直方向没有运动变化），水平方向的两个力方向相反、长度也相等（匀速直线运动，二力平衡）；③ 符号要标全，重力用 G、支持力用 F支（或 N）、拉力用 F、摩擦力用 f；④ 摩擦力方向要与相对运动方向相反——木块相对木板向右运动，所以摩擦力向左。把摩擦力画成向右是这道题最常见的错误。","difficulty":2,"tags":["作图","受力分析"],"rubric":["四个力都画在木块上（起点取木块中心即可）","竖直方向的重力 G 与支持力 F支 方向相反、线段长度相等","水平方向的拉力 F 与摩擦力 f 方向相反、线段长度相等（匀速直线运动，二力平衡）","四个力的符号标注齐全，且摩擦力方向与木块相对木板的运动方向相反（向左）"],"answerFigure":{"id":"fig-exp-friction-ans1","title":"参考答案：木块的受力示意图","caption":"竖直方向 G 与 F支 平衡，水平方向 F 与 f 平衡","view":"wide","alt":"水平木板上的木块受到四个力：向下的重力、向上的支持力、向右的拉力和向左的摩擦力，竖直与水平方向各自大小相等","prims":[{"t":"line","x1":8,"y1":44,"x2":92,"y2":44,"width":0.8},{"t":"hatch","x":8,"y":44,"w":84,"h":5,"gap":2.2},{"t":"rect","x":38,"y":28,"w":24,"h":16,"fill":true,"tone":"main","label":"木块"},{"t":"arrow","x1":62,"y1":36,"x2":88,"y2":36,"tone":"accent","label":"F"},{"t":"arrow","x1":38,"y1":36,"x2":12,"y2":36,"tone":"danger","label":"f"},{"t":"arrow","x1":50,"y1":28,"x2":50,"y2":8,"tone":"main","label":"F支","labelDx":6},{"t":"arrow","x1":50,"y1":44,"x2":50,"y2":58,"tone":"main","label":"G","labelDx":6},{"t":"text","x":50,"y":62,"text":"匀速直线运动：G = F支，F = f","size":3.6,"tone":"accent"}]}},{"id":"phy-experiment-3-m1-q1","type":"short","stem":"分析材料一的前两组数据，可以得出什么结论？写结论时要注意什么？（3 分）","answer":"前两组数据中接触面都是同一块木板（粗糙程度相同），只有压力发生了变化：压力从 4.0 N 增到 6.0 N，摩擦力从 1.6 N 增到 2.4 N，所以在接触面粗糙程度一定时，压力越大，滑动摩擦力越大。写结论时必须交代「接触面粗糙程度一定」这个前提，并指明是拿第 1、2 两组数据比较。","explain":"","tags":["控制变量","结论表述"],"rubric":["指明对比的是第 1、2 两组数据、且接触面粗糙程度相同（1 分）","写出「压力越大，滑动摩擦力越大」的结论（1 分）","结论中带上「在接触面粗糙程度一定时」这一条件（1 分）"]},{"id":"phy-experiment-3-m1-q2","type":"short","stem":"根据材料一的三组数据，说明第 2、3 两组数据的比较能研究什么问题，并写出结论。（3 分）","answer":"第 2、3 两组数据中压力都是 6.0 N（木块与砝码都没换），只有接触面从木板换成了毛巾，粗糙程度变大，摩擦力从 2.4 N 增到 3.2 N。所以这两组数据研究的是接触面粗糙程度对滑动摩擦力的影响，结论是：在压力一定时，接触面越粗糙，滑动摩擦力越大。","explain":"","tags":["控制变量","摩擦力"],"rubric":["指出两组数据压力相同、接触面材料不同（1 分）","说出研究的是接触面粗糙程度的影响（1 分）","结论完整且带「压力一定时」的条件（1 分）"]},{"id":"phy-experiment-3-m1-q3","type":"short","stem":"材料二的改进装置中，为什么不需要让木板做匀速直线运动？测力计的示数为什么仍然等于木块受到的滑动摩擦力？（4 分）","answer":"改进后木块通过测力计被固定在支架上，实验时木块相对地面（相对支架）始终静止。静止是平衡状态，木块在水平方向上只受到测力计的拉力和木板对它施加的滑动摩擦力，这两个力是一对平衡力，大小相等，所以测力计的示数等于滑动摩擦力。因为平衡条件是「木块静止」，与木板被抽动的快慢、是否匀速无关，所以不必让木板做匀速直线运动，读数还更稳定。","explain":"","tags":["实验改进","二力平衡"],"rubric":["指出木块相对地面静止、处于平衡状态（1 分）","说明水平方向只有拉力与滑动摩擦力两个力（1 分）","用二力平衡得出示数等于滑动摩擦力（1 分）","说明与木板是否匀速无关、读数更稳定（1 分）"]}]},{"id":"phy-experiment-4","title":"探究杠杆的平衡条件：力臂的测量与 F₁l₁ = F₂l₂","subtitle":"实验操作考试 · 必做实验 · all","grade":"all","tags":["实验操作考试 · 必做实验"],"blocks":[{"type":"note","title":"教材位置","text":"实验操作考试 · 必做实验 · all"},{"type":"note","title":"问题切入","text":"跷跷板上一头坐大人、一头坐小孩也能平衡，靠的是什么？力臂到底是从支点到力的作用点的距离，还是支点到力的作用线的距离？为什么实验时一定要先把杠杆调到水平位置？为什么每次实验的数据不能取平均值？"},{"type":"note","title":"一句话抓住关键","text":"杠杆的平衡条件是动力乘动力臂等于阻力乘阻力臂，即 F₁l₁ = F₂l₂，其中力臂 l 是支点到力的作用线的距离（垂线段），不是支点到力的作用点的距离。实验时先调水平平衡，既消除了杠杆自身重力的影响，又能直接从杠杆上读出力臂。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"杠杆平衡实验的关键不是算，而是「力臂怎么量」——它是支点到力的作用线的垂线距离。","walk":["先调平衡：让杠杆在水平位置平衡，方便直接从杠杆上读力臂。","挂钩码改变力和力臂，记录多组数据，避免一组数据的偶然性。","归纳出 F₁l₁ = F₂l₂，再用不同数据验证。"],"try":"用尺子和硬币做杠杆，移动硬币位置，让尺子重新水平平衡。","use":["力臂不是支点到作用点的距离，而是到作用线的垂线段。","弹簧测力计斜拉时力臂变小，示数会变大。"]},{"type":"h","text":"先看现象：杠杆在什么情况下才不转"},{"type":"p","text":"一根硬棒在力的作用下如果能绕着一个固定点转动，它就是杠杆，这个固定点叫支点。杠杆静止不动或者匀速转动，都叫杠杆平衡。跷跷板上一头重一头轻也能停住，说明决定转动的不是力的大小一个因素，力到支点的「距离」同样起作用：力越大、力到支点越远，使杠杆转动的效果就越强。"},{"type":"figure","figure":{"id":"fig-exp-lever-1","title":"杠杆的平衡","caption":"两侧的力与力臂共同决定杠杆是否平衡","view":"wide","alt":"一根水平放置的杠杆中央有支点，左端受到向下的力 F1、力臂为 l1，右端受到向下的力 F2、力臂为 l2","prims":[{"t":"lever","x1":10,"y1":18,"x2":90,"y2":18,"pivot":0.5,"label":"O"},{"t":"arrow","x1":26,"y1":18,"x2":26,"y2":32,"tone":"accent","label":"F₁"},{"t":"arrow","x1":74,"y1":18,"x2":74,"y2":32,"tone":"accent","label":"F₂"},{"t":"arrow","x1":26,"y1":40,"x2":50,"y2":40,"both":true,"tone":"muted","label":"l₁"},{"t":"arrow","x1":50,"y1":40,"x2":74,"y2":40,"both":true,"tone":"muted","label":"l₂"},{"t":"text","x":50,"y":50,"text":"平衡：F₁l₁ = F₂l₂","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"静止或匀速转动都叫杠杆平衡","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"杠杆可以是直的，也可以是弯的（如羊角锤、筷子）；判断省力还是费力，看的是力臂的长短，不是杠杆的形状。"},{"type":"h","text":"力臂的定义：支点到力的作用线的距离"},{"type":"p","text":"力臂不是「支点到力的作用点的距离」，而是「支点到力的作用线的距离」，也就是从支点向力的作用线作垂线，这条垂线段的长度才是力臂。当力的方向与杠杆垂直时，力的作用线正好经过作用点并垂直于杠杆，两者数值一样，容易混淆；一旦力斜着作用，垂线段就比「支点到作用点」的连线短，力臂变小，这时必须用垂线段。"},{"type":"figure","figure":{"id":"fig-exp-lever-2","title":"力臂是支点到力的作用线的距离","caption":"从支点 O 向力 F 的作用线作垂线，垂线段 l 才是力臂","view":"wide","alt":"杠杆右端受到一个斜向左上的力 F，虚线是力的作用线，从支点向这条作用线作垂线，垂线段标为 l，并画有直角符号","prims":[{"t":"lever","x1":10,"y1":30,"x2":90,"y2":30,"pivot":0.3,"label":"O"},{"t":"line","x1":76,"y1":4.3,"x2":96,"y2":41,"dashed":true,"tone":"muted"},{"t":"arrow","x1":90,"y1":30,"x2":78,"y2":8,"tone":"accent","label":"F"},{"t":"line","x1":34,"y1":30,"x2":77.2,"y2":6.5,"tone":"accent","width":0.8},{"t":"text","x":50,"y":13,"text":"l（力臂）","size":3.6,"tone":"accent"},{"t":"angle","x":77.2,"y":6.5,"from":118.6,"to":208.5,"r":5,"right":true},{"t":"text","x":68,"y":42,"text":"支点到作用点的距离不是力臂","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":54,"text":"力的作用线是过作用点沿力的方向的直线","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"画力臂的固定三步：先画力的作用线（用虚线延长），再从支点向它作垂线，最后标出垂足处的直角符号与力臂符号。漏掉直角符号会扣分。"},{"type":"h","text":"实验前的调平：左高左调、右高右调"},{"type":"p","text":"把杠杆的中点支在支架上，先不挂钩码，调节两端的平衡螺母，使杠杆在水平位置静止，这一步叫调平。为什么一定要调水平？一是让杠杆的重心落在支点上（或支点的正上方），杠杆自身重力的力臂为零，不会干扰实验结果；二是杠杆水平时，竖直方向的拉力与杠杆垂直，力臂正好落在杠杆上，可以直接从杠杆上的刻度读出来。调节的方向是「哪端翘起就把螺母向那端调」，也就是左高左调、右高右调。"},{"type":"figure","figure":{"id":"fig-exp-lever-3","title":"杠杆的调平","caption":"左端下沉、右端翘起时，把平衡螺母向右调","view":"wide","alt":"杠杆左端低、右端高，左端的平衡螺母旁有一个向右的箭头，表示应把螺母向翘起的一端调节","prims":[{"t":"lever","x1":14,"y1":30,"x2":86,"y2":14,"pivot":0.5,"label":"O"},{"t":"circle","cx":8,"cy":32,"r":2.5,"fill":true,"tone":"accent","label":"螺母","labelDy":7},{"t":"arrow","x1":20,"y1":28,"x2":44,"y2":22,"tone":"accent","label":"螺母向右调"},{"t":"text","x":78,"y":8,"text":"右端翘起","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":46,"text":"哪端翘起，就把平衡螺母向那端调","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"调平：不挂钩码时杠杆在水平位置静止","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"调平只能在挂钩码之前做。挂上钩码以后如果杠杆不平衡，只能改变钩码的位置或数量，绝不能再动平衡螺母。"},{"type":"h","text":"挂钩码做实验：力臂直接从杠杆上读"},{"type":"p","text":"在杠杆支点两侧挂上不同数量的钩码，每个钩码重 0.5 N。移动钩码的位置直到杠杆重新在水平位置平衡，此时支点左侧钩码的重力就是动力 F₁、它到支点的距离就是动力臂 l₁；右侧钩码的重力是阻力 F₂、它到支点的距离是阻力臂 l₂。因为杠杆是水平的、钩码的重力方向竖直向下，所以力臂就等于钩码悬挂点到支点的距离，可以直接从杠杆上的刻度读出，不需要另作垂线。"},{"type":"figure","figure":{"id":"fig-exp-lever-4","title":"挂钩码测力臂","caption":"每个钩码重 0.5 N，左侧 2 个挂在 15 cm 处，右侧 3 个挂在 10 cm 处","view":"wide","alt":"杠杆在水平位置平衡，支点左侧 15 厘米处挂 2 个钩码，右侧 10 厘米处挂 3 个钩码，两边的力臂用双向箭头标出","prims":[{"t":"text","x":50,"y":8,"text":"每个钩码重 0.5 N","size":3.6,"tone":"muted"},{"t":"lever","x1":10,"y1":26,"x2":90,"y2":26,"pivot":0.5,"label":"O"},{"t":"rect","x":8,"y":30,"w":12,"h":10,"fill":true,"tone":"main","label":"2 个"},{"t":"rect","x":68,"y":30,"w":12,"h":10,"fill":true,"tone":"main","label":"3 个"},{"t":"line","x1":14,"y1":30,"x2":14,"y2":44,"dashed":true,"tone":"muted"},{"t":"line","x1":50,"y1":30,"x2":50,"y2":44,"dashed":true,"tone":"muted"},{"t":"line","x1":74,"y1":30,"x2":74,"y2":44,"dashed":true,"tone":"muted"},{"t":"arrow","x1":14,"y1":46,"x2":50,"y2":46,"both":true,"tone":"accent","label":"l₁ = 15 cm"},{"t":"arrow","x1":50,"y1":46,"x2":74,"y2":46,"both":true,"tone":"accent","label":"l₂ = 10 cm"},{"t":"text","x":50,"y":57,"text":"1.0 N × 15 cm = 1.5 N × 10 cm，杠杆水平平衡","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"钩码要挂在杠杆的刻度位置上而不是随意悬着，否则读到的距离不是力臂；挂好后要微调位置直到杠杆重新水平静止，读数才有效。"},{"type":"h","text":"数据表与结论：多次实验是为了避免偶然性"},{"type":"p","text":"把每次的动力、动力臂、阻力、阻力臂都记进表格，并分别算出 F₁l₁ 与 F₂l₂，会发现每一组数据都满足 F₁l₁ = F₂l₂，这就是杠杆的平衡条件；乘积的单位是 N·cm（也就是力乘长度）。实验中要改变钩码数量和位置做多次，目的是避免偶然性、得出普遍适用的规律，而不是取平均值——平衡条件是一个等式关系，把不同组数据平均反而破坏了两边的对应。"},{"type":"figure","figure":{"id":"fig-exp-lever-6","title":"杠杆平衡条件的实验数据","caption":"每组数据都满足 F₁l₁ = F₂l₂","view":"wide","alt":"五行数据表：三次实验中动力与动力臂的乘积都等于阻力与阻力臂的乘积","prims":[{"t":"rect","x":8,"y":12,"w":84,"h":32,"tone":"main"},{"t":"line","x1":8,"y1":20,"x2":92,"y2":20},{"t":"line","x1":8,"y1":28,"x2":92,"y2":28},{"t":"line","x1":8,"y1":36,"x2":92,"y2":36},{"t":"line","x1":24.8,"y1":12,"x2":24.8,"y2":44},{"t":"line","x1":41.6,"y1":12,"x2":41.6,"y2":44},{"t":"line","x1":58.4,"y1":12,"x2":58.4,"y2":44},{"t":"line","x1":75.2,"y1":12,"x2":75.2,"y2":44},{"t":"text","x":16.4,"y":16,"text":"次数","size":3.2},{"t":"text","x":33.2,"y":16,"text":"F₁/N","size":3.2},{"t":"text","x":50,"y":16,"text":"l₁/cm","size":3.2},{"t":"text","x":66.8,"y":16,"text":"F₂/N","size":3.2},{"t":"text","x":83.6,"y":16,"text":"l₂/cm","size":3.2},{"t":"text","x":16.4,"y":24,"text":"1","size":3.2},{"t":"text","x":33.2,"y":24,"text":"1.0","size":3.2},{"t":"text","x":50,"y":24,"text":"15","size":3.2},{"t":"text","x":66.8,"y":24,"text":"1.5","size":3.2},{"t":"text","x":83.6,"y":24,"text":"10","size":3.2},{"t":"text","x":16.4,"y":32,"text":"2","size":3.2},{"t":"text","x":33.2,"y":32,"text":"1.5","size":3.2},{"t":"text","x":50,"y":32,"text":"10","size":3.2},{"t":"text","x":66.8,"y":32,"text":"1.0","size":3.2},{"t":"text","x":83.6,"y":32,"text":"15","size":3.2},{"t":"text","x":16.4,"y":40,"text":"3","size":3.2},{"t":"text","x":33.2,"y":40,"text":"2.0","size":3.2},{"t":"text","x":50,"y":40,"text":"10","size":3.2},{"t":"text","x":66.8,"y":40,"text":"1.0","size":3.2},{"t":"text","x":83.6,"y":40,"text":"20","size":3.2},{"t":"text","x":50,"y":52,"text":"每组都有 F₁l₁ = F₂l₂，乘积单位是 N·cm","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":59,"text":"多次实验是为了避免偶然性，不是取平均值","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"实验时如果发现某一组数据不满足等式，要先检查力臂是不是读错了（比如把支点到作用点的距离当成了力臂），再下结论。"},{"type":"h","text":"把钩码换成弹簧测力计斜着拉"},{"type":"p","text":"把右侧的钩码换成弹簧测力计，先竖直向下拉使杠杆水平平衡，读出拉力；再让弹簧测力计斜着拉（与杠杆成一定角度），仍然使杠杆在水平位置平衡。两次比较会发现：斜拉时的示数变大了。原因是斜拉时力的作用线不再与杠杆垂直，支点到这条作用线的垂线段（力臂）比原来短，由 F₁l₁ = F₂l₂ 可知，力臂变小就必须用更大的力才能平衡。这正好检验了「力臂是支点到力的作用线的距离」这一条。"},{"type":"figure","figure":{"id":"fig-exp-lever-5","title":"斜着拉时力臂变小","caption":"力斜着作用时，支点到力的作用线的垂线段比竖拉时短，需要的拉力更大","view":"wide","alt":"杠杆左端挂两个钩码，右端用弹簧测力计斜着向上拉，图中画出力的作用线与从支点作出的垂线段，表示力臂变短","prims":[{"t":"lever","x1":10,"y1":20,"x2":90,"y2":20,"pivot":0.5,"label":"O"},{"t":"rect","x":8,"y":24,"w":12,"h":10,"fill":true,"tone":"main","label":"2 个"},{"t":"line","x1":66,"y1":24.6,"x2":94,"y2":8.5,"dashed":true,"tone":"muted"},{"t":"arrow","x1":74,"y1":20,"x2":90,"y2":11,"tone":"accent","label":"F"},{"t":"angle","x":74,"y":20,"from":0,"to":30,"r":8,"label":"30°"},{"t":"line","x1":50,"y1":20,"x2":56,"y2":30.4,"tone":"accent","width":0.8},{"t":"text","x":62,"y":34,"text":"l₂ 变短了","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":46,"text":"力臂变小 → 需要的拉力变大 → 示数变大","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"竖直拉时力臂最长，斜拉时力臂变短","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"测力计要校零，拉力的方向要始终在同一竖直平面内；读数时杠杆必须重新处于水平位置静止，否则读到的力臂不是水平方向上的距离。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["杠杆的平衡条件","F₁ l₁ = F₂ l₂","F：N；l：支点到力的作用线的距离，用 m 或 cm 均可（两边同单位即可）；乘积单位 N·m 或 N·cm · 适用于杠杆处于平衡状态（静止或匀速转动）的情形。l 必须是力臂，即支点到力的作用线的距离；力的方向与杠杆不垂直时，要先作垂线求出力臂再代入。两边长度单位只要一致就行，不必都换成米，因为等式两边都是「力乘长度」。"],["平衡条件的变形（求力）","F₁ = (l₂)/(l₁) F₂","F₁、F₂：N；l₁、l₂ 单位一致 · 用来由已知的力与两个力臂求另一个力，也可以用来判断省力还是费力：当 l₁ > l₂ 时 F₁ < F₂，是省力杠杆（撬棒、羊角锤）；当 l₁ < l₂ 时 F₁ > F₂，是费力杠杆（筷子、钓鱼竿）；当 l₁ = l₂ 时既不省力也不费力（天平）。"],["力臂的定义","力臂 l 是从支点到力的作用线的距离（垂线段）","长度单位 m 或 cm · 只适用于「支点到力的作用线的垂线段」这一含义。力的作用线与杠杆垂直时，力臂正好等于支点到作用点的距离；力斜着作用时两者不等，力臂比它短。把支点到作用点的距离当作力臂，是这类题目最常见的失分原因。"]]},{"type":"h","text":"应用 · 生活应用：用撬棒撬石块"},{"type":"note","title":"情境","text":"一根长 1.2 m 的撬棒，在距前端 0.2 m 处垫一块砖当支点。石块对撬棒的压力是 600 N，作用在前端；人在撬棒的另一端向下压。"},{"type":"note","title":"模型与思路","text":"撬棒是一个杠杆：支点到石块作用点的距离是阻力臂，支点到手作用点的距离是动力臂。由 F₁l₁ = F₂l₂ 求最小动力。"},{"type":"list","title":"解答步骤","items":["确定力臂：阻力臂 l₂ = 0.2 m；动力臂 l₁ = 1.2 m − 0.2 m = 1.0 m。","写出平衡条件并变形：F₁ = F₂l₂ / l₁。","代入：F₁ = 600 N × 0.2 m ÷ 1.0 m = 120 N。"]},{"type":"note","title":"结论","text":"在撬棒末端至少用 120 N 的力就能撬起石块。动力臂越长越省力，这就是「省力杠杆」的道理。"},{"type":"h","text":"应用 · 生活应用：跷跷板怎么坐才平衡"},{"type":"note","title":"情境","text":"一个体重 600 N 的大人与一个体重 300 N 的小孩玩跷跷板，支点在中间。"},{"type":"note","title":"模型与思路","text":"把跷跷板看作杠杆，两人的重力就是动力和阻力，各自到支点的距离就是力臂；要让跷跷板水平平衡，必须满足 F₁l₁ = F₂l₂。"},{"type":"list","title":"解答步骤","items":["取大人为 F₁ = 600 N，坐在距支点 l₁ = 1.0 m 处。","由 F₁l₁ = F₂l₂ 得 l₂ = F₁l₁ / F₂ = 600 N × 1.0 m ÷ 300 N = 2.0 m。","小孩必须坐在距支点 2.0 m 处，跷跷板才能水平平衡。"]},{"type":"note","title":"结论","text":"小孩坐得离支点更远（力臂更大），用较小的力就能与大人平衡。这也解释了为什么小朋友玩跷跷板要往板子末端坐。"},{"type":"h","text":"应用 · 实验应用：由数据判断哪一组数据有问题"},{"type":"note","title":"情境","text":"某小组记录了四组数据：(1.0 N, 15 cm, 1.5 N, 10 cm)；(1.5 N, 10 cm, 1.0 N, 15 cm)；(2.0 N, 10 cm, 1.0 N, 20 cm)；(2.0 N, 10 cm, 1.5 N, 12 cm)。"},{"type":"note","title":"模型与思路","text":"杠杆平衡时两侧的「力乘力臂」必须相等。把每组数据两边的乘积都算出来，不相等的就是有问题的数据。"},{"type":"list","title":"解答步骤","items":["第 1 组：1.0 × 15 = 15，1.5 × 10 = 15，相等。","第 2 组：1.5 × 10 = 15，1.0 × 15 = 15，相等。","第 3 组：2.0 × 10 = 20，1.0 × 20 = 20，相等。","第 4 组：2.0 × 10 = 20，1.5 × 12 = 18，不相等，这一组数据有问题。"]},{"type":"note","title":"结论","text":"第 4 组数据与平衡条件不符，应检查是不是把力臂读错了（例如把支点到钩码悬挂点的距离读成了支点到力的作用线的距离），或重新测量后再记录。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["力臂就是支点到力的作用点的距离","力臂是支点到力的作用线的距离（垂线段）","力的方向与杠杆垂直时两者数值恰好相等，容易记混；一旦力斜着作用，垂线段比「支点到作用点」的连线短，力臂变小，这时需要用更大的力才能平衡。判断方法固定：先画力的作用线，再作垂线。"],["杠杆不平衡时，哪边轻就把平衡螺母往哪边调","哪端翘起（高）就把平衡螺母向那端调，即左高左调、右高右调","把螺母向翘起的一端移动，等于把杠杆这一侧的重心外移、增加这一侧的力和力臂，使翘起的一端下沉，杠杆才能恢复水平平衡。"],["多次实验是为了取平均值，让平衡条件更准确","多次改变力和力臂做实验，是为了避免偶然性、得出普遍规律","平衡条件是一个等式关系，每组数据里的 F₁l₁ 与 F₂l₂ 一一对应；把不同组的数据相加取平均，会破坏这种对应关系，得到的数没有物理意义。"],["杠杆平衡时一定处于水平位置","杠杆静止或匀速转动都叫平衡；实验时调到水平位置是为了方便读力臂","水平位置不是平衡的必要条件，而是实验的便利条件：杠杆水平时，竖直向下的力与杠杆垂直，力臂正好落在杠杆上，可以直接从刻度读出，同时在调平阶段也便于消除杠杆自身重力的影响。"]]},{"type":"table","title":"力臂与「支点到作用点的距离」（两个容易混淆的长度）","head":["比较项","力臂（支点到力的作用线的距离）","支点到力的作用点的距离"],"rows":[["画法","从支点向力的作用线作垂线，标直角符号","把支点与作用点直接连起来"],["什么时候相等","力与杠杆垂直时两者相等","同上，此时恰好相等"],["力斜着作用时","比后者短，等于后者乘夹角的正弦","仍然是原来那么长"],["用错的后果","计算正确","代入平衡条件会得出错误结论"]]},{"type":"table","title":"竖直拉与斜着拉（同样使杠杆水平平衡，两种情况下的比较）","head":["比较项","弹簧测力计竖直向下拉","弹簧测力计与杠杆成一定角度斜着拉"],"rows":[["力的作用线","与杠杆垂直，经过作用点","与杠杆不垂直，偏离作用点"],["力臂","最长，等于支点到作用点的距离","变短"],["需要的拉力","最小","变大，示数变大"],["结论","力臂越大越省力","力臂变小，必须用更大的力"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["力臂作图","给出杠杆与作用在杠杆上的力，要求画出力臂。评分通常看三步：力的作用线有没有用虚线延长、有没有从支点作垂线、垂足处有没有标直角符号。只画一条线而不标直角符号，往往拿不到满分。"],["平衡条件的计算","以撬棒、羊角锤、天平、杆秤为情境，给出一部分力或力臂，求另一个量；或者改变力的方向，问力的大小怎么变。答题要写清「找力臂—代公式—算结果—带单位」，并且在判断省力费力时说明是哪一侧的力臂更长。"],["实验操作与数据处理","考查调平的方向与理由、实验时为什么要在水平位置平衡、为什么要多次实验、实验数据的分析。回答「多次实验的目的」时要区分测量性实验（取平均值减小误差）与探究性实验（改变条件避免偶然性）。"]]},{"type":"quote","text":"【材料一】在探究杠杆平衡条件的实验中，杠杆上相邻刻度线之间的距离都是 5 cm，每个钩码重 0.5 N。小明先把杠杆的中点支在支架上，调节两端的平衡螺母使杠杆在水平位置静止；然后在支点左侧 15 cm 处挂 2 个钩码，在支点右侧 10 cm 处挂 3 个钩码，杠杆恰好重新在水平位置平衡。\n【材料二】接着他把右侧的钩码取下，改用一个弹簧测力计竖直向下拉杠杆的 20 cm 刻度处，使杠杆水平平衡，读出拉力为 1.0 N；随后他让弹簧测力计与杠杆成一定角度斜着拉，仍然使杠杆水平平衡。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据材料一，写出两侧的力与力臂，并验证杠杆的平衡条件。（4 分）","【设问】材料二中，斜着拉时弹簧测力计的示数与竖直拉时相比变大还是变小？请用力臂的概念说明理由。（4 分）","【设问】实验中为什么要先把杠杆调到水平位置平衡？请写出两条理由。（3 分）"]}],"questions":[{"id":"phy-experiment-4-q1","type":"choice","stem":"如图，杠杆右端受到一个斜向左上的力 F，虚线是力 F 的作用线。关于力 F 的力臂，下列说法正确的是","answer":"B","explain":"B 正确：力臂的定义是支点到力的作用线的距离，斜着作用时要作垂线求出这段垂线段。A 错：支点到作用点的距离只在力与杠杆垂直时才等于力臂，本题中力是斜的，两者不相等。C 错：支点到杠杆另一端的距离与力 F 的方向无关，不是力臂。D 错：那是「力与支点到作用点距离的乘积」，不是力臂，它对应的是错误的计算方式。","options":["从支点到力 F 的作用点的距离","从支点到力 F 的作用线的垂线段","从支点到杠杆另一端的距离","力 F 的大小乘以作用点到支点的距离"],"difficulty":2,"tags":["力臂","概念"],"figure":{"id":"fig-exp-lever-q1","title":"斜着作用的力的力臂","caption":"虚线是力 F 的作用线，力臂要从支点向它作垂线","view":"wide","alt":"水平杠杆右端受到斜向左上的力 F，虚线表示力的作用线，支点在杠杆上","prims":[{"t":"lever","x1":10,"y1":30,"x2":90,"y2":30,"pivot":0.3,"label":"O"},{"t":"line","x1":76,"y1":4.3,"x2":96,"y2":41,"dashed":true,"tone":"muted"},{"t":"arrow","x1":90,"y1":30,"x2":78,"y2":8,"tone":"accent","label":"F"},{"t":"text","x":50,"y":50,"text":"力的作用线：过作用点沿力的方向的直线","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-4-q2","type":"choice","stem":"调节杠杆的平衡时，发现杠杆左端下沉、右端翘起。下列操作正确的是","answer":"A","explain":"A 正确：右端翘起说明右端轻，把平衡螺母向右调，等于增大右侧的力与力臂，使右端下沉、杠杆恢复水平，这就是「哪端高就往哪端调」。B 错：向左调会使左端更重，下沉得更厉害。C 错：实验装置中支点固定在支架上，不能随意移动，移动支点也改变了力臂的测量基准。D 错：调平必须在挂任何钩码之前完成，挂上钩码后再调属于操作顺序错误。","options":["把两端的平衡螺母向右调","把两端的平衡螺母向左调","把支点向右移动一段距离","在杠杆的右端挂一个钩码，使杠杆水平"],"difficulty":1,"tags":["调平","操作规范"]},{"id":"phy-experiment-4-q3","type":"choice","stem":"在探究杠杆平衡条件的实验中，多次改变钩码的数量和位置进行实验，其主要目的是","answer":"C","explain":"C 正确：这是一个探究性实验，多组不同条件下的数据都满足同一个等式，才能说明这个规律具有普遍性。A 错：平衡条件是一个等式关系，不同组的数据取平均会破坏两侧的对应关系，没有意义；取平均值是测量性实验（如测长度、测定值电阻）减小误差的做法。B 错：多测几次并不能提高公式本身的精确度。D 错：杠杆自身的重力在调平后就已不影响实验，多次实验也不会改变它。","options":["为了取平均值，减小偶然误差","为了让 F₁l₁ = F₂l₂ 的数值计算得更精确","为了避免偶然性，得出普遍适用的规律","为了改变杠杆自身的重力"],"difficulty":2,"tags":["多次实验","实验目的"]},{"id":"phy-experiment-4-q4","type":"choice","stem":"关于杠杆与杠杆的平衡，下列说法正确的是","answer":"D","explain":"D 正确：平衡的判据是静止或匀速转动，水平位置只是实验的便利条件。A 错：杠杆在倾斜位置静止同样是平衡，天平就是靠指针判断平衡而不必看杠杆是否水平。B 错：由 F₁l₁ = F₂l₂ 可知，力臂越长需要的力越小（省力），说反了。C 错：力斜着作用时两者不等，代错会使计算结果出错，第 4 组数据对不上平衡条件往往就是这个原因。","options":["杠杆平衡时一定处于水平位置","力臂越长，使杠杆平衡所需要的力一定越大","把支点到力的作用点的距离当作力臂代入平衡条件，结果不受影响","杠杆静止或匀速转动都叫杠杆平衡，实验时把杠杆调到水平位置是为了直接从杠杆上读出力臂"],"difficulty":2,"tags":["杠杆平衡","概念"]},{"id":"phy-experiment-4-q5","type":"fill","stem":"杠杆在水平位置平衡，支点左侧 15 cm 处挂着 2 个钩码，每个钩码重 0.5 N。要使杠杆继续平衡，支点右侧 10 cm 处应挂 ______ 个钩码。","answer":"3|3 个|3个","explain":"为什么这样算：由 F₁l₁ = F₂l₂ 得 0.5 N × 2 × 15 cm = 0.5 N × n × 10 cm，即 15 = 5n，解得 n = 3。计算时两侧的钩码重力都要乘个数，力臂是支点到悬挂点的距离（杠杆水平、力的方向竖直，力臂正好落在杠杆上）。若把力臂读成支点到杠杆末端的距离，就会算错。","difficulty":2,"tags":["杠杆平衡条件","计算"]},{"id":"phy-experiment-4-q6","type":"fill","stem":"把弹簧测力计由竖直向下拉改为与杠杆成一定角度斜着拉，仍使杠杆在水平位置平衡，弹簧测力计的示数将 ______（选填「变大」「变小」或「不变」）。","answer":"变大|变大（力臂变小）","explain":"为什么变大：竖直拉时力的作用线与杠杆垂直，力臂最长；斜着拉时力臂是支点到力的作用线的垂线段，比原来短。阻力和阻力臂都没变，由 F₁l₁ = F₂l₂ 可知动力臂变小，动力必须变大，所以示数变大。这也是实验中检验「力臂是支点到力的作用线的距离」的一条常用证据。","difficulty":3,"tags":["力臂","实验现象"]},{"id":"phy-experiment-4-q7","type":"short","stem":"一根长 1.2 m 的撬棒，在距前端 0.2 m 处垫一块砖作为支点。石块对撬棒的压力为 600 N，作用在撬棒的前端；人在撬棒的另一端向下压。(1) 求阻力臂与动力臂；(2) 在撬棒末端至少要用多大的力才能撬起石块？","answer":"(1) 阻力作用在前端，阻力臂 l₂ = 0.2 m；动力作用在末端，动力臂 l₁ = 1.2 m − 0.2 m = 1.0 m。(2) 由 F₁l₁ = F₂l₂ 得 F₁ = F₂l₂/l₁ = 600 N × 0.2 m ÷ 1.0 m = 120 N。","explain":"为什么这样做：先把支点找准，再把四个量一一对应到力臂上——力臂是支点到力的作用线的距离，撬棒水平时两个力都沿竖直方向，力臂就是支点到作用点的距离。由平衡条件变形求力时，力臂的单位两边一致即可，本题都用 m。动力臂 1.0 m 大于阻力臂 0.2 m，所以是省力杠杆，最后的结果 120 N 比 600 N 小得多，与「省力」的判断相符，可以用来检查答案是否合理。","difficulty":2,"tags":["杠杆平衡条件","计算"],"rubric":["正确确定阻力臂 0.2 m（1 分）","正确确定动力臂 1.0 m（1 分）","写出平衡条件并变形（1 分）","代入计算得 120 N，结果带单位（1 分）"],"steps":["画图并标出支点、动力作用点、阻力作用点。","确定力臂：l₂ = 0.2 m，l₁ = 1.2 m − 0.2 m = 1.0 m。","写出平衡条件 F₁l₁ = F₂l₂ 并变形为 F₁ = F₂l₂/l₁。","代入数据：F₁ = 600 N × 0.2 m ÷ 1.0 m = 120 N。","答：在撬棒末端至少用 120 N 的力。"]},{"id":"phy-experiment-4-q8","type":"short","stem":"在探究杠杆平衡条件的实验中：(1) 怎样把杠杆调平？(2) 为什么要在不挂钩码时先调平？请写出调节方法与两条理由。","answer":"(1) 把杠杆的中点支在支架上，先不挂钩码，调节两端的平衡螺母，直到杠杆在水平位置静止；调节方向是「哪端翘起就把平衡螺母向那端调」，即左高左调、右高右调。(2) 理由一：调平后杠杆的重心在支点处，杠杆自身重力的力臂为零，不会干扰实验结果；理由二：杠杆水平时，竖直方向作用的力与杠杆垂直，力臂正好落在杠杆上，可以直接从杠杆上的刻度读出，测量方便且准确。","explain":"为什么必须先调平：如果不调平，杠杆自身重力的力臂不为零，它也会参与使杠杆转动，这时实验数据里就混进了杠杆自重的贡献，得出的 F₁l₁ = F₂l₂ 会不准。调平只能在挂钩码之前做；一旦挂上钩码，只能通过改变钩码的数量或位置使杠杆重新平衡，再动平衡螺母会破坏已经调好的零点。","difficulty":2,"tags":["实验操作","调平"],"rubric":["写出用平衡螺母调节、不挂钩码时使杠杆在水平位置静止（1 分）","写出「哪端高往哪端调」的调节方向（1 分）","说明调平可消除杠杆自身重力的影响（1 分）","说明水平位置时力臂可直接从杠杆刻度读出（1 分）"]},{"id":"phy-experiment-4-q9","type":"short","stem":"如图，弹簧测力计斜着向下拉杠杆。请画出这个拉力的力臂 l，并标注直角符号。","answer":"见参考答案图：先画出拉力 F 的作用线（用虚线延长），再从支点 O 向这条作用线作垂线，垂足处画上直角符号，垂线段 l 就是力臂。","explain":"作图要点：① 力的作用线要沿力的方向用虚线画出并适当延长，才能从支点向它作垂线；② 垂线段要真正垂直，可以用三角板比着画；③ 垂足处必须标直角符号，只画线不标直角往往要扣分；④ 力臂要从支点出发，不能从力的作用点出发——从作用点画出去的是「支点到作用点的距离」，那是最常见的错误画法。","difficulty":3,"tags":["作图","力臂"],"rubric":["沿拉力方向用虚线画出力的作用线并适当延长","从支点 O 向力的作用线作垂线，得到垂线段 l（力臂）","垂足处标出直角符号","力臂从支点出发，而不是从力的作用点出发"],"answerFigure":{"id":"fig-exp-lever-ans1","title":"参考答案：力 F 的力臂","caption":"从支点 O 向力的作用线作垂线，垂线段 l 就是力臂","view":"wide","alt":"杠杆上的斜向下拉力 F 用虚线画出作用线，从支点向这条作用线作垂线得到力臂 l，垂足处有直角符号","prims":[{"t":"lever","x1":10,"y1":30,"x2":90,"y2":30,"pivot":0.3,"label":"O"},{"t":"line","x1":76,"y1":4.3,"x2":96,"y2":41,"dashed":true,"tone":"muted"},{"t":"arrow","x1":90,"y1":30,"x2":78,"y2":8,"tone":"accent","label":"F"},{"t":"line","x1":34,"y1":30,"x2":77.2,"y2":6.5,"tone":"accent","width":0.8},{"t":"angle","x":77.2,"y":6.5,"from":118.6,"to":208.5,"r":5,"right":true},{"t":"text","x":50,"y":14,"text":"l（力臂）","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":52,"text":"力的作用线用虚线画出，垂足处标直角符号","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-4-m1-q1","type":"short","stem":"根据材料一，写出两侧的力与力臂，并验证杠杆的平衡条件。（4 分）","answer":"左侧：F₁ = 2 × 0.5 N = 1.0 N，l₁ = 15 cm；右侧：F₂ = 3 × 0.5 N = 1.5 N，l₂ = 10 cm。计算两边乘积：F₁l₁ = 1.0 N × 15 cm = 15 N·cm，F₂l₂ = 1.5 N × 10 cm = 15 N·cm，两者相等，符合杠杆的平衡条件 F₁l₁ = F₂l₂。","explain":"","tags":["杠杆平衡条件","计算"],"rubric":["正确算出两侧的力（1.0 N 与 1.5 N）（1 分）","正确写出两侧的力臂（15 cm 与 10 cm）（1 分）","分别算出两侧的乘积并比较（1 分）","写出杠杆的平衡条件 F₁l₁ = F₂l₂（1 分）"]},{"id":"phy-experiment-4-m1-q2","type":"short","stem":"材料二中，斜着拉时弹簧测力计的示数与竖直拉时相比变大还是变小？请用力臂的概念说明理由。（4 分）","answer":"示数变大。竖直向下拉时，力的作用线与杠杆垂直，支点到力的作用线的距离最大，力臂最长；斜着拉时力的作用线不再与杠杆垂直，从支点到这条作用线的垂线段变短，也就是力臂变小。由 F₁l₁ = F₂l₂ 可知，在阻力与阻力臂都不变的情况下，动力臂变小，动力就必须变大，所以测力计的示数变大。","explain":"","tags":["力臂","实验说理"],"rubric":["答出「变大」（1 分）","说明竖直拉时力臂最长（力的作用线与杠杆垂直）（1 分）","说明斜拉时力臂是支点到作用线的垂线段、比原来短（1 分）","用 F₁l₁ = F₂l₂ 推出动力变大（1 分）"]},{"id":"phy-experiment-4-m1-q3","type":"short","stem":"实验中为什么要先把杠杆调到水平位置平衡？请写出两条理由。（3 分）","answer":"第一条：调平后杠杆自身的重力作用线经过支点（重心落在支点处），自身重力的力臂为零，不会干扰实验结果。第二条：杠杆水平时，竖直方向作用的力与杠杆垂直，力臂正好落在杠杆上，可以直接从杠杆上的刻度读出力臂，方便又准确。","explain":"","tags":["实验操作","调平"],"rubric":["答出调平能消除杠杆自身重力的影响（1 分）","答出水平时力臂可直接从杠杆刻度读出（1 分）","写出调平的具体操作：不挂钩码时调节平衡螺母使杠杆水平静止（1 分）"]}]},{"id":"phy-experiment-5","title":"探究凸透镜成像规律：物距决定像的性质","subtitle":"实验操作考试 · 必做实验 · all","grade":"all","tags":["实验操作考试 · 必做实验"],"blocks":[{"type":"note","title":"教材位置","text":"实验操作考试 · 必做实验 · all"},{"type":"note","title":"问题切入","text":"照相机、投影仪、放大镜用的都是凸透镜，为什么一个成缩小的像、一个成放大的像，还有一个怎么都接不到光屏上？做实验时为什么第一步要调节烛焰、透镜、光屏三者的高度？光屏上找不到像的时候，该往哪里找原因？"},{"type":"note","title":"一句话抓住关键","text":"凸透镜成像的性质由物距 u 与焦距 f 的关系决定：u 大于二倍焦距成倒立缩小的实像，u 在一倍焦距与二倍焦距之间成倒立放大的实像，u 小于焦距成正立放大的虚像；实像能被光屏承接，虚像不能。实验前必须让烛焰、透镜、光屏三者的中心大致在同一高度。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"蜡烛、透镜、光屏三者的高度没调齐，光屏上就怎么也找不到像——这是实验第一步，也是最容易忘的一步。","walk":["共轴调节：烛焰、透镜、光屏的中心在同一高度。","固定焦距，逐次改变物距，记录像的虚实、大小和正倒。","归纳规律：一倍焦距分虚实，二倍焦距分大小。"],"try":"用放大镜把窗外景物投到白墙上，前后移动找到最清晰的像，观察正倒和大小。","use":["光屏上找不到像：可能成的是虚像，或三者不共轴。","成实像时，像移动的方向与物体移动方向一致。"]},{"type":"h","text":"先看现象：有时光屏上有清晰的像，有时怎么移都接不到"},{"type":"p","text":"把蜡烛、凸透镜、光屏依次放在光具座上，左右移动光屏，有时能在光屏上得到清晰的像，有时无论把光屏移到哪里都只有一片模糊的亮斑。同一个凸透镜、同一支蜡烛，差别只在于蜡烛到透镜的距离。这说明凸透镜成像的性质不是固定的，而是由物距决定的——这就是本实验要探究的规律。"},{"type":"figure","figure":{"id":"fig-exp-lens-1","title":"探究凸透镜成像规律的装置","caption":"蜡烛、凸透镜、光屏依次放在光具座上，光屏上能否接到像与物距有关","view":"wide","alt":"光具座上从左到右依次是蜡烛、凸透镜和光屏，三者都立在导轨上","prims":[{"t":"rect","x":6,"y":34,"w":88,"h":4,"tone":"main","fill":true,"label":"光具座"},{"t":"rect","x":14,"y":22,"w":6,"h":12,"fill":true,"tone":"main","label":"蜡烛"},{"t":"circle","cx":17,"cy":20,"r":2,"fill":true,"tone":"accent"},{"t":"lens","x":44,"y":21,"kind":"convex","h":26,"label":"凸透镜"},{"t":"rect","x":74,"y":14,"w":4,"h":20,"fill":true,"tone":"main","label":"光屏"},{"t":"text","x":50,"y":46,"text":"移动光屏，直到像最清晰为止","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"有时接得到、有时接不到，差别在物距","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"光具座上的刻度尺用来读位置：物距 u 是烛焰到透镜的距离，像距 v 是像（光屏）到透镜的距离，都要用位置读数相减，不能直接读成「离零刻度多远」。"},{"type":"h","text":"第一步：共轴调节，让三心大致在同一高度"},{"type":"p","text":"把蜡烛、凸透镜、光屏依次放在光具座上以后，要调节它们的高度，使烛焰、凸透镜、光屏三者的中心大致在同一高度上，这条线就是透镜的主光轴。这样做的目的是让像成在光屏的中央，便于观察和测量。如果三者的中心不在同一高度，像会落在光屏的上方或下方（甚至光屏之外），无论怎样前后移动光屏都接不到清晰的像。"},{"type":"figure","figure":{"id":"fig-exp-lens-2","title":"共轴调节：三心在同一高度","caption":"烛焰、透镜、光屏的中心大致在同一高度，像才能落在光屏中央","view":"wide","alt":"蜡烛的焰心、凸透镜的光心和光屏的中心大致在同一条水平虚线上","prims":[{"t":"rect","x":6,"y":34,"w":88,"h":4,"tone":"main","fill":true},{"t":"line","x1":8,"y1":21,"x2":92,"y2":21,"dashed":true,"tone":"accent"},{"t":"rect","x":14,"y":23,"w":6,"h":11,"fill":true,"tone":"main","label":"蜡烛"},{"t":"circle","cx":17,"cy":21,"r":2,"fill":true,"tone":"accent"},{"t":"lens","x":44,"y":21,"kind":"convex","h":26,"label":"凸透镜"},{"t":"rect","x":74,"y":8,"w":4,"h":26,"fill":true,"tone":"main","label":"光屏"},{"t":"text","x":50,"y":46,"text":"三者的中心大致在同一高度（共轴）","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"否则像落在光屏以外，怎么移都接不到","size":3.6,"tone":"danger"}]}},{"type":"note","title":"","text":"蜡烛烧短以后烛焰的高度会下降，像会偏离光屏中心，这时要重新调节三者高度（或把光屏、透镜适当上移），不是把光屏乱移一通。"},{"type":"h","text":"物距大于二倍焦距：倒立缩小的实像"},{"type":"p","text":"设凸透镜的焦距 f = 10 cm，把蜡烛放在距透镜 30 cm 处，即 u = 30 cm = 3f，此时 u 大于 2f。移动光屏，在距透镜约 15 cm 处得到清晰的像：像是倒立的，而且比蜡烛小。这就是照相机的原理。作图验证：从烛焰顶端发出的平行于主光轴的光线经透镜折射后过另一侧的焦点，过光心的光线方向不变，两条折射光线的交点就是像的顶端，它在主光轴下方，所以像是倒立的。"},{"type":"figure","figure":{"id":"fig-exp-lens-3","title":"u 大于 2f 时的成像光路","caption":"两条特殊光线相交于像点，得到倒立、缩小的实像","view":"wide","alt":"物在二倍焦距以外，平行于主光轴的光线经透镜后过焦点，过光心的光线方向不变，两条光线在透镜另一侧相交成倒立缩小的实像","prims":[{"t":"line","x1":6,"y1":30,"x2":96,"y2":30,"width":0.6},{"t":"lens","x":42,"y":30,"kind":"convex","h":24},{"t":"arrow","x1":10,"y1":30,"x2":10,"y2":18,"tone":"main","label":"物"},{"t":"line","x1":10,"y1":18,"x2":42,"y2":18},{"t":"arrow","x1":42,"y1":18,"x2":70.2,"y2":40.6,"tone":"accent"},{"t":"arrow","x1":10,"y1":18,"x2":68,"y2":39.75,"tone":"accent"},{"t":"arrow","x1":70.2,"y1":30,"x2":70.2,"y2":40.6,"tone":"danger","label":"像","labelDx":5},{"t":"text","x":12,"y":34,"text":"2F","size":3.4,"tone":"muted"},{"t":"text","x":27,"y":34,"text":"F","size":3.4,"tone":"muted"},{"t":"text","x":57,"y":34,"text":"F","size":3.4,"tone":"muted"},{"t":"text","x":72,"y":34,"text":"2F","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"u 大于 2f：倒立、缩小的实像（照相机）","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":60,"text":"像距在 f 与 2f 之间","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"实像一定在透镜另一侧，且是倒立的；照相机、摄像机、眼睛成的都是这种倒立缩小的实像。"},{"type":"h","text":"物距在一倍焦距与二倍焦距之间：倒立放大的实像，且物近像远像变大"},{"type":"p","text":"把蜡烛移到距透镜 15 cm 处，即 f < u < 2f，移动光屏要在距透镜约 30 cm 处才能得到清晰的像，这时的像是倒立、放大的，这就是投影仪的原理。把蜡烛再向透镜靠近一点（仍在 f 之外），会发现光屏必须往更远处移动才能重新得到清晰的像，而且像更大了——这就是「物近像远像变大」。反过来，把蜡烛远离透镜，像距变小、像也变小。"},{"type":"figure","figure":{"id":"fig-exp-lens-4","title":"在光具座上测物距与像距","caption":"焦距 10 cm，蜡烛在 20.0 cm 处、透镜在 50.0 cm 处，光屏移到 65.0 cm 处得到清晰的像","view":"wide","alt":"光具座上蜡烛位于 20 厘米刻度处，凸透镜位于 50 厘米刻度处，光屏位于 65 厘米刻度处，三者中心在同一条水平虚线上","prims":[{"t":"rect","x":8,"y":32,"w":84,"h":4,"tone":"main","fill":true},{"t":"line","x1":10,"y1":32,"x2":10,"y2":36},{"t":"line","x1":26,"y1":32,"x2":26,"y2":36},{"t":"line","x1":42,"y1":32,"x2":42,"y2":36},{"t":"line","x1":58,"y1":32,"x2":58,"y2":36},{"t":"line","x1":74,"y1":32,"x2":74,"y2":36},{"t":"line","x1":90,"y1":32,"x2":90,"y2":36},{"t":"text","x":10,"y":39.5,"text":"0","size":3},{"t":"text","x":26,"y":39.5,"text":"20","size":3},{"t":"text","x":42,"y":39.5,"text":"40","size":3},{"t":"text","x":58,"y":39.5,"text":"60","size":3},{"t":"text","x":74,"y":39.5,"text":"80","size":3},{"t":"text","x":90,"y":39.5,"text":"100","size":3},{"t":"line","x1":8,"y1":20,"x2":92,"y2":20,"dashed":true,"tone":"accent"},{"t":"rect","x":23,"y":22,"w":6,"h":10,"fill":true,"tone":"main","label":"蜡烛"},{"t":"circle","cx":26,"cy":20,"r":1.8,"fill":true,"tone":"accent"},{"t":"lens","x":50,"y":20,"kind":"convex","h":24},{"t":"rect","x":60,"y":10,"w":4,"h":22,"fill":true,"tone":"main","label":"光屏"},{"t":"text","x":50,"y":48,"text":"u = 50.0 cm − 20.0 cm = 30.0 cm，v = 65.0 cm − 50.0 cm = 15.0 cm","size":3.3,"tone":"accent"},{"t":"text","x":50,"y":57,"text":"物近像远像变大：物距减小时，光屏要向右移","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"读物距、像距时都用「位置读数相减」，并且要读光屏上出现最清晰的像时的位置；像不清晰就把光屏前后微调，直到最清晰为止。"},{"type":"h","text":"物距小于焦距：正立放大的虚像，光屏上接不到"},{"type":"p","text":"把蜡烛移到距透镜 5 cm 处，即 u < f，此时无论把光屏移到哪里都接不到像，只能在透镜另一侧透过透镜看到一个正立、放大的像（这就是放大镜）。原因是此时折射光线是发散的，不会实际相交，只有把它们反向延长才会相交，交点构成的像是虚像。虚像不能成在光屏上，这也是判断实像与虚像最直接的方法。"},{"type":"figure","figure":{"id":"fig-exp-lens-5","title":"u 小于 f 时成正立放大的虚像","caption":"折射光线发散，反向延长线相交成虚像，光屏上接不到","view":"wide","alt":"物在一倍焦距以内，两条折射光线发散，它们的反向延长线在物同侧相交成正立放大的虚像，光屏上无法承接","prims":[{"t":"line","x1":8,"y1":32,"x2":96,"y2":32,"width":0.6},{"t":"lens","x":56,"y":32,"kind":"convex","h":24},{"t":"arrow","x1":46,"y1":32,"x2":46,"y2":22,"tone":"main","label":"物"},{"t":"line","x1":46,"y1":22,"x2":56,"y2":22},{"t":"arrow","x1":56,"y1":22,"x2":92,"y2":46,"tone":"accent"},{"t":"arrow","x1":46,"y1":22,"x2":80,"y2":56,"tone":"accent"},{"t":"line","x1":56,"y1":22,"x2":26,"y2":2,"dashed":true,"tone":"muted"},{"t":"line","x1":46,"y1":22,"x2":26,"y2":2,"dashed":true,"tone":"muted"},{"t":"arrow","x1":26,"y1":32,"x2":26,"y2":2,"tone":"danger","label":"虚像","labelDx":6},{"t":"text","x":41,"y":36,"text":"F","size":3.4,"tone":"muted"},{"t":"text","x":71,"y":36,"text":"F","size":3.4,"tone":"muted"},{"t":"text","x":62,"y":56,"text":"u 小于 f：正立、放大的虚像（放大镜）","size":3.4,"tone":"accent"},{"t":"text","x":62,"y":62,"text":"虚像不能成在光屏上","size":3.4,"tone":"danger"}]}},{"type":"note","title":"","text":"实像与虚像的根本区别：实像由实际光线相交而成，能成在光屏上；虚像由折射光线的反向延长线相交而成，光屏上接不到，只能透过透镜看到。"},{"type":"h","text":"数据表与结论：三段分界"},{"type":"p","text":"把每次的物距、像的性质、像距都记进表格，可以看出像的性质由物距与焦距的关系分成三段：u 大于 2f 时成倒立缩小的实像（像距在 f 与 2f 之间）；u 等于 2f 时成倒立等大的实像（像距也等于 2f，这一点常用来测焦距）；f 小于 u 小于 2f 时成倒立放大的实像（像距大于 2f）；u 小于 f 时成正立放大的虚像，光屏上接不到。判断时先算出 f 与 2f，再看物距落在哪一段。"},{"type":"figure","figure":{"id":"fig-exp-lens-6","title":"凸透镜成像规律的数据","caption":"焦距 10 cm 时的四组实验记录","view":"wide","alt":"四行数据表：物距 30 厘米成倒立缩小实像、像距 15 厘米；物距 20 厘米成倒立等大实像、像距 20 厘米；物距 15 厘米成倒立放大实像、像距 30 厘米；物距 5 厘米成正立放大虚像、光屏不能承接","prims":[{"t":"rect","x":6,"y":12,"w":88,"h":40,"tone":"main"},{"t":"line","x1":6,"y1":20,"x2":94,"y2":20},{"t":"line","x1":6,"y1":28,"x2":94,"y2":28},{"t":"line","x1":6,"y1":36,"x2":94,"y2":36},{"t":"line","x1":6,"y1":44,"x2":94,"y2":44},{"t":"line","x1":22,"y1":12,"x2":22,"y2":52},{"t":"line","x1":46,"y1":12,"x2":46,"y2":52},{"t":"line","x1":76,"y1":12,"x2":76,"y2":52},{"t":"text","x":14,"y":16,"text":"次数","size":3.2},{"t":"text","x":34,"y":16,"text":"物距 u/cm","size":3.2},{"t":"text","x":61,"y":16,"text":"像的性质","size":3.2},{"t":"text","x":85,"y":16,"text":"像距 v/cm","size":3.2},{"t":"text","x":14,"y":24,"text":"1","size":3.2},{"t":"text","x":34,"y":24,"text":"30","size":3.2},{"t":"text","x":61,"y":24,"text":"倒立、缩小、实像","size":3.2},{"t":"text","x":85,"y":24,"text":"15","size":3.2},{"t":"text","x":14,"y":32,"text":"2","size":3.2},{"t":"text","x":34,"y":32,"text":"20","size":3.2},{"t":"text","x":61,"y":32,"text":"倒立、等大、实像","size":3.2},{"t":"text","x":85,"y":32,"text":"20","size":3.2},{"t":"text","x":14,"y":40,"text":"3","size":3.2},{"t":"text","x":34,"y":40,"text":"15","size":3.2},{"t":"text","x":61,"y":40,"text":"倒立、放大、实像","size":3.2},{"t":"text","x":85,"y":40,"text":"30","size":3.2},{"t":"text","x":14,"y":48,"text":"4","size":3.2},{"t":"text","x":34,"y":48,"text":"5","size":3.2},{"t":"text","x":61,"y":48,"text":"正立、放大、虚像","size":3.2},{"t":"text","x":85,"y":48,"text":"不能承接","size":3.2},{"t":"text","x":50,"y":58,"text":"f = 10 cm：先算 f 与 2f，再看物距落在哪一段","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"u = 2f 时成倒立等大的实像，这一组数据可以用来测焦距：f 等于这时的物距的一半。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["成像性质的分段判断","u > 2f ⇒ 倒立、缩小的实像","u：物距，f：焦距，单位一致（cm 或 m） · 判断前必须先算出 f 与 2f，再看物距落在哪一段：u 大于 2f 成倒立缩小实像（照相机）；u 等于 2f 成倒立等大实像（此时 v 也等于 2f，可用来测焦距）；f 小于 u 小于 2f 成倒立放大实像（投影仪）；u 等于 f 不成像（折射光平行射出）；u 小于 f 成正立放大虚像（放大镜），光屏上接不到。"],["测焦距（平行光聚焦法）","f = d","f、d 单位都是 cm 或 m · d 是透镜光心到最小最亮光斑的距离，条件必须是让凸透镜正对平行光（太阳光），并且光斑调到最小最亮。若透镜没有正对光源，或光斑没有调到最小，测出的 d 会偏大，不是焦距。也可以在实验中用 u = 2f 成等大实像的方法测焦距。"],["物距与像距的测量","u = |x_(烛) - x_(镜)|","x 为光具座上的位置读数，单位 cm · u 是烛焰到透镜光心的距离，v 是光屏（像）到透镜光心的距离，都用位置读数相减。使用条件是三者中心已调到同一高度；读数前要让像最清晰，并且像距要读光屏的位置而不是读「光屏到光具座零刻度」的距离。"]]},{"type":"h","text":"应用 · 生活应用：照相机、投影仪与放大镜"},{"type":"note","title":"情境","text":"用手机拍远处的风景时像很小；用投影仪把课件投到屏幕上时像很大；用放大镜看邮票上的字时看到的是正立放大的字。"},{"type":"note","title":"模型与思路","text":"三者都是凸透镜成像，区别只在物距落在哪一段：u 大于 2f 成倒立缩小实像，f 小于 u 小于 2f 成倒立放大实像，u 小于 f 成正立放大虚像。"},{"type":"list","title":"解答步骤","items":["照相机、手机镜头：被拍物体在二倍焦距以外，成倒立缩小的实像，像距在 f 与 2f 之间。","投影仪：幻灯片在一倍焦距与二倍焦距之间，成倒立放大的实像，屏幕要在二倍焦距以外。","放大镜：邮票在一倍焦距以内，成正立放大的虚像，虚像不能成在光屏上，只能透过透镜看到。"]},{"type":"note","title":"结论","text":"要改变像的大小，就改变物距：物近像远像变大，物远像近像变小，但物距一旦小于焦距，像就变成虚像，光屏上再也接不到了。"},{"type":"h","text":"应用 · 实验应用：用平行光聚焦法测焦距"},{"type":"note","title":"情境","text":"在阳光下用一张白纸和一个凸透镜，可以在纸上得到一个很小很亮的光斑。"},{"type":"note","title":"模型与思路","text":"太阳光可看作平行光。平行于主光轴的光线经凸透镜折射后会聚于焦点，最小最亮的光斑处就是焦点，光斑到透镜光心的距离就是焦距 f。"},{"type":"list","title":"解答步骤","items":["让凸透镜正对太阳光（正对，不是斜着放），在白纸上得到光斑。","上下移动白纸或透镜，直到纸上的光斑最小最亮，此时光斑在焦点上。","用刻度尺量出光斑到透镜光心的距离 d，则 f = d。"]},{"type":"note","title":"结论","text":"若测得 d = 10 cm，则这个凸透镜的焦距是 10 cm。若透镜没有正对太阳光，光斑不会最小最亮，测出的距离会偏大。"},{"type":"h","text":"应用 · 实验应用：由物距判断像的性质与光屏位置"},{"type":"note","title":"情境","text":"已知凸透镜的焦距为 10 cm，把蜡烛放在距透镜 30 cm 处。"},{"type":"note","title":"模型与思路","text":"先算出 2f = 20 cm，比较物距与 2f 的大小判断像的性质，再根据「物远像近」判断光屏移动的方向：u 大于 2f 时成倒立缩小的实像，像距在 f 与 2f 之间。"},{"type":"list","title":"解答步骤","items":["比较：u = 30 cm，2f = 20 cm，所以 u 大于 2f。","判断像的性质：倒立、缩小的实像。","判断光屏位置：像距在 10 cm 与 20 cm 之间，应把光屏放在透镜后 10 至 20 cm 的范围内移动，直到像最清晰。","可用来验证：u = 30 cm、v = 15 cm 时，物距变成原来的三倍、像距是物距的一半，符合这组实验数据。"]},{"type":"note","title":"结论","text":"物距大于二倍焦距时得到倒立缩小的实像，光屏要放在一倍焦距与二倍焦距之间。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["只要把光屏放在透镜后面，总能承接到底片上的像","只有实像能被光屏承接；物距小于焦距时成虚像，光屏上接不到","虚像是折射光线的反向延长线相交形成的，那个交点处并没有实际光线会聚，所以光屏上只有一片光斑，无论把光屏移到哪里都得不到清晰的像。"],["蜡烛烧短了不用管，光屏上照样能看到完整的像","烛焰中心下降后像会偏离光屏中心，必须重新调节三者的高度使中心大致在同一高度","凸透镜成像是按「三心共轴」的条件把像成在光屏中央的。烛焰变低，像的位置随之偏移，甚至有一部分落到光屏以外，所以要么调节高度，要么把光屏相应上下移动。"],["像距就是光屏到光具座零刻度的距离","像距是像到透镜光心的距离，等于光屏的位置读数减去透镜的位置读数","物距、像距都是相对透镜而言的。若直接用光屏的位置读数当像距，得到的是一个与透镜位置有关的错数，代入任何判断都会出错。"],["物距减小时像一定变小","在成实像的范围内，物距减小像距变大、像变大；一旦物距小于焦距，像变成虚像，光屏上接不到","「物近像远像变大」有前提：必须仍然能成实像，即 u 大于 f。u 小于 f 时规律不再适用，此时像的正倒、虚实都变了。"]]},{"type":"table","title":"实像与虚像（两种像的形成方式与观察方式）","head":["比较项","实像","虚像"],"rows":[["形成原因","实际光线会聚而成","折射光线的反向延长线相交而成"],["能否用光屏承接","能，成在光屏上","不能，光屏上只有光斑"],["正倒","一定是倒立的","一定是正立的"],["典型应用","照相机、投影仪、眼睛","放大镜、平面镜成的像"]]},{"type":"table","title":"物距大于 2f 与物距在 f 与 2f 之间（两段成像范围的对照）","head":["比较项","u 大于 2f","f 小于 u 小于 2f"],"rows":[["像的性质","倒立、缩小的实像","倒立、放大的实像"],["像距范围","f 与 2f 之间","大于 2f"],["应用","照相机、摄像机","投影仪、幻灯机"],["物距减小时","像距变大、像变大","像距变大、像变大（光屏要向右移）"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["成像规律的判断与计算","给出焦距与物距，要求判断像的正倒、大小、虚实，并说明光屏应放在什么范围内。固定做法是先算 2f，把物距与 f、2f 比较，再按分段规律作答；问「光屏应向哪边移动」时，用「物近像远」判断方向。"],["实验器材调节与故障排查","考查共轴调节的方法与理由、光屏上找不到像的原因、蜡烛变短后像怎么偏移、如何用 u = 2f 成等大实像来测焦距。回答「找不到像」时要给出可排查的原因：物距小于焦距、三心不在同一高度、光屏位置超出光具座范围、像没有调到最清晰。"],["生活应用与光路作图","以照相机、投影仪、放大镜、近视眼镜为情境考查成像规律的应用，或要求画出两条特殊光线（平行于主光轴的光线过焦点、过光心的光线方向不变）确定像的位置。作图时要注意箭头方向与倒立像的画法。"]]},{"type":"quote","text":"【材料一】某小组用焦距为 10 cm 的凸透镜做探究实验。他们把蜡烛、凸透镜、光屏依次放在光具座上，调节三者的高度后，记录了四组数据：物距 30 cm 时，光屏移到距透镜 15 cm 处得到清晰的像；物距 20 cm 时，光屏在 20 cm 处得到清晰的像；物距 15 cm 时，光屏在 30 cm 处得到清晰的像；物距 5 cm 时，无论把光屏移到哪里都得不到像。\n【材料二】实验进行到一半时蜡烛烧短了一截，同学们发现光屏上原本清晰的像变得模糊，而且位置偏高。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据材料一的四组数据，分别写出每种情况下像的性质。（4 分）","【设问】材料一中物距为 30 cm 时，像距是 15 cm。若把蜡烛向透镜靠近到物距 15 cm，光屏应该向哪个方向移动？像的大小怎样变化？（3 分）","【设问】根据材料二，蜡烛烧短后为什么光屏上的像会变模糊、位置偏高？应该怎样调节？（3 分）"]}],"questions":[{"id":"phy-experiment-5-q1","type":"choice","stem":"凸透镜的焦距为 10 cm，把蜡烛放在距透镜 30 cm 处，移动光屏直到得到清晰的像。下列说法正确的是","answer":"B","explain":"B 正确：f = 10 cm，2f = 20 cm，物距 30 cm 大于 2f，成倒立、缩小的实像，像距在 f 与 2f 之间，所以光屏要放在 10 cm 到 20 cm 之间（本模块的实验数据是 15 cm）。A 错：像距大于 20 cm 对应的是物距在 f 与 2f 之间的情形，与本题条件不符。C 错：虚像只能在物距小于焦距时出现，而且虚像不能成在光屏上。D 错：物距大于焦距就一定能成实像，只要光屏放对位置就能接到。","options":["光屏上得到倒立、缩小的实像，光屏到透镜的距离应大于 20 cm","光屏上得到倒立、缩小的实像，光屏到透镜的距离应在 10 cm 与 20 cm 之间","光屏上得到正立、放大的虚像","无论怎样移动光屏都接不到像"],"difficulty":2,"tags":["成像规律","物距分段"],"figure":{"id":"fig-exp-lens-q1","title":"蜡烛在二倍焦距以外","caption":"焦距 10 cm，蜡烛在距透镜 30 cm 处","view":"wide","alt":"光具座上蜡烛距凸透镜较远，光屏放在透镜另一侧较近的位置","prims":[{"t":"rect","x":6,"y":34,"w":88,"h":4,"tone":"main","fill":true,"label":"光具座"},{"t":"rect","x":14,"y":22,"w":6,"h":12,"fill":true,"tone":"main","label":"蜡烛"},{"t":"circle","cx":17,"cy":20,"r":2,"fill":true,"tone":"accent"},{"t":"lens","x":60,"y":21,"kind":"convex","h":26,"label":"凸透镜"},{"t":"rect","x":72,"y":14,"w":4,"h":20,"fill":true,"tone":"main","label":"光屏"},{"t":"text","x":37,"y":46,"text":"u = 30 cm","size":3.6,"tone":"accent"},{"t":"text","x":78,"y":46,"text":"v = ?","size":3.6,"tone":"accent"}]}},{"id":"phy-experiment-5-q2","type":"choice","stem":"把蜡烛放在距凸透镜 15 cm 处（凸透镜的焦距为 10 cm），要在光屏上得到清晰的像，下列做法正确的是","answer":"A","explain":"A 正确：f = 10 cm、2f = 20 cm，物距 15 cm 在 f 与 2f 之间，成倒立、放大的实像，像距大于 2f，所以光屏要放在距透镜 20 cm 以外（本模块数据是 30 cm）处，并左右微调找到最清晰的位置。B 错：10 cm 处是一倍焦距处，那里得不到清晰的实像。C 错：实像一定成在透镜的另一侧，不可能出现在透镜与蜡烛之间。D 错：把蜡烛向透镜靠近会使物距更小，一旦小于 10 cm 就变成虚像，光屏上永远接不到。","options":["把光屏放在距透镜 30 cm 附近，左右移动光屏直到像最清晰","把光屏放在距透镜 10 cm 处即可","把光屏放在凸透镜与蜡烛之间","把蜡烛向透镜靠近，直到光屏上出现像"],"difficulty":2,"tags":["成像规律","实验操作"]},{"id":"phy-experiment-5-q3","type":"choice","stem":"关于凸透镜成像的应用，下列说法正确的是","answer":"C","explain":"C 正确：放大镜把物体放在一倍焦距以内，成正立、放大的虚像，虚像不能成在光屏上。A 错：照相机成的是倒立、缩小的实像，物体在二倍焦距以外。B 错：投影仪成的是倒立、放大的实像，幻灯片在一倍焦距与二倍焦距之间，屏幕在二倍焦距以外。D 错：放大镜成的是虚像，不能承接，把三种仪器一概说成实像是把成像性质记混了。","options":["照相机利用了凸透镜成倒立、放大实像的规律","投影仪利用了凸透镜成正立、放大虚像的规律","放大镜利用了凸透镜成正立、放大虚像的规律，此时物距小于焦距","三种仪器成的都是实像，都能用光屏承接"],"difficulty":1,"tags":["生活应用","成像规律"]},{"id":"phy-experiment-5-q4","type":"choice","stem":"在探究凸透镜成像规律的实验中，下列关于操作的说明正确的是","answer":"D","explain":"D 正确：三心共轴是像能落在光屏中央的前提，凡是「找不到像」，第一步就应检查这一点。A 错：焦距、物距、三者高度、光屏位置都可能造成找不到像，不能只归因于焦距。B 错：蜡烛烧短后烛焰中心下降，像的位置随之偏移。C 错：物距等于焦距时折射光线平行射出，不成像；成倒立等大实像对应的是物距等于二倍焦距。","options":["光屏上始终得不到像，一定是凸透镜的焦距太大","蜡烛烧短后像的位置不会改变","物距等于焦距时成倒立、等大的实像","若烛焰、透镜、光屏三者的中心不在同一高度，像可能落在光屏以外，应调节三者的高度使中心大致在同一高度"],"difficulty":2,"tags":["实验操作","故障排查"]},{"id":"phy-experiment-5-q5","type":"fill","stem":"凸透镜的焦距为 10 cm，把蜡烛放在距透镜 30 cm 处，在光屏上得到清晰的像。此时像距是 ______ cm。","answer":"15|15 cm|15cm","explain":"为什么是 15 cm：物距 30 cm 时成倒立、缩小的实像，像距应在 f 与 2f 之间。本模块的实验数据给出 u = 30 cm 时 v = 15 cm，可以这样核对：像距是物距的一半（15 cm = 30 cm ÷ 2），并且落在 10 cm 与 20 cm 之间，符合规律。若把蜡烛移到 15 cm 处，像距就变成 30 cm，像变成倒立放大的实像。","difficulty":2,"tags":["成像规律","像距"]},{"id":"phy-experiment-5-q6","type":"fill","stem":"凸透镜的焦距是 10 cm。当物距为 25 cm 时，所成的像是倒立、______ 的实像（选填「缩小」「等大」或「放大」）。","answer":"缩小|缩小的","explain":"为什么是缩小：先算 2f = 20 cm，物距 25 cm 大于 2f，落在「u 大于 2f」这一段，成倒立、缩小的实像。若物距正好是 20 cm 则是等大，物距在 10 cm 与 20 cm 之间是放大。判断这类题目的固定顺序是：先算 2f，再把物距与 f、2f 比较，最后写像的性质。","difficulty":2,"tags":["成像规律","物距分段"]},{"id":"phy-experiment-5-q7","type":"short","stem":"某小组用焦距为 10 cm 的凸透镜做实验，得到三组数据：u = 30 cm 时 v = 15 cm；u = 20 cm 时 v = 20 cm；u = 15 cm 时 v = 30 cm。(1) 分析数据说明物距与像距怎样相互变化？(2) 当 u = 18 cm 时，像距应在什么范围内？成的像有什么特点？","answer":"(1) 由数据可以看出：物距从 30 cm 减小到 15 cm 的过程中，像距从 15 cm 增大到 30 cm，说明物距减小时像距变大，即「物近像远」；同时由表格可推知像也变大。(2) u = 18 cm 在 15 cm 与 20 cm 之间，而 u = 15 cm 时 v = 30 cm、u = 20 cm 时 v = 20 cm，物距连续变化时像距也连续变化，所以像距应在 20 cm 到 30 cm 之间；又因为 18 cm 在 f（10 cm）与 2f（20 cm）之间，所以成的是倒立、放大的实像。","explain":"为什么用「范围」而不是算一个确切值：初中不要求用透镜的成像公式计算像距，判断像距范围靠两点——一是物距落在哪一段（决定像距大于 2f 还是在 f 与 2f 之间），二是用已有的两组数据夹逼（u 在 15 cm 与 20 cm 之间，v 就在 30 cm 与 20 cm 之间）。分析数据时必须强调「物距连续变化」，这样才能由两组数据推出中间的值。","difficulty":3,"tags":["数据分析","成像规律"],"rubric":["由数据得出「物距减小、像距变大」的规律（1 分）","正确算出 f 与 2f（1 分）","判断出像距范围 20—30 cm（1 分）","判断出像是倒立、放大的实像（1 分）"],"steps":["列出三组数据，指出物距减小、像距变大（物近像远）。","算出 f = 10 cm、2f = 20 cm。","判断 18 cm 所在的区间：f 小于 18 cm 小于 2f。","判断像距范围：把 18 cm 夹在 15 cm 与 20 cm 之间，对应的像距就夹在 30 cm 与 20 cm 之间。","答：像距在 20 cm 到 30 cm 之间，成倒立、放大的实像。"]},{"id":"phy-experiment-5-q8","type":"short","stem":"在探究凸透镜成像规律的实验中：(1) 为什么要先调节烛焰、凸透镜、光屏三者的中心大致在同一高度？(2) 如果无论怎样移动光屏都找不到清晰的像，请写出三种可能的原因。","answer":"(1) 这样可以使像成在光屏的中央，便于观察和测量（否则像可能落在光屏以外）；同时也保证物距、像距是在同一条主光轴上测量的，读数才有意义。(2) 可能的原因：① 物距小于焦距（u 小于 f），成的是虚像，光屏上接不到；② 三者的中心不在同一高度，像落在光屏以外；③ 物距略大于焦距时像距很大，光屏已经移到光具座的端点仍够不到；④ 光屏放在了一倍焦距以内（透镜与蜡烛之间），实像不可能出现在那里；⑤ 像没有调到最清晰就读数，看到的总是一片光斑。","explain":"为什么把「共轴」放在第一位检查：凸透镜成像必须沿主光轴进行，三心不在同一高度时，像虽然存在，却可能整体落在光屏以外，表现出的现象与「不成像」很像，所以排查时先看这一点，再看物距落在哪一段（区分实像与虚像），最后看光屏的位置范围是否合适。回答这类题要给出「可操作的原因」，不要只写「实验误差」。","difficulty":3,"tags":["实验设计","故障排查"],"rubric":["说明共轴能使像成在光屏中央、便于观察与测量（1 分）","写出原因一：物距小于焦距成虚像，光屏接不到（1 分）","写出原因二：三者中心不在同一高度（1 分）","写出原因三：光屏位置超出应放的范围（或像距太大、光具座长度不够）（1 分）"]},{"id":"phy-experiment-5-q9","type":"short","stem":"请画出物距大于二倍焦距时凸透镜成像的光路示意图：画出两条特殊光线，标出物、像与焦点 F、二倍焦距 2F 的位置。","answer":"见参考答案图：从物（烛焰）顶端画两条光线——一条平行于主光轴射向透镜，折射后经过另一侧的焦点 F；另一条经过光心，方向不改变。两条折射光线相交于一点，这一点就是像的顶端，由此得到倒立、缩小的实像，像的位置在另一侧的一倍焦距与二倍焦距之间。","explain":"作图要点：① 两条特殊光线是「平行于主光轴的光线过焦点」和「过光心的光线方向不变」，画出这两条就能定出像点；② 像必须画在透镜另一侧、主光轴的下方（倒立），并且比物短（缩小）；③ 焦点 F 与二倍焦距 2F 要在主光轴两侧对称标出；④ 光线要带箭头表示方向，从物出发、经透镜后射向像。只画一条光线不能确定像的位置。","difficulty":3,"tags":["作图","光路图"],"rubric":["画出两条特殊光线：平行于主光轴的光线经透镜后过焦点；过光心的光线方向不变","两条光线相交定出像的位置，像在透镜另一侧、主光轴下方（倒立）","像比物短，体现「缩小」","焦点 F 与二倍焦距 2F 在主光轴两侧对称标出，光线带箭头表示方向"],"answerFigure":{"id":"fig-exp-lens-ans1","title":"参考答案：u 大于 2f 的光路图","caption":"两条特殊光线的交点就是像的顶端","view":"wide","alt":"物在二倍焦距以外，平行于主光轴的光线折射后过焦点，过光心的光线方向不变，两条光线在透镜另一侧相交成倒立缩小的实像，主光轴上标出一倍焦距与二倍焦距的位置","prims":[{"t":"line","x1":6,"y1":30,"x2":96,"y2":30,"width":0.6},{"t":"lens","x":42,"y":30,"kind":"convex","h":24,"label":"凸透镜"},{"t":"arrow","x1":10,"y1":30,"x2":10,"y2":18,"tone":"main","label":"物"},{"t":"line","x1":10,"y1":18,"x2":42,"y2":18},{"t":"arrow","x1":42,"y1":18,"x2":70.2,"y2":40.6,"tone":"accent"},{"t":"arrow","x1":10,"y1":18,"x2":68,"y2":39.75,"tone":"accent"},{"t":"arrow","x1":70.2,"y1":30,"x2":70.2,"y2":40.6,"tone":"danger","label":"像","labelDx":5},{"t":"text","x":12,"y":35,"text":"2F","size":3.4,"tone":"muted"},{"t":"text","x":27,"y":35,"text":"F","size":3.4,"tone":"muted"},{"t":"text","x":57,"y":35,"text":"F","size":3.4,"tone":"muted"},{"t":"text","x":72,"y":35,"text":"2F","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":54,"text":"平行于主光轴的光线过焦点，过光心的光线方向不变","size":3.4,"tone":"accent"}]}},{"id":"phy-experiment-5-m1-q1","type":"short","stem":"根据材料一的四组数据，分别写出每种情况下像的性质。（4 分）","answer":"焦距 f = 10 cm，所以 2f = 20 cm。物距 30 cm 大于 2f，成倒立、缩小的实像；物距 20 cm 等于 2f，成倒立、等大的实像；物距 15 cm 在 f 与 2f 之间，成倒立、放大的实像；物距 5 cm 小于 f，成正立、放大的虚像，不能在光屏上承接。","explain":"","tags":["成像规律","数据判断"],"rubric":["先算出 f = 10 cm、2f = 20 cm（1 分）","物距 30 cm 与 15 cm 两种情况的性质判断正确（1 分）","物距 20 cm 判断为倒立、等大的实像（1 分）","物距 5 cm 判断为正立、放大的虚像并说明光屏接不到（1 分）"]},{"id":"phy-experiment-5-m1-q2","type":"short","stem":"材料一中物距为 30 cm 时，像距是 15 cm。若把蜡烛向透镜靠近到物距 15 cm，光屏应该向哪个方向移动？像的大小怎样变化？（3 分）","answer":"物距从 30 cm 减小到 15 cm，物距变小，像距变大（从 15 cm 变到 30 cm），所以光屏应该向远离透镜的方向（向右）移动，才能重新得到清晰的像；同时像变大，由倒立缩小的实像变成倒立放大的实像。","explain":"","tags":["物近像远","实验操作"],"rubric":["答出光屏向远离透镜的方向移动（1 分）","说明物距减小时像距变大（1 分）","说明像变大（由缩小变为放大）（1 分）"]},{"id":"phy-experiment-5-m1-q3","type":"short","stem":"根据材料二，蜡烛烧短后为什么光屏上的像会变模糊、位置偏高？应该怎样调节？（3 分）","answer":"蜡烛烧短后，烛焰的中心（也就是物体的中心）降低了，而凸透镜与光屏的高度没有变，三者的中心不再大致在同一高度，成像的光路随之改变，像的位置升高、变得模糊。调节方法：重新调节三者的高度，把凸透镜（或光屏）适当向上移动、或把蜡烛垫高，使烛焰、透镜、光屏的中心重新大致在同一高度，像就会重新落在光屏中央并变得清晰。","explain":"","tags":["共轴调节","故障排查"],"rubric":["指出烛焰中心降低、三心不再在同一高度（1 分）","说明这是像偏离光屏中心、变模糊的原因（1 分）","写出调节方法：重新调节三者高度使中心大致在同一高度（1 分）"]}]},{"id":"phy-experiment-6","title":"伏安法测电阻与测量小灯泡的电功率","subtitle":"实验操作考试 · 必做实验 · all","grade":"all","tags":["实验操作考试 · 必做实验"],"blocks":[{"type":"note","title":"教材位置","text":"实验操作考试 · 必做实验 · all"},{"type":"note","title":"问题切入","text":"同一个电路，为什么测小灯泡的电阻时不能说「这个灯泡的电阻是某个定值」？为什么连接电路时必须先把开关断开、把滑动变阻器调到阻值最大？电流表的指针不偏转而电压表的示数接近电源电压，说明哪里出了问题？"},{"type":"note","title":"一句话抓住关键","text":"伏安法用电流表串联测电流、电压表并联测电压，再由 R = U/I 求电阻；测电功率时用 P = UI。滑动变阻器既保护电路（接入最大电阻限制电流），又能改变电压实现多次测量。灯丝电阻随温度升高而变大，所以小灯泡在各电压下测得的电阻不同，不能取平均值。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"测电阻和测电功率用的是同一套电路，区别只在最后「代入哪个公式」。","walk":["连接：开关断开、滑片调到最大、电流表串联、电压表并联。","测量：移动滑片改变电压，记录多组 U、I。","计算：定值电阻用 R = U/I 求平均；小灯泡用 P = UI，电阻随温度变化不求平均。"],"try":"按图连接测一个定值电阻，记录三组数据，画出 I-U 图像看是否为直线。","use":["故障：灯不亮但电压表有示数，多半是灯泡断路。","只有额定电压下的功率才是额定功率。"]},{"type":"h","text":"先看器材与电路：伏安法测电阻"},{"type":"p","text":"测量一个定值电阻的阻值，需要一个电源（3 V，两节干电池）、一个开关、一个电流表、一个电压表、一个滑动变阻器、待测电阻和若干导线。电路这样接：电源、开关、滑动变阻器、电流表、待测电阻依次串联成回路；电压表并联在待测电阻的两端。这样电流表测的是通过电阻的电流 I，电压表测的是电阻两端的电压 U，由 R = U/I 就能算出电阻。"},{"type":"figure","figure":{"id":"fig-exp-elec-1","title":"伏安法测电阻的电路","caption":"电流表串联、电压表并联在待测电阻两端，滑动变阻器串联在电路中","view":"wide","alt":"电源、开关、滑动变阻器、电流表和待测电阻依次串联成回路，电压表并联在待测电阻两端","prims":[{"t":"line","x1":14,"y1":14,"x2":22,"y2":14},{"t":"line","x1":36,"y1":14,"x2":44,"y2":14},{"t":"line","x1":56,"y1":14,"x2":60,"y2":14},{"t":"line","x1":84,"y1":14,"x2":86,"y2":14},{"t":"line","x1":14,"y1":14,"x2":14,"y2":48},{"t":"line","x1":86,"y1":14,"x2":86,"y2":48},{"t":"line","x1":14,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":53,"y2":48},{"t":"line","x1":75,"y1":48,"x2":86,"y2":48},{"t":"line","x1":52,"y1":48,"x2":52,"y2":34},{"t":"line","x1":52,"y1":34,"x2":59.4,"y2":34},{"t":"line","x1":68.6,"y1":34,"x2":76,"y2":34},{"t":"line","x1":76,"y1":34,"x2":76,"y2":48},{"t":"battery","x":26,"y":14,"cells":2,"label":"电源 3 V"},{"t":"switch","x":50,"y":14,"closed":true,"label":"S"},{"t":"rheostat","x":72,"y":14,"label":"R滑"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表"},{"t":"resistor","x":64,"y":48,"label":"R"},{"t":"meter","x":64,"y":34,"kind":"V","label":"电压表"},{"t":"junction","x":52,"y":48},{"t":"junction","x":76,"y":48},{"t":"text","x":50,"y":58,"text":"电流表串联测电流，电压表并联测电压","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"两只表都不能直接接在电源两极上单独成路：电流表内阻极小，直接接电源相当于短路；电压表虽然内阻很大，但单独接在电源上也测不出有用的量。"},{"type":"h","text":"连接电路的规范：开关断开、滑片调到最大"},{"type":"p","text":"连接电路时必须先断开开关，接好检查无误后再闭合；闭合开关前，把滑动变阻器的滑片调到阻值最大的一端。这两条都是为了安全：开关断开时接线不会带电，避免接线过程中短路；滑片在最大阻值处时，电路总电阻最大、电流最小，即使某处接错也不会一下子烧坏电流表或灯泡。滑片调到最大之后，再通过移动滑片逐步减小电阻，把电压调到需要的值。"},{"type":"figure","figure":{"id":"fig-exp-elec-2","title":"连接电路时的规范操作","caption":"开关断开，滑动变阻器的滑片放在阻值最大处","view":"wide","alt":"与伏安法测电阻相同的电路，开关处于断开状态，滑动变阻器的滑片位于阻值最大的一端","prims":[{"t":"line","x1":14,"y1":14,"x2":22,"y2":14},{"t":"line","x1":36,"y1":14,"x2":44,"y2":14},{"t":"line","x1":56,"y1":14,"x2":60,"y2":14},{"t":"line","x1":84,"y1":14,"x2":86,"y2":14},{"t":"line","x1":14,"y1":14,"x2":14,"y2":48},{"t":"line","x1":86,"y1":14,"x2":86,"y2":48},{"t":"line","x1":14,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":53,"y2":48},{"t":"line","x1":75,"y1":48,"x2":86,"y2":48},{"t":"line","x1":52,"y1":48,"x2":52,"y2":34},{"t":"line","x1":52,"y1":34,"x2":59.4,"y2":34},{"t":"line","x1":68.6,"y1":34,"x2":76,"y2":34},{"t":"line","x1":76,"y1":34,"x2":76,"y2":48},{"t":"battery","x":26,"y":14,"cells":2,"label":"电源 3 V"},{"t":"switch","x":50,"y":14,"closed":false,"label":"S"},{"t":"rheostat","x":72,"y":14,"label":"R滑"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表"},{"t":"resistor","x":64,"y":48,"label":"R"},{"t":"meter","x":64,"y":34,"kind":"V","label":"电压表"},{"t":"junction","x":52,"y":48},{"t":"junction","x":76,"y":48},{"t":"text","x":50,"y":58,"text":"开关断开接线，滑片先调到阻值最大处","size":3.6,"tone":"danger"}]}},{"type":"note","title":"","text":"滑动变阻器一律「一上一下」接入两个接线柱；若接成「两上」或「两下」，移动滑片时接入的电阻不变，就无法调节电压，这属于常见接线错误。"},{"type":"h","text":"两表的接法、量程与读数"},{"type":"p","text":"电流表要串联在被测的那条支路上，电流从正接线柱流入、从负接线柱流出；电压表要并联在被测元件的两端。量程选择的原则是先用大量程试触，指针偏转太小时再换小量程：电源只有 3 V、待测电阻约 10 Ω，电流一般不超过 0.3 A，所以电流表选 0～0.6 A 量程（分度值 0.02 A），电压表选 0～3 V 量程。读数时视线正对表盘，示数要带单位。"},{"type":"figure","figure":{"id":"fig-exp-elec-meter-1","title":"电流表的读数","caption":"量程 0～0.6 A，分度值 0.02 A，指针所指的示数是 0.2 A","view":"wide","alt":"电流表的表盘上指针偏转到满刻度的三分之一处，刻度从 0 到 0.6 安培","prims":[{"t":"rect","x":26,"y":10,"w":48,"h":32,"rx":3,"tone":"main"},{"t":"arc","cx":50,"cy":36,"r":18,"from":30,"to":150},{"t":"line","x1":65.6,"y1":27,"x2":63,"y2":28.5},{"t":"line","x1":59,"y1":20.4,"x2":57.5,"y2":23},{"t":"line","x1":50,"y1":18,"x2":50,"y2":21},{"t":"line","x1":41,"y1":20.4,"x2":42.5,"y2":23},{"t":"line","x1":34.4,"y1":27,"x2":37,"y2":28.5},{"t":"line","x1":50,"y1":36,"x2":44.5,"y2":21,"tone":"danger","width":0.7},{"t":"text","x":33,"y":31,"text":"0","size":3.2},{"t":"text","x":67,"y":31,"text":"0.6","size":3.2},{"t":"text","x":43,"y":16,"text":"0.2","size":3.2,"tone":"accent"},{"t":"text","x":50,"y":7,"text":"电流表","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":48,"text":"量程 0～0.6 A，分度值 0.02 A","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"电流从正接线柱流入，读数时视线正对表盘","size":3.4,"tone":"accent"}]}},{"type":"note","title":"","text":"若指针反向偏转，说明正负接线柱接反了，必须断电改正；若指针一下子打到满刻度右侧，说明量程选小了，要换用更大的量程。"},{"type":"h","text":"定值电阻的数据处理：多次测量取平均值"},{"type":"p","text":"调节滑动变阻器的滑片，使电压表的示数分别为 1.0 V、2.0 V、2.4 V，记下每次对应的电流，再分别算出 U 与 I 的比值，可以发现三次算出的电阻都接近 10 Ω。对定值电阻来说，多次测量取平均值可以减小偶然误差，最后的结果记作 10.0 Ω。表格要写清表头与单位，如「电压 U/V」「电流 I/A」「电阻 R/Ω」。"},{"type":"figure","figure":{"id":"fig-exp-elec-6","title":"伏安法测电阻的数据表","caption":"三次算出的电阻都接近 10 Ω，取平均值为 10.0 Ω","view":"wide","alt":"三行数据表：电压 1.0 伏电流 0.10 安电阻 10.0 欧；电压 2.0 伏电流 0.20 安电阻 10.0 欧；电压 2.4 伏电流 0.24 安电阻 10.0 欧","prims":[{"t":"rect","x":6,"y":12,"w":88,"h":32,"tone":"main"},{"t":"line","x1":6,"y1":20,"x2":94,"y2":20},{"t":"line","x1":6,"y1":28,"x2":94,"y2":28},{"t":"line","x1":6,"y1":36,"x2":94,"y2":36},{"t":"line","x1":28,"y1":12,"x2":28,"y2":44},{"t":"line","x1":50,"y1":12,"x2":50,"y2":44},{"t":"line","x1":72,"y1":12,"x2":72,"y2":44},{"t":"text","x":17,"y":16,"text":"次数","size":3.4},{"t":"text","x":39,"y":16,"text":"电压 U/V","size":3.4},{"t":"text","x":61,"y":16,"text":"电流 I/A","size":3.4},{"t":"text","x":83,"y":16,"text":"电阻 R/Ω","size":3.4},{"t":"text","x":17,"y":24,"text":"1","size":3.4},{"t":"text","x":39,"y":24,"text":"1.0","size":3.4},{"t":"text","x":61,"y":24,"text":"0.10","size":3.4},{"t":"text","x":83,"y":24,"text":"10.0","size":3.4},{"t":"text","x":17,"y":32,"text":"2","size":3.4},{"t":"text","x":39,"y":32,"text":"2.0","size":3.4},{"t":"text","x":61,"y":32,"text":"0.20","size":3.4},{"t":"text","x":83,"y":32,"text":"10.0","size":3.4},{"t":"text","x":17,"y":40,"text":"3","size":3.4},{"t":"text","x":39,"y":40,"text":"2.4","size":3.4},{"t":"text","x":61,"y":40,"text":"0.24","size":3.4},{"t":"text","x":83,"y":40,"text":"10.0","size":3.4},{"t":"text","x":50,"y":52,"text":"R = U/I：三次都是 10.0 Ω，取平均值减小偶然误差","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":59,"text":"在同一段导体、同一时刻取 U 与 I，不能混搭不同次的示数","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"表格里必须写清物理量与单位。若把电压 2.4 V 与电流 0.10 A 配在一起算，就会得出 24 Ω 的错误结果，这是「同一性、同时性」最典型的失分。"},{"type":"h","text":"测量小灯泡的电功率：额定电压下的读数"},{"type":"p","text":"把待测电阻换成额定电压为 2.5 V 的小灯泡，电路接法不变。移动滑动变阻器的滑片，使电压表的示数正好等于 2.5 V（额定电压），这时读出电流表的示数为 0.2 A，小灯泡的额定功率 P = UI = 2.5 V × 0.2 A = 0.5 W。为了让实验结果更有说服力，还要分别测量电压略低于、略高于额定电压时的功率，观察小灯泡的发光情况：实际电压越大，灯泡越亮，实际功率越大。"},{"type":"figure","figure":{"id":"fig-exp-elec-3","title":"测量小灯泡的电功率","caption":"电压表并联在灯泡两端，移动滑片使电压表示数为 2.5 V","view":"wide","alt":"电源、开关、滑动变阻器、电流表和小灯泡依次串联，电压表并联在小灯泡两端，表示在测量灯泡的电压","prims":[{"t":"line","x1":14,"y1":14,"x2":22,"y2":14},{"t":"line","x1":36,"y1":14,"x2":44,"y2":14},{"t":"line","x1":56,"y1":14,"x2":60,"y2":14},{"t":"line","x1":84,"y1":14,"x2":86,"y2":14},{"t":"line","x1":14,"y1":14,"x2":14,"y2":48},{"t":"line","x1":86,"y1":14,"x2":86,"y2":48},{"t":"line","x1":14,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":55.4,"y2":48},{"t":"line","x1":72.6,"y1":48,"x2":86,"y2":48},{"t":"line","x1":52,"y1":48,"x2":52,"y2":34},{"t":"line","x1":52,"y1":34,"x2":59.4,"y2":34},{"t":"line","x1":68.6,"y1":34,"x2":76,"y2":34},{"t":"line","x1":76,"y1":34,"x2":76,"y2":48},{"t":"battery","x":26,"y":14,"cells":2,"label":"电源 3 V"},{"t":"switch","x":50,"y":14,"closed":true,"label":"S"},{"t":"rheostat","x":72,"y":14,"label":"R滑"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表"},{"t":"bulb","x":64,"y":48,"label":"L 2.5 V"},{"t":"meter","x":64,"y":34,"kind":"V","label":"电压表"},{"t":"junction","x":52,"y":48},{"t":"junction","x":76,"y":48},{"t":"text","x":50,"y":58,"text":"P = UI：电压调到 2.5 V 时读出电流，算出额定功率","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"灯泡的电阻会随温度变化：不同电压下算出的电阻并不相同，所以不能对灯泡的电阻取平均值，也不能把不同电压下的功率平均当作额定功率。"},{"type":"h","text":"故障判断：断路与短路的示数特征"},{"type":"p","text":"闭合开关后如果小灯泡不亮，可以按电表的示数判断故障。若电流表几乎没有示数、电压表的示数接近电源电压（3 V），说明电路是断开的，而且断点在电压表并联的那部分（灯泡灯丝断了或灯座接触不良）——因为电压表内阻很大，它和其余元件串联后，电源电压几乎全落在它的两端。若电压表示数为零、电流表却有示数（甚至比正常时大），说明灯泡被短路了，电流绕过了灯泡。"},{"type":"figure","figure":{"id":"fig-exp-elec-5","title":"灯泡断路时的电表示数","caption":"灯不亮、电流表几乎无示数、电压表示数接近电源电压，说明灯泡断路","view":"wide","alt":"小灯泡处灯丝断开，与灯泡并联的电压表示数接近电源电压，串联的电流表几乎没有示数","prims":[{"t":"line","x1":14,"y1":14,"x2":22,"y2":14},{"t":"line","x1":36,"y1":14,"x2":44,"y2":14},{"t":"line","x1":56,"y1":14,"x2":60,"y2":14},{"t":"line","x1":84,"y1":14,"x2":86,"y2":14},{"t":"line","x1":14,"y1":14,"x2":14,"y2":48},{"t":"line","x1":86,"y1":14,"x2":86,"y2":48},{"t":"line","x1":14,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":55.4,"y2":48},{"t":"line","x1":72.6,"y1":48,"x2":86,"y2":48},{"t":"line","x1":52,"y1":48,"x2":52,"y2":34},{"t":"line","x1":52,"y1":34,"x2":59.4,"y2":34},{"t":"line","x1":68.6,"y1":34,"x2":76,"y2":34},{"t":"line","x1":76,"y1":34,"x2":76,"y2":48},{"t":"battery","x":26,"y":14,"cells":2,"label":"电源 3 V"},{"t":"switch","x":50,"y":14,"closed":true,"label":"S"},{"t":"rheostat","x":72,"y":14,"label":"R滑"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表几乎无示数"},{"t":"bulb","x":64,"y":48,"label":"L"},{"t":"circle","cx":64,"cy":48,"r":8,"dashed":true,"tone":"danger"},{"t":"meter","x":64,"y":34,"kind":"V","label":"示数接近 3 V"},{"t":"junction","x":52,"y":48},{"t":"junction","x":76,"y":48},{"t":"text","x":50,"y":60,"text":"灯泡断路：电流表无示数，电压表示数接近电源电压","size":3.4,"tone":"danger"}]}},{"type":"note","title":"","text":"两种故障的口诀：哪里断路，电压表就往哪里「靠」到电源电压；哪里短路，电压表就没有示数，而电流反而变大。判断时先说清哪个表有示数、哪个没有。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["伏安法测电阻","R = (U)/(I)","U：V；I：A；R：Ω（1 Ω = 1 V/A） · U 与 I 必须取自同一段导体、同一时刻（同一性与同时性），不能把不同次测量的电压和电流混搭代入。对定值电阻可以多次测量取平均值；对小灯泡不行，因为灯丝电阻随温度升高而变大，各电压下算出的电阻本来就不同，只能逐次记录。"],["电功率","P = UI","U：V；I：A；P：W · 求额定功率必须用额定电压与此时对应的电流（如 2.5 V 与 0.2 A 对应 0.5 W）；求实际功率则用实际电压与对应的实际电流。同一个灯泡在不同电压下的功率不同，不能把几次测得的功率平均当作额定功率。"],["滑动变阻器接入的电阻（串联分压）","R_(滑) = U_(电源) - U_(灯)I","各电压单位 V，电流单位 A，电阻单位 Ω · 只适用于滑动变阻器与被测元件串联的电路：电源电压等于各部分电压之和，滑变阻器分到的电压是电源电压减去元件电压，再用串联电路中电流处处相等的特点求电阻。若电路是并联，或者滑变阻器接成了「两下」接线柱（此时它相当于定值电阻），这个式子的含义就要重新分析。"]]},{"type":"h","text":"应用 · 实验应用：由 I-U 图像比较定值电阻与小灯泡"},{"type":"note","title":"情境","text":"同一个实验装置分别测一个定值电阻和一个小灯泡，把每次的电压与电流描在同一张 I-U 图像上。"},{"type":"note","title":"模型与思路","text":"定值电阻的阻值不随电压变化，它的 I-U 图像是一条过原点的直线，直线的斜率反映的是 1/R（电压相同时电流越大电阻越小）；小灯泡的灯丝电阻随温度升高而变大，图像不是直线。"},{"type":"list","title":"解答步骤","items":["定值电阻：电压 1.0 V 时电流 0.10 A、2.0 V 时 0.20 A、2.4 V 时 0.24 A，比值都是 10 Ω，描点后在一条过原点的直线上。","小灯泡：电压升高时灯丝温度升高、电阻变大，电流增长得比电压慢，描出的点连起来是一条向下弯曲的曲线。","比较结论：由 R = U/I 求电阻时，定值电阻可以取平均值；小灯泡只能在每个电压下各算一个电阻，不能平均。"]},{"type":"figure","figure":{"id":"fig-exp-elec-4","title":"定值电阻与小灯泡的 I-U 图像","caption":"定值电阻的图像是过原点的直线，小灯泡的图像向下弯曲","view":"square","alt":"以电压为横轴、电流为纵轴的坐标图，一条过原点的直线表示定值电阻，一条向下弯曲的曲线表示小灯泡","prims":[{"t":"axis","x":20,"y":84,"w":72,"h":64,"xLabel":"U/V","yLabel":"I/A","origin":true,"grid":true,"xTicks":[{"at":0.33,"label":"1.0"},{"at":0.67,"label":"2.0"},{"at":1,"label":"3.0"}],"yTicks":[{"at":0.33,"label":"0.1"},{"at":0.67,"label":"0.2"},{"at":1,"label":"0.3"}]},{"t":"curve","points":[[20,84],[92,20]],"tone":"accent"},{"t":"curve","points":[[20,84],[44,64],[68,48],[92,36]],"tone":"danger","dashed":true},{"t":"text","x":62,"y":30,"text":"定值电阻","size":3.4,"tone":"accent"},{"t":"text","x":66,"y":52,"text":"小灯泡","size":3.4,"tone":"danger"},{"t":"text","x":56,"y":92,"text":"取某点的 U 与 I 相除即得该状态的电阻","size":3.4,"tone":"muted"}]}},{"type":"note","title":"结论","text":"遇到「由图像求电阻」的题目，要取图像上某个点的电压与电流相除，而不是用整条直线的想法去估；图像弯曲说明电阻在变，此时求出的电阻只对应那个电压下的状态。"},{"type":"h","text":"应用 · 生活应用：为什么灯泡往往在开灯瞬间烧坏"},{"type":"note","title":"情境","text":"家里的白炽灯用久了常常在刚开灯的一瞬间烧断灯丝，正常发光以后反而不容易坏。"},{"type":"note","title":"模型与思路","text":"灯丝的电阻随温度升高而变大：刚通电时灯丝温度低、电阻小，由 I = U/R 可知电流比正常发光时大得多，灯丝局部过热就容易烧断。"},{"type":"list","title":"解答步骤","items":["冷态时灯丝温度低，电阻比正常发光时小得多。","接通 220 V 电压的瞬间，电阻小则电流大，灯丝发热剧烈。","灯丝温度升高后电阻变大，电流回落到额定值，进入正常发光状态。"]},{"type":"note","title":"结论","text":"用「灯丝电阻随温度升高而变大」可以解释这个现象，也说明为什么小灯泡的电阻不能在不同电压下取平均值。"},{"type":"h","text":"应用 · 实验应用：滑动变阻器在电路中的双重作用"},{"type":"note","title":"情境","text":"在测小灯泡额定功率的实验中，闭合开关时灯泡很暗，移动滑片后灯泡逐渐变亮，最终电压表示数达到 2.5 V。"},{"type":"note","title":"模型与思路","text":"滑动变阻器与灯泡串联，起两个作用：一是保护电路（开始接入最大电阻，限制电流）；二是通过改变接入的电阻改变电路中的电流，从而改变灯泡两端的电压，实现多次测量。"},{"type":"list","title":"解答步骤","items":["闭合开关前把滑片调到阻值最大处，电路总电阻最大、电流最小，灯泡很暗，电流表不会被打坏。","移动滑片使接入电路的电阻变小，总电阻变小、电流变大，灯泡两端电压随之升高。","当电压表示数正好为 2.5 V 时停止移动，读出此时电流表的示数，用 P = UI 计算额定功率。","滑动变阻器接入的电阻可由串联分压求：R滑 = (U电源 − U灯)/I。"]},{"type":"note","title":"结论","text":"滑动变阻器既能保护电路，又能连续调节电压；缺少它就只能在一个电压下测一次，无法比较不同电压下的功率。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["小灯泡的电阻是固定不变的，几次测得的电阻取平均值更准确","灯丝电阻随温度升高而变大，不同电压下测出的电阻不同，不能取平均值","电压升高时灯丝温度升高，灯丝的电阻随之变大，所以测出的电阻一次比一次大。把它们平均，得到的是一个在任何电压下都不成立的数。定值电阻才可以取平均值。"],["电流表并联在被测电阻两端，电压表串联在电路中，这样读数更方便","电流表必须串联在被测支路上，电压表必须并联在被测元件两端","电流表内阻极小，并联在电阻两端相当于把那部分电路短路，电流会大量流过电流表，容易烧坏表；电压表内阻很大，串联在电路里会让电流几乎为零，用电器都不工作。"],["闭合开关后灯不亮、电流表无示数，一定是灯泡短路了","电流表无示数、电压表示数接近电源电压，说明是灯泡断路；灯泡短路时电压表示数为零而电流表有示数","断路时电路没有电流，电压表与其余元件串联，电源电压几乎全部落在内阻很大的电压表上，所以它的示数接近电源电压；短路时电流绕过灯泡，灯泡两端电压为零、总电阻变小、电流反而变大。"],["连接电路时开关闭合着也没关系，只要动作快一点","连接电路时必须断开开关，并先把滑动变阻器的滑片调到阻值最大处","带电接线容易在接错时造成短路，烧坏电流表或电源；滑片在最大阻值处可以让电流最小，即使接错也有一次缓冲的机会。接好并检查无误后再闭合开关。"]]},{"type":"table","title":"电流表与电压表（两只表的接法与使用区别）","head":["比较项","电流表","电压表"],"rows":[["接法","串联在被测支路中","并联在被测元件两端"],["内阻特征","很小，接近一条导线","很大，几乎不通电流"],["量程选择","本实验选 0～0.6 A","本实验选 0～3 V"],["接反的现象","指针反偏，可能损坏表","指针反偏，可能损坏表"]]},{"type":"table","title":"伏安法测电阻与测量小灯泡的电功率（同一套电路的两种实验目的）","head":["比较项","测定值电阻的阻值","测小灯泡的额定功率"],"rows":[["测量目的","由 R = U/I 求电阻","由 P = UI 求功率"],["多次测量","可以取平均值减小偶然误差","不能平均，要逐次记录并比较发光情况"],["电压的选取","任意取几个不同的电压值","必须包含额定电压，并测略高、略低的情形"],["图像","I-U 图像是一条过原点的直线","I-U 图像是一条向下弯曲的曲线"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["电路连接与作图","要求补全电路、连接实物图或画电路图，考查电流表串联、电压表并联、滑动变阻器「一上一下」的接法，以及开关断开、滑片置最大等操作要求。评分通常按「元件位置是否正确、导线是否连到接线柱、有没有多余的线」逐项给分。"],["故障判断","给出闭合开关后的现象（灯不亮、两表示数如何），要求判断故障类型与位置。答题要用「断路时电压表靠近电源电压、短路时电压表示数为零而电流变大」这两条特征，并指出故障发生在哪个元件上。"],["数据表格与图像处理","给出电压、电流的数据，要求算电阻或功率、画 I-U 图像、由图像比较不同元件。评分关键是有没有写清单位、有没有正确取平均值（定值电阻可以、灯泡不可以）、由图像取点算电阻的过程是否完整。"],["滑动变阻器的作用","反复出现的问法是「滑动变阻器在本实验中起什么作用」，标准答案是两条：保护电路（开始接入最大电阻）与改变电压以实现多次测量。只答一条通常只能得一半的分。"]]},{"type":"quote","text":"【材料一】某小组用伏安法测量一个定值电阻的阻值。电源电压为 3 V，电压表并联在待测电阻两端，电流表串联在电路中，滑动变阻器的规格是 20 Ω 1 A。移动滑片，得到三组数据：电压 1.0 V 时电流 0.10 A；电压 2.0 V 时电流 0.20 A；电压 2.4 V 时电流 0.24 A。\n【材料二】接着他们把定值电阻换成额定电压为 2.5 V 的小灯泡，重新调节滑片，使电压表的示数正好为 2.5 V，此时电流表的示数为 0.2 A。开始实验时，他们先把滑动变阻器的滑片调到了阻值最大处。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据材料一的三组数据，求这个定值电阻的阻值（写出每次的计算结果与最后取值）。（4 分）","【设问】根据材料二，求小灯泡的额定功率；如果换用电压 2.0 V 再测一次，测得的功率还是额定功率吗？（3 分）","【设问】实验开始时把滑动变阻器的滑片调到阻值最大处，这样做有什么作用？请写出两条。（3 分）"]}],"questions":[{"id":"phy-experiment-6-q1","type":"choice","stem":"如图是伏安法测电阻的电路。关于两只电流表和电压表的连接，下列说法正确的是","answer":"C","explain":"C 正确：电压表并联在被测电阻两端测电压，电流表串联在被测支路中测电流，这样由 R = U/I 才能算出电阻。A 错：电流表内阻极小，并联在电阻两端相当于把电阻短路，还会烧坏电流表。B 错：电压表内阻很大，串联在电路中电流几乎为零，电阻不工作。D 错：两只表的内阻差别极大，接法互换会改变电路的工作状态，测出的结果毫无意义。","options":["电流表并联在待测电阻两端，用来测电阻两端的电压","电压表串联在电路中，用来测通过电阻的电流","电压表并联在待测电阻两端测电压，电流表串联在电路中测电流","两只表的位置可以互换，对测量结果没有影响"],"difficulty":2,"tags":["电路连接","电表使用"],"figure":{"id":"fig-exp-elec-q1","title":"伏安法测电阻的电路","caption":"电压表并联在待测电阻两端，电流表串联在电路中","view":"wide","alt":"电源、开关、滑动变阻器、电流表和待测电阻串联成回路，电压表并联在待测电阻两端","prims":[{"t":"line","x1":14,"y1":14,"x2":22,"y2":14},{"t":"line","x1":36,"y1":14,"x2":44,"y2":14},{"t":"line","x1":56,"y1":14,"x2":60,"y2":14},{"t":"line","x1":84,"y1":14,"x2":86,"y2":14},{"t":"line","x1":14,"y1":14,"x2":14,"y2":48},{"t":"line","x1":86,"y1":14,"x2":86,"y2":48},{"t":"line","x1":14,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":53,"y2":48},{"t":"line","x1":75,"y1":48,"x2":86,"y2":48},{"t":"line","x1":52,"y1":48,"x2":52,"y2":34},{"t":"line","x1":52,"y1":34,"x2":59.4,"y2":34},{"t":"line","x1":68.6,"y1":34,"x2":76,"y2":34},{"t":"line","x1":76,"y1":34,"x2":76,"y2":48},{"t":"battery","x":26,"y":14,"cells":2,"label":"电源"},{"t":"switch","x":50,"y":14,"closed":true,"label":"S"},{"t":"rheostat","x":72,"y":14,"label":"R滑"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表"},{"t":"resistor","x":64,"y":48,"label":"R"},{"t":"meter","x":64,"y":34,"kind":"V","label":"电压表"},{"t":"junction","x":52,"y":48},{"t":"junction","x":76,"y":48}]}},{"id":"phy-experiment-6-q2","type":"choice","stem":"关于连接电路的操作要求，下列说法正确的是","answer":"A","explain":"A 正确：断开开关接线可以避免带电操作引起短路，滑片在最大阻值处可以让电流最小，起保护作用。B 错：闭合开关接线，一旦接错就会立刻形成短路，可能烧坏电表或电源。C 错：滑动变阻器既要保护电路，又要改变电压；接成「两上」或「两下」时移动滑片电阻不变，起不到调节作用。D 错：电流表内阻极小，直接接电源两极就是短路，会烧坏电流表和电源。","options":["连接电路时开关要断开，滑动变阻器的滑片要调到阻值最大处","连接电路时要闭合开关，这样才能随时看出有没有接错","滑动变阻器只起改变电压的作用，怎么接都可以","为了省时间，可以把电流表直接接到电源的两极上测电流"],"difficulty":1,"tags":["操作规范","滑动变阻器"]},{"id":"phy-experiment-6-q3","type":"choice","stem":"闭合开关后，小灯泡不亮，电流表的示数几乎为零，电压表的示数接近 3 V（电源电压）。电路的故障可能是","answer":"B","explain":"B 正确：电流表无示数说明电路某处断开；电压表示数接近电源电压，说明断点就在电压表并联的这段电路上，也就是灯泡处。A 错：灯泡被短路时电流绕开灯泡，电压表示数为零而电流表有示数。C 错：滑动变阻器被短路只会使总电阻变小、电流变大，灯反而更亮。D 错：若电流表断路，整个串联回路断开，电压表与电源之间也断开了，它的示数会是零而不是 3 V。","options":["小灯泡被短路了","小灯泡断路了（灯丝断了或灯座接触不良）","滑动变阻器被短路了","电流表断路，但电压表仍然正常"],"difficulty":3,"tags":["故障判断","断路"]},{"id":"phy-experiment-6-q4","type":"choice","stem":"关于伏安法测电阻与测小灯泡电功率的数据处理，下列说法正确的是","answer":"D","explain":"D 正确：定值电阻的阻值不随电压变化，电流与电压成正比，图像是过原点的直线；小灯泡的灯丝温度随电压升高而升高，电阻变大，图像向下弯曲。A 错：灯丝电阻随温度变化，各电压下的电阻不同，取平均值没有意义。B 错：定值电阻的图像是直线而不是曲线。C 错：小灯泡的图像是曲线，只有在电压变化很小的范围内才近似看作直线。","options":["小灯泡在不同电压下测得的电阻应当取平均值","定值电阻的 I-U 图像是一条曲线","小灯泡的 I-U 图像是一条过原点的直线","定值电阻的 I-U 图像是一条过原点的直线，小灯泡的电阻随温度升高而变大"],"difficulty":2,"tags":["图像分析","数据处理"],"figure":{"id":"fig-exp-6-ui-compare","title":"定值电阻与小灯泡的 U-I 图像","caption":"定值电阻的阻值不随电压变化，图像是过原点的直线；灯丝电阻随温度升高而变大，图像向电压轴方向弯曲","view":"wide","alt":"两幅 U-I 图像并排：左边定值电阻的图像是一条过原点的直线，右边小灯泡的图像是一条向右上方弯曲的曲线","prims":[{"t":"axis","x":12,"y":52,"w":34,"h":32,"xLabel":"I","yLabel":"U","origin":true,"grid":true},{"t":"curve","points":[[12,52],[46,20]],"tone":"accent","width":1},{"t":"text","x":28,"y":60,"text":"定值电阻：直线","size":3.4,"tone":"accent","anchor":"middle"},{"t":"text","x":28,"y":66,"text":"阻值不变，可求平均值","size":3.2,"tone":"muted","anchor":"middle"},{"t":"axis","x":58,"y":52,"w":34,"h":32,"xLabel":"I","yLabel":"U","origin":true,"grid":true},{"t":"curve","points":[[58,52],[66,44],[74,34],[82,26],[90,22]],"tone":"danger","width":1},{"t":"text","x":74,"y":60,"text":"小灯泡：曲线","size":3.4,"tone":"danger","anchor":"middle"},{"t":"text","x":74,"y":66,"text":"灯丝电阻随温度变大","size":3.2,"tone":"muted","anchor":"middle"},{"t":"text","x":50,"y":12,"text":"两组数据不能混算：小灯泡的电阻要逐次分别说明","size":3.6,"tone":"main","anchor":"middle"}]}},{"id":"phy-experiment-6-q5","type":"fill","stem":"用伏安法测量一个定值电阻，三次测得的阻值分别为 9.8 Ω、10.0 Ω、10.2 Ω，这个定值电阻的阻值应记为 ______ Ω。","answer":"10.0|10","explain":"为什么这样记：定值电阻的阻值不随电压变化，三次测量的差别来自读数等偶然误差，取平均值可以减小误差：(9.8 Ω + 10.0 Ω + 10.2 Ω) ÷ 3 = 10.0 Ω。注意两点：一是只有同一段导体、同一类条件下的重复测量才能平均；二是如果是小灯泡，因为灯丝电阻随温度升高而变大，三次结果会依次变大，此时不能取平均值。","difficulty":1,"tags":["平均值","数据处理"]},{"id":"phy-experiment-6-q6","type":"fill","stem":"如图是电流表的表盘，实验中选用 0～0.6 A 的量程。此时电流表的示数是 ______ A。","answer":"0.2|0.2 A|0.2A","explain":"为什么这样读：先看量程 0～0.6 A，再数分度值——把 0.6 A 平均分成 30 小格，每一小格是 0.02 A。指针偏到满刻度的三分之一处，也就是 0.2 A 所在的位置，所以读数是 0.2 A。读数时视线要正对表盘，并注意把量程读对：同一根指针在 0～3 A 量程下的示数是它的 5 倍，读错量程是电学读数最常见的错误。","difficulty":2,"tags":["电流表","读数"],"figure":{"id":"fig-exp-elec-q6","title":"电流表的示数","caption":"量程 0～0.6 A，分度值 0.02 A","view":"wide","alt":"电流表表盘上指针偏转到满刻度的三分之一处，刻度范围从 0 到 0.6 安培","prims":[{"t":"rect","x":26,"y":10,"w":48,"h":32,"rx":3,"tone":"main"},{"t":"arc","cx":50,"cy":36,"r":18,"from":30,"to":150},{"t":"line","x1":65.6,"y1":27,"x2":63,"y2":28.5},{"t":"line","x1":59,"y1":20.4,"x2":57.5,"y2":23},{"t":"line","x1":50,"y1":18,"x2":50,"y2":21},{"t":"line","x1":41,"y1":20.4,"x2":42.5,"y2":23},{"t":"line","x1":34.4,"y1":27,"x2":37,"y2":28.5},{"t":"line","x1":50,"y1":36,"x2":44.5,"y2":21,"tone":"danger","width":0.7},{"t":"text","x":33,"y":31,"text":"0","size":3.2},{"t":"text","x":67,"y":31,"text":"0.6","size":3.2},{"t":"text","x":50,"y":7,"text":"电流表","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":48,"text":"0～0.6 A 量程，分度值 0.02 A","size":3.4,"tone":"muted"}]}},{"id":"phy-experiment-6-q7","type":"short","stem":"用伏安法测量一个定值电阻（阻值约 10 Ω），电源电压为 3 V 且保持不变，滑动变阻器的规格是 20 Ω 1 A。(1) 当电压表的示数为 2.0 V 时，电流表的示数为 0.2 A，求定值电阻的阻值；(2) 此时滑动变阻器接入电路的电阻是多少？","answer":"(1) R = U/I = 2.0 V ÷ 0.2 A = 10 Ω。(2) 定值电阻与滑动变阻器串联，电源电压等于两部分电压之和，所以滑动变阻器分到的电压 U滑 = 3 V − 2.0 V = 1.0 V；串联电路中电流处处相等，通过它的电流也是 0.2 A，则 R滑 = U滑/I = 1.0 V ÷ 0.2 A = 5 Ω。","explain":"为什么这样做：第 (1) 问直接用同一时刻的电压与电流相除，取同一性、同时性；第 (2) 问要用串联电路的两个规律——电压关系 U = U₁ + U₂ 和电流处处相等。先用电源电压减去定值电阻的电压得到滑动变阻器的电压，再用同一电流求电阻。若要检验，可以算总电阻 10 Ω + 5 Ω = 15 Ω，3 V ÷ 15 Ω = 0.2 A，与题给电流一致。","difficulty":2,"tags":["伏安法","计算"],"rubric":["写出 R = U/I 并用同一组数据算出 10 Ω（1 分）","利用串联电压关系求出滑动变阻器的电压 1.0 V（1 分）","说明串联电流相等并用同一电流计算（1 分）","算出 5 Ω 并带单位（1 分）"],"steps":["写出欧姆定律的变形 R = U/I。","代入同一时刻的示数：R = 2.0 V ÷ 0.2 A = 10 Ω。","由串联电路电压关系求滑动变阻器的电压：U滑 = 3 V − 2.0 V = 1.0 V。","由串联电路电流处处相等，用同一个电流求电阻：R滑 = 1.0 V ÷ 0.2 A = 5 Ω。","答：定值电阻为 10 Ω，滑动变阻器接入 5 Ω。"]},{"id":"phy-experiment-6-q8","type":"short","stem":"在测量小灯泡额定功率的实验中：(1) 滑动变阻器起什么作用？(2) 为什么至少要测三次（低于额定电压、额定电压、略高于额定电压）？(3) 为什么不能把三次测得的功率取平均值作为额定功率？","answer":"(1) 两个作用：一是保护电路，闭合开关前把滑片调到阻值最大处，使电路中的电流最小；二是通过改变接入电路的电阻来改变小灯泡两端的电压和电流，从而测量不同电压下的功率。(2) 分别测量略低于、等于、略高于额定电压时的功率，可以看出实际功率随实际电压的变化，比较灯泡的亮度，找出额定电压下的额定功率。(3) 额定功率只对应额定电压 2.5 V 这一个状态，其他电压下测得的都是实际功率，大小各不相同；把它们平均并不能得到额定功率，也没有物理意义。","explain":"为什么这样答：额定功率是铭牌上标定的值，只在额定电压下才有意义，所以实验的关键动作是「把电压调到 2.5 V 再读数」。滑动变阻器的两个作用要分开写，只写「保护电路」会漏掉「改变电压、多次测量」这一半。判断灯泡亮度时要说清依据：灯泡的亮度由实际功率决定，实际功率越大越亮，与额定功率的大小无关。","difficulty":2,"tags":["实验说理","额定功率"],"rubric":["答出滑动变阻器的两个作用：保护电路、改变电压实现多次测量（1 分）","说明必须在额定电压下测得额定功率（1 分）","说明三次测量的目的：比较不同电压下的实际功率与发光情况（1 分）","说明不同电压下的功率不能取平均值及其原因（1 分）"]},{"id":"phy-experiment-6-q9","type":"short","stem":"请画出测量小灯泡额定功率的实验电路图，要求标出电源、开关、滑动变阻器、电流表、小灯泡和电压表的符号，并说明电压表接在哪里、为什么这样接。","answer":"见参考答案图：电源、开关、滑动变阻器、电流表、小灯泡依次串联成一条回路；电压表并联在小灯泡的两端。电压表并联在灯泡两端，才能直接读出灯泡两端的电压，从而把电压调到额定电压 2.5 V，此时读出电流表的示数，用 P = UI 算出额定功率。","explain":"作图要点：① 导线用直线画、拐角为直角，元件符号画在导线中间并留出引线；② 电流表必须串联在电路中（与被测灯泡串联），电压表必须并联在灯泡两端，两条接线端都要连到灯泡的两侧；③ 滑动变阻器要「一上一下」接入两个接线柱；④ 画完后检查一圈：从电源正极出发，沿导线走一圈能不能回到负极，中间有没有把某个元件漏掉或短路。把电压表画成串联、或者把电流表并在灯泡两端，都是电路作图的典型错误。","difficulty":3,"tags":["作图","电路图"],"rubric":["导线用直线、拐角为直角，元件符号带引线接在导线中","电流表串联在电路中（与灯泡串联），电压表并联在灯泡两端","滑动变阻器「一上一下」接入两个接线柱","从电源正极出发沿导线能走回负极，没有漏接元件或把元件短路","说明栏写清电压表接在灯泡两端及理由（测灯泡两端电压）"],"answerFigure":{"id":"fig-exp-elec-ans1","title":"参考答案：测小灯泡额定功率的电路","caption":"电压表并联在灯泡两端，电流表串联在电路中","view":"wide","alt":"电源、开关、滑动变阻器、电流表与灯泡串联成回路，电压表并联在灯泡两端","prims":[{"t":"line","x1":14,"y1":14,"x2":22,"y2":14},{"t":"line","x1":36,"y1":14,"x2":44,"y2":14},{"t":"line","x1":56,"y1":14,"x2":60,"y2":14},{"t":"line","x1":84,"y1":14,"x2":86,"y2":14},{"t":"line","x1":14,"y1":14,"x2":14,"y2":48},{"t":"line","x1":86,"y1":14,"x2":86,"y2":48},{"t":"line","x1":14,"y1":48,"x2":21.4,"y2":48},{"t":"line","x1":38.6,"y1":48,"x2":55.4,"y2":48},{"t":"line","x1":72.6,"y1":48,"x2":86,"y2":48},{"t":"line","x1":52,"y1":48,"x2":52,"y2":34},{"t":"line","x1":52,"y1":34,"x2":59.4,"y2":34},{"t":"line","x1":68.6,"y1":34,"x2":76,"y2":34},{"t":"line","x1":76,"y1":34,"x2":76,"y2":48},{"t":"battery","x":26,"y":14,"cells":2,"label":"电源"},{"t":"switch","x":50,"y":14,"closed":true,"label":"S"},{"t":"rheostat","x":72,"y":14,"label":"R滑"},{"t":"meter","x":30,"y":48,"kind":"A","label":"电流表"},{"t":"bulb","x":64,"y":48,"label":"L"},{"t":"meter","x":64,"y":34,"kind":"V","label":"电压表"},{"t":"junction","x":52,"y":48},{"t":"junction","x":76,"y":48},{"t":"text","x":50,"y":58,"text":"电压表并联在灯泡两端，测灯泡的电压","size":3.6,"tone":"accent"}]}},{"id":"phy-experiment-6-m1-q1","type":"short","stem":"根据材料一的三组数据，求这个定值电阻的阻值（写出每次的计算结果与最后取值）。（4 分）","answer":"三次分别计算：R₁ = 1.0 V ÷ 0.10 A = 10.0 Ω；R₂ = 2.0 V ÷ 0.20 A = 10.0 Ω；R₃ = 2.4 V ÷ 0.24 A = 10.0 Ω。三次结果相同，说明这是一段定值电阻，最后取平均值 10.0 Ω。","explain":"","tags":["伏安法测电阻","数据处理"],"rubric":["写出公式 R = U/I（1 分）","正确算出三次的电阻都是 10.0 Ω（1 分）","说明定值电阻可以取平均值、结果记为 10.0 Ω（1 分）","每次代入的 U 与 I 都是同一组数据（同一性与同时性）（1 分）"]},{"id":"phy-experiment-6-m1-q2","type":"short","stem":"根据材料二，求小灯泡的额定功率；如果换用电压 2.0 V 再测一次，测得的功率还是额定功率吗？（3 分）","answer":"额定功率 P = UI = 2.5 V × 0.2 A = 0.5 W。换用 2.0 V 再测时，得到的是小灯泡在 2.0 V 下的实际功率，不是额定功率：额定功率只有在额定电压 2.5 V 下测得的才是，其他电压下的功率都属于实际功率，此时灯泡比正常发光时暗。","explain":"","tags":["电功率","额定功率"],"rubric":["写出公式 P = UI（1 分）","算出额定功率 0.5 W 并带单位（1 分）","说明 2.0 V 下测得的是实际功率而不是额定功率（1 分）"]},{"id":"phy-experiment-6-m1-q3","type":"short","stem":"实验开始时把滑动变阻器的滑片调到阻值最大处，这样做有什么作用？请写出两条。（3 分）","answer":"第一条是保护电路：滑片在最大阻值处时电路总电阻最大、电流最小，即使某处接错或灯泡额定电流较小，也不至于把电流表或灯泡烧坏。第二条是便于调节：闭合开关后再逐步减小接入的电阻，可以连续地把电压从较小值调到需要的值（如 2.5 V），从而实现多次测量。","explain":"","tags":["滑动变阻器","操作规范"],"rubric":["答出保护电路、限制电流（1 分）","答出便于通过移动滑片改变电压、实现多次测量（1 分）","指出闭合开关前必须先调到最大阻值处这一操作顺序（1 分）"]}]},{"id":"phy-experiment-7","title":"实验操作考试评分要点与常见失分：评委看什么，哪里最容易扣分","subtitle":"实验操作考试 · 评分与失分 · all","grade":"all","tags":["实验操作考试 · 评分与失分"],"blocks":[{"type":"note","title":"教材位置","text":"实验操作考试 · 评分与失分 · all"},{"type":"note","title":"问题切入","text":"同一个实验，两位同学都做出了正确的结果，为什么分数差了一大截？评委在你动做的几分钟里到底在看什么？哪些失分是「一扣就是一整项」的？考前几分钟应该先做什么？"},{"type":"note","title":"一句话抓住关键","text":"实验操作考试是评委现场按细则观察打分，看的是可观察的行为：器材选得对不对、检查没检查、顺序对不对、读数规不规范、数据有没有记全（含单位）、结论说得准不准、器材有没有整理、有没有安全操作。把每一步都做成「看得见的规范动作」，并养成先想后做的习惯，分数就稳。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"实验操作考试不是笔试，评委看的是你「手上的动作」：器材选得对不对、检查没检查、顺序对不对。","walk":["开场三件事：检查器材、看清量程和分度值、向老师报告。","操作讲顺序：先组装再检查，先调零再测量。","收尾三件事：整理器材、记录数据并带单位、报告结论。"],"try":"在家用天平或量筒完整走一遍「检查—测量—记录—整理」的流程，并给自己计时。","use":["常见扣分：不调零、读数不估读、不写单位、不整理器材。","口述报告模板：「我选用的器材是……，量程……，分度值……」。"]},{"type":"h","text":"评委通常看这六个方面"},{"type":"p","text":"实验操作考试的评分细则一般会把一次实验拆成若干观察点，大致集中在六个方面：器材的选择与检查、操作顺序、读数规范、数据记录与处理、结论表述、整理器材与安全。每个方面都由评委在操作过程中直接观察，所以「心里明白但手上没做出来」拿不到分——规范动作必须做出来给评委看见。"},{"type":"figure","figure":{"id":"fig-exp-score-1","title":"评分通常观察的六个方面","caption":"每一步都要做成看得见的规范动作","view":"wide","alt":"六个方框分别写着器材检查、操作顺序、读数规范、数据记录、结论表述、整理与安全","prims":[{"t":"rect","x":6,"y":10,"w":28,"h":14,"fill":true,"tone":"main","label":"器材检查"},{"t":"rect","x":36,"y":10,"w":28,"h":14,"fill":true,"tone":"main","label":"操作顺序"},{"t":"rect","x":66,"y":10,"w":28,"h":14,"fill":true,"tone":"main","label":"读数规范"},{"t":"rect","x":6,"y":30,"w":28,"h":14,"fill":true,"tone":"accent","label":"数据记录"},{"t":"rect","x":36,"y":30,"w":28,"h":14,"fill":true,"tone":"accent","label":"结论表述"},{"t":"rect","x":66,"y":30,"w":28,"h":14,"fill":true,"tone":"accent","label":"整理与安全"},{"t":"text","x":50,"y":54,"text":"评委现场观察：动作做出来才算完成","size":3.8,"tone":"accent"}]}},{"type":"note","title":"","text":"不同地区、不同年度的评分细则与分值分配可能不同，但观察的方向大体一致；训练时按这六个方面逐项自检，比死记某一份细则更有用。"},{"type":"h","text":"进场第一步：器材选择与检查"},{"type":"p","text":"动手之前先看器材：需要哪些仪器，规格合不合适，仪器是否完好。常用的一句话是「先看量程与分度值，再看指针是否指零」：刻度尺要看零刻度线与分度值；天平要放在水平台上、游码归零、砝码是否齐全；量筒要看量程与分度值、有没有裂纹；弹簧测力计要看指针是否指在零刻度线、量程够不够；电流表、电压表要看量程与指针是否指零、接线柱是否松动。发现器材有问题要举手更换，不要凑合着做。"},{"type":"figure","figure":{"id":"fig-exp-score-2","title":"器材与检查要点","caption":"先看量程与分度值，再看指针是否指零","view":"wide","alt":"左侧列出刻度尺、天平、量筒、弹簧测力计、电流表电压表，右侧对应写出各自要检查的项目","prims":[{"t":"line","x1":6,"y1":15,"x2":94,"y2":15},{"t":"text","x":8,"y":11,"text":"器材","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":11,"text":"要检查什么","anchor":"start","size":3.6,"tone":"muted"},{"t":"text","x":8,"y":22,"text":"刻度尺","anchor":"start","size":3.4},{"t":"text","x":50,"y":22,"text":"零刻度线是否磨损、分度值是多少","anchor":"start","size":3.4},{"t":"text","x":8,"y":31,"text":"托盘天平","anchor":"start","size":3.4},{"t":"text","x":50,"y":31,"text":"放平、游码归零、砝码是否齐全","anchor":"start","size":3.4},{"t":"text","x":8,"y":40,"text":"量筒","anchor":"start","size":3.4},{"t":"text","x":50,"y":40,"text":"量程、分度值、是否漏水或有裂纹","anchor":"start","size":3.4},{"t":"text","x":8,"y":49,"text":"弹簧测力计","anchor":"start","size":3.4},{"t":"text","x":50,"y":49,"text":"指针是否指零、量程是否够用","anchor":"start","size":3.4},{"t":"text","x":8,"y":58,"text":"电流表电压表","anchor":"start","size":3.4},{"t":"text","x":50,"y":58,"text":"量程选择、指针是否指零、接线柱","anchor":"start","size":3.4}]}},{"type":"note","title":"","text":"器材检查不是走过场：天平游码没归零就去称量、测力计指针不在零位就开始测量，后面所有的数据都会带着系统偏差。"},{"type":"h","text":"操作顺序：先检查、再连接或调节、后测量、最后整理"},{"type":"p","text":"每个必做实验都有一条固定的操作顺序，顺序本身就是评分点。电学实验：断开开关 → 按电路图连接（滑动变阻器滑片调到阻值最大处）→ 检查无误 → 闭合开关 → 调节并读数 → 断开开关、整理器材。密度实验：调平天平 → 称质量 → 量筒测体积 → 计算。温度计测量：玻璃泡全部浸入 → 待示数稳定 → 读数（玻璃泡留在液体中）。做题时先把顺序在心里过一遍，再动手。"},{"type":"figure","figure":{"id":"fig-exp-score-3","title":"一次实验的四个环节","caption":"顺序错了往往一整项都拿不到分","view":"wide","alt":"流程图：检查器材、连接或调节、测量读数、整理器材四个环节依次相连","prims":[{"t":"rect","x":4,"y":20,"w":21,"h":14,"fill":true,"tone":"main","label":"检查器材"},{"t":"arrow","x1":26,"y1":27,"x2":30,"y2":27,"tone":"accent"},{"t":"rect","x":31,"y":20,"w":21,"h":14,"fill":true,"tone":"main","label":"连接调节"},{"t":"arrow","x1":53,"y1":27,"x2":57,"y2":27,"tone":"accent"},{"t":"rect","x":58,"y":20,"w":19,"h":14,"fill":true,"tone":"accent","label":"测量读数"},{"t":"arrow","x1":78,"y1":27,"x2":82,"y2":27,"tone":"accent"},{"t":"rect","x":83,"y":20,"w":15,"h":14,"fill":true,"tone":"accent","label":"整理器材"},{"t":"text","x":50,"y":44,"text":"每一步动手之前先在心里说清「我准备怎么做」","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":54,"text":"顺序错乱、漏做整理，通常是整项失分","size":3.6,"tone":"danger"}]}},{"type":"note","title":"","text":"完成后不要急着交：把器材归位、开关断开、游码归零，这些收尾动作也在评分范围内。"},{"type":"h","text":"读数与记录：位数、单位、表格"},{"type":"p","text":"读数前先确认量程与分度值，读数时视线要正对刻度线（或与凹液面最低处、液柱上表面相平），刻度尺还要在分度值下再估读一位；读数后立刻写上单位。记录数据要画表格，表头写成「物理量 / 单位」的形式，如「质量 m / g」「体积 V / cm³」，表格里的数值只写数字、不再重复写单位。数据要如实记录，发现数据与预期不符时先记下来再分析原因，不能涂改或编造。"},{"type":"figure","figure":{"id":"fig-exp-score-4","title":"数据记录表怎么写","caption":"表头写「物理量 / 单位」，数值只写数字","view":"wide","alt":"一张数据记录表，表头是物理量与单位、测量值两列，三行数据分别是质量、体积和密度","prims":[{"t":"rect","x":8,"y":12,"w":84,"h":32,"tone":"main"},{"t":"line","x1":8,"y1":20,"x2":92,"y2":20},{"t":"line","x1":8,"y1":28,"x2":92,"y2":28},{"t":"line","x1":8,"y1":36,"x2":92,"y2":36},{"t":"line","x1":52,"y1":12,"x2":52,"y2":44},{"t":"text","x":30,"y":16,"text":"物理量 / 单位","size":3.4},{"t":"text","x":72,"y":16,"text":"测量值","size":3.4},{"t":"text","x":30,"y":24,"text":"质量 m / g","size":3.4},{"t":"text","x":72,"y":24,"text":"27.0","size":3.4},{"t":"text","x":30,"y":32,"text":"体积 V / cm³","size":3.4},{"t":"text","x":72,"y":32,"text":"10","size":3.4},{"t":"text","x":30,"y":40,"text":"密度 ρ /（g·cm⁻³）","size":3.4},{"t":"text","x":72,"y":40,"text":"2.7","size":3.4},{"t":"text","x":50,"y":52,"text":"数值后面不重复写单位，位数按分度值确定","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":60,"text":"数据要如实记录，不能为了让结论好看而改动","size":3.6,"tone":"danger"}]}},{"type":"note","title":"","text":"常见失分：表格没有单位、读数不带单位、把不需要估读的仪器多写一位（或刻度尺少写估读位）、把测出的数据改成「应该」的数值。"},{"type":"h","text":"结论表述：必须交代控制变量的条件"},{"type":"p","text":"探究性实验的结论有固定句式：在（某个量）一定时，（另一个量）越大（或越小），（结果）越大（或越小）。例如「在接触面粗糙程度一定时，压力越大，滑动摩擦力越大」；写成「压力越大，摩擦力越大」缺了前提，属于表述不完整。测量性实验则要给出数值结果并带上单位，必要时说明多次测量取平均值。表述时不要用绝对化的说法，也不要把实验没研究过的因素写进结论。"},{"type":"figure","figure":{"id":"fig-exp-score-5","title":"结论怎么写","caption":"规范表述要带上控制变量的条件","view":"wide","alt":"左侧方框里是带控制条件的规范结论，右侧方框里是缺少条件的不完整结论","prims":[{"t":"text","x":26,"y":8,"text":"规范表述","size":3.6,"tone":"ok"},{"t":"rect","x":6,"y":12,"w":40,"h":18,"fill":true,"tone":"ok"},{"t":"text","x":26,"y":18,"text":"在压力一定时，接触面越粗糙，","size":3.1},{"t":"text","x":26,"y":25,"text":"滑动摩擦力越大","size":3.1},{"t":"text","x":74,"y":8,"text":"不完整的表述","size":3.6,"tone":"danger"},{"t":"rect","x":54,"y":12,"w":40,"h":18,"fill":true,"tone":"danger"},{"t":"text","x":74,"y":18,"text":"接触面越粗糙，摩擦力越大","size":3.1},{"t":"text","x":74,"y":25,"text":"（缺了控制变量的条件）","size":3.1},{"t":"text","x":50,"y":42,"text":"句式：在……一定时，……越大，……越大","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":52,"text":"只说现象不说条件，通常拿不到结论分","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"结论要有依据：写结论时说明是根据哪两组数据比较得出的，这既是物理的严谨要求，也是评分点。"},{"type":"h","text":"整理器材与安全：最后一步也有分"},{"type":"p","text":"实验结束要整理器材：电学实验先断开开关，把滑动变阻器、导线复位；天平要把砝码用镊子放回砝码盒、游码归零；量筒、烧杯中的水倒掉洗净放回原处；器材摆回原来的位置。安全方面：不使用破损的器材、不把导线直接接在电源两极、不在带电情况下拆改电路、玻璃器皿轻拿轻放。这些收尾动作既反映实验习惯，也是评分表上的条目。"},{"type":"figure","figure":{"id":"fig-exp-score-6","title":"整理器材与安全","caption":"收尾动作也要做出来","view":"wide","alt":"四个方框写着：开关断开、砝码回盒、游码归零、仪器复位","prims":[{"t":"rect","x":6,"y":12,"w":40,"h":16,"fill":true,"tone":"main","label":"开关断开"},{"t":"rect","x":54,"y":12,"w":40,"h":16,"fill":true,"tone":"main","label":"砝码回盒"},{"t":"rect","x":6,"y":34,"w":40,"h":16,"fill":true,"tone":"accent","label":"游码归零"},{"t":"rect","x":54,"y":34,"w":40,"h":16,"fill":true,"tone":"accent","label":"仪器复位"},{"t":"text","x":50,"y":58,"text":"安全：不带电拆改电路、不把导线直接接电源两极、轻拿轻放","size":3.4,"tone":"danger"}]}},{"type":"note","title":"","text":"实验做完不要立刻离开：先按顺序整理，再向评委报告完成情况，这也是操作规范的一部分。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["读数末位的确定","读数的末位由仪器的分度值决定：刻度尺在分度值下再估读一位，其他仪器读到分度值所在位","结果必须带单位 · 适用于所有读数类评分点。做题前的固定动作是先写分度值，再写结果：分度值 1 mm 的刻度尺读到 0.01 cm，分度值 1 mL 的量筒读到 1 mL，感量 0.2 g 的天平读到 0.1 g 位，分度值 0.02 A 的电流表读到 0.01 A。位数与分度值不匹配，即使数值接近也会被扣分。"],["多次测量取平均值","x = (x₁ + x₂ + x₃)/(3)","各次测量单位相同，结果保留到与仪器分度值相称的位数 · 只适用于「同一对象、同一条件」的重复测量，如测同一根金属丝的长度、同一个定值电阻的阻值。属于不同条件的数据不能平均：不同压力下的摩擦力、不同电压下小灯泡的电阻与功率都是不同条件下的结果，平均会掩盖规律或得出没有意义的数。"],["单位配套与换算","同一算式中的单位必须配套：g 配 cm³、kg 配 m³；1 g/cm³ = 1×10³ kg/m³，1 mL = 1 cm³","长度 m、cm、mm；质量 kg、g；体积 m³、cm³、mL · 适用于所有计算类评分点。代入公式前先统一单位：密度用 g 与 cm³ 时结果是 g/cm³，写进答案前再按题目要求换算成 kg/m³；速度、压强、电功率的计算同样要先统一单位。单位漏写或换算错，往往整道题的结果分都拿不到。"]]},{"type":"h","text":"应用 · 考场应用：拿到题目后的第一分钟做什么"},{"type":"note","title":"情境","text":"你抽到的题目是「用天平和量筒测量小石块的密度」，器材已经摆在桌上，评委在旁边准备记录。"},{"type":"note","title":"模型与思路","text":"把第一分钟用来「看题目、认器材、想顺序」：确认实验目的、找出需要的仪器、在心里过一遍操作顺序与读数要求，然后再动手。"},{"type":"list","title":"解答步骤","items":["看题目与器材清单，确认要测的量：质量 m 与体积 V，最后用 ρ = m/V 计算。","检查器材：天平放在水平台上、游码归零、砝码是否齐全；量筒有没有裂纹、分度值是多少。","在心里过一遍顺序：调平天平 → 称石块质量 → 量筒注入适量水读出 V₁ → 石块浸没读 V₂ → 计算 → 整理器材。","向评委说明你准备怎么做，然后按顺序动手，边做边说关键操作（如「游码已归零，现在调平衡螺母」）。"]},{"type":"note","title":"结论","text":"先想后做，可以避免三类高发失分：漏掉器材检查、操作顺序颠倒（先测体积使石块沾水）、读数不按分度值记录。"},{"type":"h","text":"应用 · 考场应用：一次典型扣分的复盘"},{"type":"note","title":"情境","text":"某同学的实验记录：用量筒量取 40 mL 水时俯视读数；用天平称量时用手拿砝码、游码没有归零；读数记成「27」没有单位；结论写成「压力越大摩擦力越大」。"},{"type":"note","title":"模型与思路","text":"每一条失分都能对应到「读数规范、器材使用、数据记录、结论表述」四个观察点，把错误动作与它造成的后果一一对上，就能记住怎么改。"},{"type":"list","title":"解答步骤","items":["俯视读数：读到的体积偏大，量取 40 mL 时实际水量偏少，属读数规范失分。","用手拿砝码、游码未归零：砝码会被污染、零点带着额外质量，测出的质量偏大，属器材使用与操作顺序失分。","记录只写「27」没有单位：无法表达测的是什么，属数据记录失分。","结论缺「在接触面粗糙程度一定时」这个条件：属结论表述失分。"]},{"type":"note","title":"结论","text":"这四处都是「知道却容易忘」的规范动作，考前把它们写成清单逐条自检，比多做几道计算题更能提分。"},{"type":"h","text":"应用 · 实验情境：同一次实验，两种做法的差距"},{"type":"note","title":"情境","text":"甲同学上来就称量石块、再放进量筒测体积，读数随手记在纸上，做完把器材留在桌上就走了；乙同学先检查器材、调平天平，称完质量再测体积，数据填进带单位的表格，最后整理好器材才离开。"},{"type":"note","title":"模型与思路","text":"两人测出的数据可能都很接近，但甲同学在「器材检查、操作顺序、数据记录、整理器材」四个观察点上都可能被扣分。"},{"type":"list","title":"解答步骤","items":["器材检查：甲没有检查游码是否归零，乙做了（并说明了自己的操作）。","操作顺序：甲先测体积使石块沾水，测出的质量偏大、密度偏大；乙先测质量，结果准确。","数据记录：甲没有表格与单位；乙用表头带单位的表格记录，并注明多次测量取平均值。","整理器材：甲没有整理；乙断开电源或归零游码、把器材复位。"]},{"type":"note","title":"结论","text":"结果接近不等于得分相同：实验操作考试评的是过程与规范，把每一步做成看得见、说得清的动作，才是这 10 分的拿分方式。"},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["实验做完了，只要结论正确就能拿满分，过程不规范没关系","评分看的是操作过程：读数不规范、没有记录单位、器材没有整理都会被扣分","实验操作考试由评委现场观察打分，评分点落在看得见的动作上。结果对而过程不规范，通常只能拿到部分分；反过来，过程完整规范即使数据略有偏差，也能拿到大部分分数。"],["记录数据时只写数值就行，单位可以等计算时再统一加","记录时必须写上单位，表格的表头要写成「物理量 / 单位」的形式","没有单位的数据无法表达测的是什么、量级对不对；表头带单位是实验记录的通用规范，评委会把这一条作为独立观察点。"],["任何实验都要多次测量，而且都要取平均值","测量性实验的重复测量取平均值以减小误差；探究性实验是改变条件多次实验以避免偶然性、得出普遍规律","两种「多次」的目的不同，处理方式也不同：测长度、测定值电阻取平均；探究摩擦力、杠杆平衡条件则是改变压力或力臂，靠比较不同条件的数据找规律，不能用平均值代替。"],["数据与预期不一致时，把数据改成符合结论的样子更方便","要如实记录数据，再分析原因（操作、读数或器材问题），必要时重做实验","实验的目的是求真，修改或编造数据是科学态度上的严重问题，也是评分中的大忌。发现异常数据应先保留记录，再检查是不是操作或读数出了问题。"]]},{"type":"table","title":"「结果对」与「做得规范」（同一个实验的两种表现）","head":["比较项","只求结果对","过程可观察、可复现"],"rows":[["器材","拿起就用，不检查","先看量程、分度值与指针是否指零"],["操作顺序","想到哪做到哪","按固定顺序：检查、连接调节、测量、整理"],["读数","数值接近就行，位数随意","按分度值确定位数，刻度尺估读一位"],["记录与结论","随手写在纸上，结论只说现象","带单位的表格与带控制条件的结论"]]},{"type":"table","title":"测量性实验与探究性实验（两类实验对「多次测量」的不同要求）","head":["比较项","测量性实验（测密度、测电阻）","探究性实验（摩擦力、杠杆平衡条件）"],"rows":[["目的","测出一个量的大小","找出量与量之间的规律"],["多次测量的含义","同一条件重复测量","改变条件分别测量"],["数据处理","取平均值减小偶然误差","比较各组数据，不能取平均"],["常见失分","不写单位、位数与分度值不匹配","结论缺控制变量的条件"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["操作过程性评价","这是实验操作考试的主体形式：评委按观察点现场打分。备考的落点是动作清单，例如「调平天平前先游码归零」「读数前先看分度值」「实验结束先断开开关」，把清单背下来并在每次练习中做出来。"],["失分点自查","常见失分集中在四类：器材不检查、顺序颠倒、读数不规范（位数与单位）、结论不完整。练习时可以互查：一人操作、一人对照细则逐条打分，比只做纸面题更有效。"],["规范表述与书面记录","即使以口头或纸面形式作答，也要写清三件事：记录表格的物理量与单位、结论中的控制条件、结果的有效位数。这类要求在笔试的「探究与实验」题里同样适用，两者一起练效果最好。"]]},{"type":"quote","text":"【材料一】某次实验操作测评的片段记录：一名同学用量筒量取 40 mL 水时俯视读数；用托盘天平称量时先放砝码后放物体，并且用手拿取砝码；用弹簧测力计拉木块测滑动摩擦力时没有保持匀速；测量结束后没有把游码归零，也没有整理器材。\n【材料二】评分通常把一次实验分成器材检查、操作顺序、读数规范、数据记录、结论表述、整理器材与安全等若干观察点，评委在操作过程中逐项观察记录，最后汇总给分。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】材料一中量取 40 mL 水时俯视读数，读到的体积比实际体积偏大还是偏小？实际量到的水比 40 mL 多还是少？（3 分）","【设问】用手拿取砝码有什么问题？为什么必须用镊子？天平称量的正确顺序是什么？（4 分）","【设问】材料一中「拉木块时不匀速」为什么会影响结论？应怎样改进？（3 分）"]}],"questions":[{"id":"phy-experiment-7-q1","type":"choice","stem":"关于实验操作考试的要求，下列说法正确的是","answer":"C","explain":"C 正确：整理器材与安全操作本身就是观察点，收尾动作也要做出来。A 错：操作顺序是独立评分项，顺序颠倒（如先测体积后称质量）会既扣顺序分又使结果偏大。B 错：记录数据必须带单位，表格表头要写成「物理量 / 单位」的形式。D 错：位数要与分度值匹配、结果必须带单位，这两点都是常见的独立扣分项。","options":["只要最终结果正确，操作顺序不会影响得分","记录数据时可以先只写数值，单位在计算时统一加上","实验结束后应把仪器整理复位：断开开关、砝码放回盒中、游码归零","读数只要接近规范值就可以，位数与单位不重要"],"difficulty":1,"tags":["评分要点","操作规范"]},{"id":"phy-experiment-7-q2","type":"choice","stem":"关于实验中「多次测量」的做法，下列说法正确的是","answer":"A","explain":"A 正确：测量性实验（测密度、测电阻）是同一条件下的重复测量，取平均值减小偶然误差；探究性实验（摩擦力、杠杆平衡条件）是改变条件分别测量，靠比较不同条件的数据找规律。B 错：探究性实验取平均会把要找的规律抹掉。C 错：两类实验都需要多次测量，只是含义不同。D 错：不同条件的数据平均后没有物理意义，不能提高结论的可靠性。","options":["测量性实验重复测量取平均值是为了减小偶然误差；探究性实验改变条件多次测量是为了避免偶然性、得出普遍规律","两类实验都要把数据取平均值","两类实验都不需要多次测量","探究性实验取平均值可以减小误差、提高结论的可靠性"],"difficulty":2,"tags":["多次测量","实验方法"]},{"id":"phy-experiment-7-q3","type":"choice","stem":"下列关于读数与记录的做法，正确的是","answer":"B","explain":"B 正确：这是读数类观察点的完整要求——先看量程与分度值（决定读数末位）、视线规范、结果带单位，刻度尺还要再估读一位。A 错：刻度尺必须估读，例如分度值 1 mm 时要写成 2.70 cm 而不是 2.7 cm。C 错：量筒读数时视线必须与凹液面最低处相平，俯视读数偏大、仰视偏小。D 错：测力计使用前要检查并调节指针到零位，否则每次读数都带着同一个零点误差。","options":["刻度尺读数读到分度值即可，不需要估读","读数前先看清量程和分度值，读数后写上单位；刻度尺要估读到分度值的下一位","量筒读数时视线可以随意，只要把数值记准就行","弹簧测力计使用前不必检查指针是否指在零刻度线"],"difficulty":1,"tags":["读数规范","数据记录"],"figure":{"id":"fig-exp-score-q3","title":"读数位数由分度值决定","caption":"刻度尺要估读一位，量筒读到分度值所在位","view":"wide","alt":"左边是分度值 1 毫米的刻度尺读数，不规范地记成 2.7 厘米，规范地记成 2.70 厘米；右边是量筒，水面在 42 毫升处，读到分度值 1 毫升","prims":[{"t":"text","x":50,"y":8,"text":"读数位数：先看分度值，再定末位","size":3.6,"tone":"muted"},{"t":"rect","x":6,"y":12,"w":40,"h":18,"fill":true,"tone":"danger"},{"t":"text","x":26,"y":18,"text":"2.7 cm","size":4,"tone":"danger"},{"t":"text","x":26,"y":25,"text":"少了估读位","size":3.2,"tone":"danger"},{"t":"rect","x":54,"y":12,"w":40,"h":18,"fill":true,"tone":"ok"},{"t":"text","x":74,"y":18,"text":"2.70 cm","size":4,"tone":"ok"},{"t":"text","x":74,"y":25,"text":"末位 0 是估读位","size":3.2,"tone":"ok"},{"t":"beaker","x":12,"y":36,"w":20,"h":20,"fill":0.6},{"t":"text","x":36,"y":45,"text":"42 mL","anchor":"start","size":3.4,"tone":"accent"},{"t":"text","x":58,"y":45,"text":"量筒分度值 1 mL","anchor":"start","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":61,"text":"位数与分度值不匹配是最常见的读数失分","size":3.4,"tone":"accent"}]}},{"id":"phy-experiment-7-q4","type":"choice","stem":"实验中发现测得的数据与预期不一致，最恰当的做法是","answer":"D","explain":"D 正确：实验的目的是求真，如实记录是基本的科学态度；数据异常时先检查操作、读数与器材，再决定是否重做。A 错：修改数据是编造实验结果，属于严重问题。B 错：随意舍弃数据等于掩盖问题，除非能明确说明是操作错误造成的，并记录原因。C 错：抄别人的数据既不能反映自己的操作水平，也无法发现问题。","options":["把数据改成与结论一致，保证结论成立","直接舍弃这组数据，不写进记录表","照抄同组同学的数据","如实记录数据，分析可能的原因（操作、读数或器材），必要时重做实验"],"difficulty":1,"tags":["科学态度","数据处理"]},{"id":"phy-experiment-7-q5","type":"fill","stem":"某同学用分度值为 1 mm 的刻度尺测得物体的长度是 2.7 cm，并把它记在表格里。这个记录不规范，规范记录应写成 ______ cm。","answer":"2.70|2.70 cm","explain":"为什么不规范：分度值 1 mm = 0.1 cm，准确值读到 0.1 cm，还要在分度值下再估读一位，即读到 0.01 cm，所以应写成 2.70 cm。末位的 0 表示估读到 0.1 mm 这一位，不能省略。这类「位数与分度值不匹配」的失分在读数类观察点里出现频率很高：刻度尺少一位、量筒或天平多一位都要扣分。","difficulty":2,"tags":["读数规范","刻度尺"]},{"id":"phy-experiment-7-q6","type":"fill","stem":"用天平和量筒测小石块密度，测得质量为 27 g、体积为 10 cm³，写出完整的计算结果：ρ = ______ kg/m³。","answer":"2700|2.7×10³|2700 kg/m³|2.7×10³","explain":"为什么这样算：先按配套单位求密度，ρ = m/V = 27 g ÷ 10 cm³ = 2.7 g/cm³；再换算单位，1 g/cm³ = 1×10³ kg/m³，得 2.7×10³ kg/m³，也就是 2700 kg/m³。作答时要注意两点：一是必须带单位，只写 2700 无法说明单位；二是换算不要照抄数字，把 2.7 直接写成 kg/m³ 是常见错误。","difficulty":2,"tags":["密度计算","单位换算"]},{"id":"phy-experiment-7-q7","type":"short","stem":"某小组测小石块的密度：用天平称得小石块的质量为 54 g；在 50 mL 量筒中先注入 20 mL 水，把小石块用细线系好完全浸没后，水面升到 40 mL。(1) 求小石块的体积；(2) 求小石块的密度，分别用 g/cm³ 与 kg/m³ 表示。","answer":"(1) V = V₂ − V₁ = 40 mL − 20 mL = 20 mL = 20 cm³。(2) ρ = m/V = 54 g ÷ 20 cm³ = 2.7 g/cm³ = 2.7×10³ kg/m³。","explain":"为什么这样做：体积用排水法的两次读数之差，读数时量筒要放平、视线与凹液面最低处相平，石块要完全浸没；密度用 ρ = m/V，代入前保证单位配套（g 与 cm³），最后再换算成国际单位。答题时每一步都要写清：先写关系式，再代数，最后写结果并带单位——这正是「分步给分」的写法。若先测体积再称质量，石块沾水会使质量偏大、密度偏大，这是操作顺序上的失分点。","difficulty":2,"tags":["综合计算","密度"],"rubric":["写出体积关系式 V = V₂ − V₁ 并算出 20 cm³（1 分）","写出密度公式 ρ = m/V（1 分）","算出 2.7 g/cm³ 并带单位（1 分）","正确换算成 2.7×10³ kg/m³（1 分）"],"steps":["写出体积关系式：V = V₂ − V₁。","代入：V = 40 mL − 20 mL = 20 mL，并换算成 20 cm³。","写出密度公式：ρ = m/V。","代入：ρ = 54 g ÷ 20 cm³ = 2.7 g/cm³。","换算单位并作答：2.7 g/cm³ = 2.7×10³ kg/m³。"]},{"id":"phy-experiment-7-q8","type":"short","stem":"为什么要按「先检查器材、再连接或调节、后测量、最后整理」的顺序做实验？请结合天平称量或电学实验中的一个例子，说明不规范顺序会带来什么后果，并写出整理器材的三条要求。","answer":"按固定顺序做，可以避免三类问题：一是用有问题的器材或带着错误的零点去测量，数据从一开始就不可靠；二是操作互相干扰，使测量值带上系统偏差；三是操作不安全，可能损坏器材。举例：天平如果先把物体放上去再调平衡螺母，或者称量前游码没有归零，调出的零点就带着一个额外质量，测出的质量偏大；电学实验中如果闭合开关后再接线，一旦接错就会短路，可能烧坏电流表或电源，所以必须断开开关接线、并把滑动变阻器的滑片调到阻值最大处。整理器材的三条要求：断开开关（电学）、把砝码用镊子放回砝码盒并把游码归零（天平）、把仪器与导线复位、玻璃器皿洗净放回原处。","explain":"为什么这样答：实验操作考试的观察点落在顺序上，而不是落在「有没有做对结果」上。回答这类题要用「如果……就会……」的因果句式，把错误顺序与后果对应起来：天平对应零点误差，电学对应短路与器材损坏。整理器材的要求要具体到动作（断开开关、砝码回盒、游码归零、仪器复位），只写「整理好器材」不能得分。","difficulty":3,"tags":["操作顺序","实验说理"],"rubric":["答出检查器材的必要性：避免用有问题的器材或带错误零点测量（1 分）","举出天平的例子并说明后果（游码未归零或顺序颠倒使质量偏大）（1 分）","举出电学实验的例子并说明后果（闭合开关接线可能短路、损坏器材）（1 分）","写出整理器材的具体要求（断开开关、砝码回盒、游码归零、仪器复位中答出三条）（1 分）"]},{"id":"phy-experiment-7-q9","type":"short","stem":"请把实验操作考试的一般流程画成流程图，要求包含四个环节，并在每个环节旁写出一条最容易失分的地方。","answer":"见参考答案图：检查器材（容易漏掉：不检查量程、分度值与指针是否指零）→ 连接或调节（容易漏掉：开关没断开、滑片没调到阻值最大处、天平游码没归零）→ 测量读数（容易漏掉：读数位数与分度值不匹配、视线不规范、不写单位）→ 整理器材（容易漏掉：砝码没回盒、游码没归零、开关没断开、仪器没复位）。","explain":"作图要点：① 四个环节用方框表示、用箭头连成流程，箭头的方向要体现先后顺序；② 每个环节旁边写一条最容易失分的地方，写「动作」而不是写「要注意」；③ 流程图要能当自检清单用，考试前按它逐条过一遍。把这张图与前面六个必做实验的要点对照记忆，实验操作考试的 10 分就有了稳定的抓手。","difficulty":2,"tags":["作图","自检清单"],"rubric":["四个环节用方框表示，箭头体现先后顺序（检查器材 → 按步骤操作 → 读数记录 → 整理器材）","每个环节旁写出一条最容易失分的地方","写的是具体动作（如「读数时视线与凹液面最低处相平」），不是「要注意」这类空话","流程图能直接当考前自检清单用，逐条可对照"],"answerFigure":{"id":"fig-exp-score-ans1","title":"参考答案：实验流程与易失分处","caption":"四个环节与对应的常见失分","view":"wide","alt":"流程图有四个环节：检查器材、连接调节、测量读数、整理器材，每个环节下面写着一条常见失分","prims":[{"t":"rect","x":4,"y":8,"w":21,"h":12,"fill":true,"tone":"main","label":"检查器材"},{"t":"arrow","x1":26,"y1":14,"x2":30,"y2":14,"tone":"accent"},{"t":"rect","x":31,"y":8,"w":21,"h":12,"fill":true,"tone":"main","label":"连接调节"},{"t":"arrow","x1":53,"y1":14,"x2":57,"y2":14,"tone":"accent"},{"t":"rect","x":58,"y":8,"w":19,"h":12,"fill":true,"tone":"accent","label":"测量读数"},{"t":"arrow","x1":78,"y1":14,"x2":82,"y2":14,"tone":"accent"},{"t":"rect","x":83,"y":8,"w":15,"h":12,"fill":true,"tone":"accent","label":"整理器材"},{"t":"text","x":14,"y":28,"text":"不看量程与分度值","size":3.2,"tone":"danger"},{"t":"text","x":41,"y":28,"text":"开关没断开、游码没归零","size":3.2,"tone":"danger"},{"t":"text","x":67,"y":28,"text":"位数与单位不规范","size":3.2,"tone":"danger"},{"t":"text","x":90,"y":28,"text":"砝码没回盒","size":3.2,"tone":"danger"},{"t":"text","x":50,"y":42,"text":"每一步都要做成看得见的规范动作","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":52,"text":"先检查、再连接调节、后测量、最后整理","size":3.6,"tone":"muted"}]}},{"id":"phy-experiment-7-m1-q1","type":"short","stem":"材料一中量取 40 mL 水时俯视读数，读到的体积比实际体积偏大还是偏小？实际量到的水比 40 mL 多还是少？（3 分）","answer":"俯视时视线斜向下，看到的刻度在液面实际位置的上方，读到的体积偏大；因此当读数显示 40 mL 时就停止加水，实际的水还没有到 40 mL，量到的水比 40 mL 少。","explain":"","tags":["读数规范","量筒"],"rubric":["答出读数偏大（1 分）","说明视线斜向下、看到的刻度偏上（1 分）","推出实际量到的水少于 40 mL（1 分）"]},{"id":"phy-experiment-7-m1-q2","type":"short","stem":"用手拿取砝码有什么问题？为什么必须用镊子？天平称量的正确顺序是什么？（4 分）","answer":"用手拿砝码，手上的汗渍、油脂会沾在砝码上，使砝码的质量发生变化（也会腐蚀砝码），造成测量结果不准确，所以必须用镊子夹取。天平称量的正确顺序是：把天平放在水平台上，把游码移到标尺左端的零刻度线，调节平衡螺母使横梁平衡；左盘放物体、右盘放砝码（用镊子夹取，先大后小），最后移动游码使横梁重新平衡；读数等于砝码总质量加游码示数；称量完毕把砝码放回盒中、游码归零。","explain":"","tags":["托盘天平","操作规范"],"rubric":["答出手上的汗渍、油脂会污染或腐蚀砝码、影响质量（1 分）","答出用镊子夹取砝码（1 分）","写出放平、游码归零、调平衡螺母的调平顺序（1 分）","写出左物右码、读数规则与称量后的整理（1 分）"]},{"id":"phy-experiment-7-m1-q3","type":"short","stem":"材料一中「拉木块时不匀速」为什么会影响结论？应怎样改进？（3 分）","answer":"用弹簧测力计拉木块测滑动摩擦力，靠的是二力平衡：只有木块做匀速直线运动时，水平方向上的拉力与滑动摩擦力才大小相等，测力计的示数才等于摩擦力。不匀速时拉力与摩擦力不平衡，示数不等于摩擦力，测出的数据不能用。改进办法：把弹簧测力计的一端固定，另一端拉住木块，改用手拉动下面的木板，让木块保持静止，这样测力计的示数就等于滑动摩擦力，而且不必要求木板匀速运动，读数更稳定。","explain":"","tags":["摩擦力实验","实验改进"],"rubric":["说明只有匀速直线运动时才满足二力平衡、示数等于摩擦力（1 分）","指出不匀速会使测出的数据无效（1 分）","写出改进办法：拉动木板、木块静止（1 分）"]}]}];
